INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C1','kor',5,2,'u1',1,'인상적인 부분의 뜻 — 작품을 읽으며 마음이 움직이거나 궁금증 · 깨달음이 생기는 부분으로, 내 경험이 떠오르는 곳이나 기억에 남는 문장도 인상적인 부분이 된다',ARRAY['6국05-04 문학']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C2','kor',5,2,'u1',1,'사람마다 다른 인상적인 부분 — 같은 작품을 읽어도 마음에 남는 부분은 사람마다 다를 수 있어서, 인상적인 부분에는 하나로 정해진 정답이 없다',ARRAY['6국05-04 문학']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C3','kor',5,2,'u1',1,'부분과 까닭은 한 짝 — 인상적인 부분은 아무 곳이나 고르는 것이 아니라 그 부분이 인상적인 까닭을 작품 속 말이나 내 경험과 이어서 함께 말해야 서로의 생각을 알 수 있다',ARRAY['6국05-04 문학']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C4','kor',5,2,'u1',1,'시와 이야기에서 살필 것 — 시에서는 표현 · 말하는 이의 마음 · 분위기를, 이야기에서는 인물 · 사건 · 때와 곳, 인물의 말과 행동, 사건의 흐름을 살피며 인상적인 부분을 찾는다',ARRAY['6국05-04 문학']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C5','kor',5,2,'u1',1,'단원의 흐름 — 시를 읽고 까닭을 들어 인상적인 부분을 말하고 → 시에 대한 의견을 나누고 → 이야기로 넓힌 뒤 → 서평을 쓰고 → 우리 반 「이달의 책」을 고른다',ARRAY['6국05-04 문학']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C6','kor',5,2,'u1',2,'시를 여러 번 읽고 내용 · 주제 알기 — 시는 여러 번 읽으며 장면을 떠올리고, 무엇을 말하는지(내용)와 말하는 이가 가장 전하고 싶은 생각(주제)을 찾는다',ARRAY['6국05-04 문학']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C7','kor',5,2,'u1',2,'독특하고 재미있는 표현 — 흉내 내는 말 · 빗대어 나타낸 말처럼 독특하고 재미있는 표현은 인상적인 부분이 되기 쉬우며, 그 표현이 어떤 느낌을 주는지까지 말한다',ARRAY['6국05-04 문학']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C8','kor',5,2,'u1',2,'경험과 이어지는 공감 — 시 속 일이 내가 겪은 일과 닮아 「나도 그랬지」 하고 공감되는 부분도 인상적인 부분이며, 그때 떠오른 내 경험이 곧 까닭이 된다',ARRAY['6국05-04 문학']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C9','kor',5,2,'u1',2,'주제가 잘 드러나는 부분 — 말하는 이가 하고 싶은 말이 또렷이 드러나거나 특별한 생각이 들게 하는 부분도 인상적인 부분이며, 제목만으로는 주제를 다 알 수 없어 시 전체를 읽고 찾는다',ARRAY['6국05-04 문학']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C10','kor',5,2,'u1',2,'마음과 분위기도 인상적인 부분 — 인상적인 부분은 한 구절에만 머물지 않아 말하는 이의 마음이나 시 전체의 분위기처럼 시 전체에서 느낀 것도 인상적인 부분이 된다',ARRAY['6국05-04 문학']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C11','kor',5,2,'u1',2,'빗댄 표현을 경험과 이어 읽기 — 「말은 마음에 찍히는 발자국」처럼 빗대어 나타낸 표현은 글자 그대로가 아니라 닮은 점(말이 마음에 남는다)을 찾아, 내 경험이나 배경지식과 이어 이해한다',ARRAY['6국05-04 문학']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C12','kor',5,2,'u1',2,'느낌을 살려 낭송하기 — 인상적인 부분의 느낌이 살도록 빠르기 · 목소리 크기 · 쉬는 곳을 바꾸어 낭송하며, 모두 같은 소리로 크게만 읽는 것이 아니다',ARRAY['6국05-04 문학']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C13','kor',5,2,'u1',4,'공감하며 읽은 시 소개하기 — 수업이나 도서관에서 읽은 시 가운데 공감한 시를 골라 어떤 시인지와 공감한 까닭을 친구에게 소개하며, 꼭 똑같은 일을 겪지 않아도 비슷한 마음을 느껴 보았으면 공감할 수 있다',ARRAY['6국05-04 문학']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C14','kor',5,2,'u1',4,'낱말의 뜻을 알고 읽기 — 모르는 낱말은 앞뒤 문장으로 짐작하고 뜻을 확인하며 읽고(괜스레 — 까닭이나 실속 없이), 낱말을 넣어 문장을 만들어 본다',ARRAY['6국05-04 문학']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C15','kor',5,2,'u1',4,'말하는 이의 마음 흐름 — 시 속 말하는 이의 마음은 처음부터 끝까지 같지 않을 수 있어서(속상함 → 답답함 → 스스로 달래기), 연마다 행동과 말이 어떻게 바뀌는지 따라가며 읽는다',ARRAY['6국05-04 문학']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C16','kor',5,2,'u1',4,'마음 흐름에 맞춘 낭송 — 마음이 바뀌는 곳에서 빠르기와 강약을 바꾸고, 모둠이 연을 나누어 맡아 이어 읽으며 시의 분위기를 살린다',ARRAY['6국05-04 문학']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C17','kor',5,2,'u1',4,'까닭이 다른 까닭 — 친구마다 경험 · 관심사 · 배경지식이 달라 같은 시에서도 인상적인 부분과 그 까닭이 다를 수 있으며, 그렇다고 어느 한쪽이 잘못 읽은 것은 아니다',ARRAY['6국05-04 문학']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C18','kor',5,2,'u1',4,'경청하며 의견 나누기 — 친구의 의견을 끝까지 듣고 나와 같은 점 · 다른 점을 찾으면 미처 생각하지 못한 관점으로 작품을 다시 보게 되어 생각이 넓어진다',ARRAY['6국01-06 듣기·말하기']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C19','kor',5,2,'u1',4,'그림으로 감상 넓히기 — 다른 시를 한 편 더 읽고 인상적인 부분을 그림으로 그린 뒤 그 부분을 고른 까닭을 말하며, 그림은 잘 그렸는지가 아니라 무엇을 왜 골랐는지가 중요하다',ARRAY['6국05-04 문학']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C20','kor',5,2,'u1',7,'전기문의 뜻 — 전기문은 실제로 살았던 인물의 삶을 사실에 근거하여 쓴 글로, 인물이 겪은 일 · 한 일 · 생각을 알려 주어 감동과 교훈을 준다',ARRAY['6국05-04 문학']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C21','kor',5,2,'u1',7,'사실과 다시 꾸민 부분 — 전기문의 사건은 대체로 역사적 사실에 바탕을 두지만 인물이 한 말이나 행동은 작가가 상상하거나 다시 꾸며 표현한 것일 수 있어, 사실과 꾸민 부분을 가려 읽는다',ARRAY['6국05-04 문학']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C22','kor',5,2,'u1',7,'시대적 상황 알기 — 이야기 속 인물이 살았던 때와 곳(나라를 빼앗긴 일제 강점기처럼)을 알아야 인물이 왜 그런 일을 했는지 이해할 수 있다',ARRAY['6국05-04 문학']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C23','kor',5,2,'u1',7,'처한 상황과 말 · 행동 잇기 — 인물이 처한 상황과 그때 한 말이나 행동을 이어 보면 인물의 마음과 생각이 보이며, 말 · 행동만 떼어 보면 그 뜻을 놓친다',ARRAY['6국05-04 문학']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C24','kor',5,2,'u1',7,'이야기에서 인상적인 부분 — 이야기에서는 사건의 흐름 · 인물의 변화 · 기억에 남는 말이나 행동이 인상적인 부분이 되기 쉽고, 이야기의 주제나 분위기도 인상적인 부분이 된다',ARRAY['6국05-04 문학']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C25','kor',5,2,'u1',7,'인상적인 부분으로 질문 만들기 — 인상적인 부분을 중심으로 인물에게 하고 싶은 질문(「그때 무섭지 않았나요?」)을 만들어 친구와 묻고 답하면 인물의 마음에 더 깊이 공감한다',ARRAY['6국05-04 문학']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C26','kor',5,2,'u1',7,'인물의 삶과 나의 삶 — 전기문 속 인물의 삶에서 본받을 점을 찾고 지금 우리의 삶과 이어 보면, 옛사람의 이야기도 오늘의 나에게 뜻이 있음을 알게 된다',ARRAY['6국05-04 문학']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C27','kor',5,2,'u1',10,'서평의 뜻 — 서평은 책을 읽고 그 책에 대한 자신의 의견이나 평가를 까닭과 함께 밝힌 글이다',ARRAY['6국05-04 문학']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C28','kor',5,2,'u1',10,'서평에 들어갈 내용 — 서평에는 제목 · 책 소개(제목 · 지은이 · 대상 독자 · 주제) · 줄거리 · 인상적인 부분과 그 까닭 · 책에 대한 평가가 들어간다',ARRAY['6국05-04 문학']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C29','kor',5,2,'u1',10,'줄거리는 간단히 — 서평의 줄거리는 일어난 일 가운데 중요한 일만 골라 차례대로 간단히 쓰며, 서평의 중심은 줄거리가 아니라 인상적인 부분과 평가다',ARRAY['6국05-04 문학']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C30','kor',5,2,'u1',10,'평가 — 좋은 점 · 아쉬운 점 · 추천 — 평가에는 좋은 점뿐 아니라 아쉬운 점도 까닭과 함께 쓸 수 있고, 누구에게 왜 추천하는지를 쓴다',ARRAY['6국05-04 문학']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C31','kor',5,2,'u1',10,'독서 감상문과 서평 — 독서 감상문은 책을 읽고 떠오른 생각이나 느낌을 자유롭게 쓴 글이고, 서평은 책의 좋은 점이나 아쉬운 점을 평가하고 그렇게 생각한 까닭을 함께 밝힌 글이다',ARRAY['6국05-04 문학']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C32','kor',5,2,'u1',10,'서평의 제목 붙이기 — 서평의 제목은 책 제목을 그대로 옮기기보다 읽을 사람의 관심을 끌고 책의 핵심 내용이나 내 평가가 드러나게 붙인다',ARRAY['6국05-04 문학']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C33','kor',5,2,'u1',10,'계획하고 쓰고 고쳐 쓰기 — 쓸 내용을 칸마다 정리해 계획하고, 「이 책이 재미있는 까닭은?」처럼 스스로 물으며 쓴 뒤, 친구와 돌려 읽고 받은 의견으로 고쳐 쓴다',ARRAY['6국05-04 문학']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C34','kor',5,2,'u1',12,'추천할 책과 까닭 정리하기 — 「이달의 책」에 어울리는 조건(흥미로운 이야기 · 교훈을 주는 이야기)을 생각해 추천할 책과 추천하는 까닭, 인상적인 부분을 정리하며, 너무 어렵거나 한 분야에만 치우친 책은 피한다',ARRAY['6국05-04 문학']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C35','kor',5,2,'u1',12,'의견 견주기 — 모둠 친구들의 추천 까닭을 끝까지 듣고 같은 점과 다른 점을 견주어 정리한다',ARRAY['6국01-06 듣기·말하기']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C36','kor',5,2,'u1',12,'기준을 세워 조정하기 — 의견이 갈리면 「반 친구들에게 두루 도움이 되는가」처럼 함께 정한 기준에 대어 견주고 조정해 고르며, 목소리 크기나 말한 차례로 정하지 않는다',ARRAY['6국01-06 듣기·말하기']::text[],36) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C37','kor',5,2,'u1',12,'뽑히지 않은 의견도 존중 — 토의는 의견을 견주고 조정하는 과정이어서 뽑히지 않은 책의 추천 까닭도 친구들이 새 책을 알게 하고 다음 후보가 될 수 있으므로, 다양한 의견을 인정한다',ARRAY['6국01-06 듣기·말하기']::text[],37) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C38','kor',5,2,'u1',12,'소개 자료 만들기 — 고른 책은 간단한 소개 · 추천 까닭 · 인상적인 문장을 모아 광고지나 발표 자료로 만들어 반 친구들에게 알린다',ARRAY['6국05-04 문학']::text[],38) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C39','kor',5,2,'u1',14,'인상적인 문장 — 인상적인 문장은 어렵고 긴 문장이 아니라 마음이 움직이거나 깨달음이 생긴 문장이어서, 짧고 쉬운 문장도 내 경험과 이어지면 가장 인상적인 문장이 된다',ARRAY['6국05-04 문학']::text[],39) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C40','kor',5,2,'u1',14,'분류하다 · 분석하다 · 분배하다 — 분류하다(기준에 따라 종류별로 나누거나 묶다) · 분석하다(복잡한 것을 부분으로 나누어 자세히 살피다) · 분배하다(몫으로 나누어 주다)는 모두 「나누다」와 관계있지만 쓰이는 곳이 다르다 (기초 다지기)',ARRAY['기초 다지기(낱말)']::text[],40) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X01','kor',5,'u1',ARRAY['K5-2-u1-C1']::text[],'인상적인 부분을 글자 수가 많거나 어려운 낱말이 든 부분으로 여긴다','마음이 움직인 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X02','kor',5,'u1',ARRAY['K5-2-u1-C2']::text[],'작품의 인상적인 부분에는 하나로 정해진 정답이 있다고 여긴다','사람마다 다를 수 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X03','kor',5,'u1',ARRAY['K5-2-u1-C3']::text[],'인상적인 부분을 고르고 「그냥 좋아서」처럼 까닭을 말하지 않는다','부분과 까닭은 한 짝') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X04','kor',5,'u1',ARRAY['K5-2-u1-C3','K5-2-u1-C2']::text[],'정답이 없으니 작품과 이어지지 않는 아무 까닭이나 대도 된다고 여긴다','까닭은 작품과 이어져야') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X05','kor',5,'u1',ARRAY['K5-2-u1-C4','K5-2-u1-C5']::text[],'시와 이야기에서 살필 것을 헷갈리거나, 단원의 활동 차례를 거꾸로 안다','시 → 이야기 → 서평') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X06','kor',5,'u1',ARRAY['K5-2-u1-C6']::text[],'시를 한 번 훑어 읽고 내용과 주제를 다 알았다고 여긴다','여러 번 읽어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X07','kor',5,'u1',ARRAY['K5-2-u1-C10']::text[],'인상적인 부분은 멋진 구절 하나뿐이라 여겨, 말하는 이의 마음이나 분위기는 인상적인 부분이 될 수 없다고 본다','시 전체에서 느낀 것도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X08','kor',5,'u1',ARRAY['K5-2-u1-C8','K5-2-u1-C13']::text[],'내 경험이 떠올라 고른 부분은 작품과 관계없는 내 이야기라서 까닭이 될 수 없다고 여긴다','「나도 그랬지」도 까닭') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X09','kor',5,'u1',ARRAY['K5-2-u1-C11','K5-2-u1-C7']::text[],'빗대어 나타낸 표현을 글자 그대로 받아들인다(말이 정말 발자국을 남긴다)','닮은 점을 찾아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X10','kor',5,'u1',ARRAY['K5-2-u1-C12','K5-2-u1-C16']::text[],'낭송은 모든 줄을 같은 빠르기로 크게만 읽으면 된다고 여긴다','느낌 따라 빠르기 · 강약') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X11','kor',5,'u1',ARRAY['K5-2-u1-C9','K5-2-u1-C6']::text[],'시의 주제는 제목만 보면 다 알 수 있다고 여겨 시 전체를 살피지 않는다','시 전체에서 찾아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X12','kor',5,'u1',ARRAY['K5-2-u1-C13']::text[],'공감은 시와 똑같은 일을 겪어 본 사람만 할 수 있다고 여긴다','비슷한 마음이면 돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X13','kor',5,'u1',ARRAY['K5-2-u1-C14']::text[],'모르는 낱말을 짐작하거나 확인하지 않고 넘어가 뜻을 잘못 안다(괜스레 → 괜찮게)','앞뒤 문장으로 짐작') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X14','kor',5,'u1',ARRAY['K5-2-u1-C15']::text[],'말하는 이의 마음은 시의 처음부터 끝까지 같다고 여긴다','연마다 따라가요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X15','kor',5,'u1',ARRAY['K5-2-u1-C17']::text[],'친구와 인상적인 부분이 다르면 둘 가운데 한 사람은 잘못 읽은 것이라 여긴다','경험 · 관심사 · 배경지식') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X16','kor',5,'u1',ARRAY['K5-2-u1-C18','K5-2-u1-C35']::text[],'친구의 의견을 끝까지 듣지 않거나, 나와 다르면 바로 깎아내린다','끝까지 듣고 견줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X17','kor',5,'u1',ARRAY['K5-2-u1-C19']::text[],'그림으로 감상할 때 잘 그렸는지가 가장 중요하다고 여긴다','무엇을 왜 골랐나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X18','kor',5,'u1',ARRAY['K5-2-u1-C20']::text[],'전기문을 지어낸 인물의 이야기로 여기거나, 사실을 담은 글이라 감동은 주지 못한다고 여긴다','실제 인물 · 사실 바탕') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X19','kor',5,'u1',ARRAY['K5-2-u1-C21']::text[],'전기문 속 인물의 말과 행동은 모두 그날 그대로 받아 적은 것이라 여긴다','다시 꾸몄을 수도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X20','kor',5,'u1',ARRAY['K5-2-u1-C22']::text[],'인물이 살았던 시대의 상황을 몰라도 인물이 한 일을 이해할 수 있다고 여긴다','때와 곳을 알아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X21','kor',5,'u1',ARRAY['K5-2-u1-C23']::text[],'인물의 말 · 행동을 처한 상황과 잇지 않고 따로 떼어 본다','상황 + 말 · 행동') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X22','kor',5,'u1',ARRAY['K5-2-u1-C24']::text[],'이야기에서 인상적인 부분은 가장 큰 사건 한 장면뿐이라 여긴다','흐름 · 변화 · 말 · 분위기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X23','kor',5,'u1',ARRAY['K5-2-u1-C25']::text[],'인물에게 하는 질문을 인상적인 부분과 관계없이 글에 답이 그대로 적힌 것만 만든다','인상적인 부분에서 출발') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X24','kor',5,'u1',ARRAY['K5-2-u1-C26']::text[],'옛날 인물의 이야기는 지금의 나와 아무 관계가 없다고 여긴다','본받을 점 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X25','kor',5,'u1',ARRAY['K5-2-u1-C29','K5-2-u1-C28']::text[],'서평은 책의 줄거리를 처음부터 끝까지 자세히 쓰는 글이라 여긴다','줄거리는 간단히') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X26','kor',5,'u1',ARRAY['K5-2-u1-C30']::text[],'서평에는 책의 좋은 점만 써야 한다고 여긴다','아쉬운 점도 까닭과 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X27','kor',5,'u1',ARRAY['K5-2-u1-C31','K5-2-u1-C27']::text[],'서평과 독서 감상문을 같은 글로 여긴다','평가와 까닭이 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X28','kor',5,'u1',ARRAY['K5-2-u1-C27','K5-2-u1-C30']::text[],'서평의 평가를 「재미있다」처럼 까닭 없이 쓴다','왜 그렇게 평가했나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X29','kor',5,'u1',ARRAY['K5-2-u1-C32']::text[],'서평의 제목은 책 제목을 그대로 쓰면 된다고 여긴다','관심 · 핵심이 드러나게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X30','kor',5,'u1',ARRAY['K5-2-u1-C33']::text[],'서평을 한 번 쓰면 고쳐 쓸 필요가 없다고 여기거나 친구의 의견을 받지 않는다','돌려 읽고 고쳐 써요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X31','kor',5,'u1',ARRAY['K5-2-u1-C34']::text[],'내가 좋아하는 책이면 어렵거나 한 분야에 치우쳐도 반 친구 모두에게 맞는 「이달의 책」이라 여긴다','반 친구들의 눈으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X32','kor',5,'u1',ARRAY['K5-2-u1-C36']::text[],'의견이 갈리면 목소리가 큰 쪽이나 먼저 말한 쪽으로 정한다','함께 정한 기준에 대어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X33','kor',5,'u1',ARRAY['K5-2-u1-C37']::text[],'내가 추천한 책이 뽑히지 않으면 내 의견은 쓸모없었다고 여긴다','견주고 조정하는 과정') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X34','kor',5,'u1',ARRAY['K5-2-u1-C38']::text[],'소개 자료에는 책 제목만 크게 쓰면 된다고 여긴다','소개 · 까닭 · 문장') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X35','kor',5,'u1',ARRAY['K5-2-u1-C39']::text[],'인상적인 문장은 길고 어려운 낱말이 많은 문장이어야 한다고 여긴다','짧고 쉬운 문장도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X36','kor',5,'u1',ARRAY['K5-2-u1-C40']::text[],'분류하다 · 분석하다 · 분배하다의 뜻을 헷갈려 바꾸어 쓴다','묶기 · 살피기 · 나눠 주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L01_basic#1','kor',5,2,'u1','L01','g5_2_kor_u1_L01_basic','lesson_basic','K5-2-u1-C1',1,'mc','auto','작품에서 「인상적인 부분」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X01','K5-2-u1-X02']::text[],false,'{"seq":1,"concept":"K5-2-u1-C1","difficulty":1,"kind":"mc","stem":"작품에서 「인상적인 부분」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"읽으며 마음이 움직이거나 궁금증 · 깨달음이 생기는 부분","correct":true},{"t":"글자 수가 가장 많은 부분","mis":"K5-2-u1-X01"},{"t":"선생님이 정해 주신 한 부분","mis":"K5-2-u1-X02"},{"t":"어려운 낱말이 가장 많이 든 부분","mis":"K5-2-u1-X01"}],"explanation":["길이와는 관계없어요.","정해 준 정답이 있는 게 아니에요.","내 마음이 움직인 곳이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L01_basic#2','kor',5,2,'u1','L01','g5_2_kor_u1_L01_basic','lesson_basic','K5-2-u1-C2',1,'ox','auto','같은 시를 읽으면 모든 사람의 인상적인 부분이 똑같아요.',ARRAY['K5-2-u1-X02']::text[],false,'{"seq":2,"concept":"K5-2-u1-C2","difficulty":1,"kind":"ox","stem":"같은 시를 읽으면 모든 사람의 인상적인 부분이 똑같아요.","answer":"X","reason_options":[{"t":"사람마다 마음에 남는 부분이 다를 수 있기 때문에","correct":true},{"t":"시에는 하나로 정해진 인상적인 부분이 있기 때문에","mis":"K5-2-u1-X02"}],"mis":"K5-2-u1-X02","explanation":["같은 시도 다르게 남아요.","정답이 하나로 정해져 있지 않아요.","그래서 서로 이야기 나눌 거리가 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L01_basic#3','kor',5,2,'u1','L01','g5_2_kor_u1_L01_basic','lesson_basic','K5-2-u1-C2',1,'mc','auto','시우와 나은이가 「우산 셋」에서 고른 부분을 보고 알 수 있는 것은 어느 것인가요?',ARRAY['K5-2-u1-X15','K5-2-u1-X02','K5-2-u1-X01']::text[],false,'{"seq":3,"concept":"K5-2-u1-C2","difficulty":1,"kind":"mc","stem":"시우와 나은이가 「우산 셋」에서 고른 부분을 보고 알 수 있는 것은 어느 것인가요?","options":[{"t":"같은 시를 읽어도 인상적인 부분이 다를 수 있다","correct":true},{"t":"둘 중 한 사람은 시를 잘못 읽었다","mis":"K5-2-u1-X15"},{"t":"인상적인 부분은 첫째 연에만 있다","mis":"K5-2-u1-X02"},{"t":"긴 연을 고른 사람이 더 잘 읽었다","mis":"K5-2-u1-X01"}],"explanation":["잘못 읽은 사람은 없어요.","어느 연이든 될 수 있어요.","고른 곳이 달라도 둘 다 까닭이 있어요."],"asset":{"type":"speech","turns":[{"who":"시우","text":"나는 「폴짝폴짝 웅덩이를 건너고」가 인상적이야. 빗물 튀는 소리가 들리는 것 같아."},{"who":"나은","text":"나는 「친구 우산 밑으로 쏙」이 좋아. 지난번에 짝꿍이 나를 씌워 준 일이 떠올랐거든."},{"who":"시우","text":"같은 시인데 우리가 고른 데가 다르네."},{"who":"나은","text":"응, 그래도 둘 다 왜 골랐는지 까닭이 있잖아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L01_basic#4','kor',5,2,'u1','L01','g5_2_kor_u1_L01_basic','lesson_basic','K5-2-u1-C3',1,'blank','auto','인상적인 부분을 말할 때에는 고른 부분과 함께 그 부분이 인상적인 (     )을/를 말해요.',ARRAY['K5-2-u1-X01','K5-2-u1-X04']::text[],false,'{"seq":4,"concept":"K5-2-u1-C3","difficulty":1,"kind":"blank","stem":"인상적인 부분을 말할 때에는 고른 부분과 함께 그 부분이 인상적인 (     )을/를 말해요.","options":[{"t":"까닭","correct":true},{"t":"글자 수","mis":"K5-2-u1-X01"},{"t":"쪽수","mis":"K5-2-u1-X04"},{"t":"지은이 나이","mis":"K5-2-u1-X04"}],"explanation":["글자 수는 묻지 않아요.","쪽수는 까닭이 아니에요.","왜 마음에 남았는지 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L01_basic#5','kor',5,2,'u1','L01','g5_2_kor_u1_L01_basic','lesson_basic','K5-2-u1-C1',2,'mc','auto','「우산 셋」을 읽고 고른 인상적인 부분 가운데 「궁금증이 생긴 곳」에 가장 가까운 말은 어느 것인가요?',ARRAY['K5-2-u1-X01','K5-2-u1-X03','K5-2-u1-X04']::text[],false,'{"seq":5,"concept":"K5-2-u1-C1","difficulty":2,"kind":"mc","stem":"「우산 셋」을 읽고 고른 인상적인 부분 가운데 「궁금증이 생긴 곳」에 가장 가까운 말은 어느 것인가요?","options":[{"t":"「파란 우산은 왜 꽃집 앞에 멈췄을까?」 하고 궁금했어.","correct":true},{"t":"「빨간 우산 이야기가 제일 길어서 골랐어.」","mis":"K5-2-u1-X01"},{"t":"「그냥 넷째 연이 좋아.」","mis":"K5-2-u1-X03"},{"t":"「우산이 세 개라서 골랐어.」","mis":"K5-2-u1-X04"}],"explanation":["길이는 까닭이 못 돼요.","까닭이 빠졌어요.","궁금증이 생긴 곳도 인상적인 부분이에요."],"asset":{"type":"passage","lines":["노란 우산은 / 폴짝폴짝 웅덩이를 건너고","파란 우산은 / 느릿느릿 꽃집 앞에 멈추고","빨간 우산은 / 친구 우산 밑으로 쏙 들어갔다","비 그친 하늘이 / 세 우산을 나란히 말려 준다"],"title":"시 「우산 셋」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L01_basic#6','kor',5,2,'u1','L01','g5_2_kor_u1_L01_basic','lesson_basic','K5-2-u1-C3',2,'mc','auto','나은이가 「친구 우산 밑으로 쏙 들어갔다」를 고른 까닭은 무엇인가요?',ARRAY['K5-2-u1-X03','K5-2-u1-X04']::text[],false,'{"seq":6,"concept":"K5-2-u1-C3","difficulty":2,"kind":"mc","stem":"나은이가 「친구 우산 밑으로 쏙 들어갔다」를 고른 까닭은 무엇인가요?","options":[{"t":"짝꿍이 우산을 씌워 준 일이 떠올라서","correct":true},{"t":"빗물 튀는 소리가 들리는 것 같아서","mis":"K5-2-u1-X03"},{"t":"시의 맨 처음 연이라서","mis":"K5-2-u1-X04"},{"t":"빨간색을 가장 좋아해서","mis":"K5-2-u1-X04"}],"explanation":["그건 시우가 든 까닭이에요.","그 행은 처음 연이 아니에요.","내 경험이 떠오른 것도 까닭이에요."],"asset":{"type":"speech","turns":[{"who":"시우","text":"나는 「폴짝폴짝 웅덩이를 건너고」가 인상적이야. 빗물 튀는 소리가 들리는 것 같아."},{"who":"나은","text":"나는 「친구 우산 밑으로 쏙」이 좋아. 지난번에 짝꿍이 나를 씌워 준 일이 떠올랐거든."},{"who":"시우","text":"같은 시인데 우리가 고른 데가 다르네."},{"who":"나은","text":"응, 그래도 둘 다 왜 골랐는지 까닭이 있잖아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L01_basic#7','kor',5,2,'u1','L01','g5_2_kor_u1_L01_basic','lesson_basic','K5-2-u1-C4',2,'match','auto','작품의 종류와 인상적인 부분을 찾을 때 살필 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K5-2-u1-C4","difficulty":2,"kind":"match","stem":"작품의 종류와 인상적인 부분을 찾을 때 살필 것을 알맞게 이으세요.","pairs":[{"l":"시","r":"표현 · 말하는 이의 마음 · 분위기"},{"l":"이야기","r":"인물 · 사건 · 인물의 말과 행동"},{"l":"서평","r":"책에 대한 평가와 그 까닭"}],"mis":"K5-2-u1-X05","explanation":["시는 표현과 마음을 봐요.","이야기는 인물과 사건을 봐요.","서평은 평가를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L01_basic#8','kor',5,2,'u1','L01','g5_2_kor_u1_L01_basic','lesson_basic','K5-2-u1-C3',2,'error','auto','「우산 셋」을 읽고 친구들이 한 말이에요. 인상적인 부분을 알맞게 말하지 못한 것은 어느 것인가요?',ARRAY['K5-2-u1-X03','K5-2-u1-X04']::text[],false,'{"seq":8,"concept":"K5-2-u1-C3","difficulty":2,"kind":"error","stem":"「우산 셋」을 읽고 친구들이 한 말이에요. 인상적인 부분을 알맞게 말하지 못한 것은 어느 것인가요?","options":[{"t":"「넷째 연이 인상적이야. 이유는 없어.」","correct":true,"mis_target":"K5-2-u1-X03"},{"t":"「넷째 연이 인상적이야. 하늘이 우산을 말려 준다는 말이 다정하게 느껴져.」","mis":"K5-2-u1-X03"},{"t":"「셋째 연이 인상적이야. 친구를 챙기는 모습이 따뜻해서.」","mis":"K5-2-u1-X04"}],"explanation":["까닭이 시 속 말과 이어져요.","까닭이 장면과 이어져요.","부분만 있고 까닭이 없어요."],"asset":{"type":"passage","lines":["노란 우산은 / 폴짝폴짝 웅덩이를 건너고","파란 우산은 / 느릿느릿 꽃집 앞에 멈추고","빨간 우산은 / 친구 우산 밑으로 쏙 들어갔다","비 그친 하늘이 / 세 우산을 나란히 말려 준다"],"title":"시 「우산 셋」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L01_basic#9','kor',5,2,'u1','L01','g5_2_kor_u1_L01_basic','lesson_basic','K5-2-u1-C5',2,'mc','auto','이 단원에서 배울 내용의 차례로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X05']::text[],false,'{"seq":9,"concept":"K5-2-u1-C5","difficulty":2,"kind":"mc","stem":"이 단원에서 배울 내용의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"시 → 이야기 → 서평 쓰기 → 「이달의 책」 고르기","correct":true},{"t":"서평 쓰기 → 시 → 이야기 → 「이달의 책」 고르기","mis":"K5-2-u1-X05"},{"t":"「이달의 책」 고르기 → 서평 쓰기 → 시","mis":"K5-2-u1-X05"},{"t":"이야기 → 「이달의 책」 고르기 → 시","mis":"K5-2-u1-X05"}],"explanation":["서평은 이야기를 읽은 뒤에 써요.","「이달의 책」은 맨 끝에 골라요.","시에서 시작해 책으로 넓혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L01_basic#10','kor',5,2,'u1','L01','g5_2_kor_u1_L01_basic','lesson_basic','K5-2-u1-C4',3,'mc','auto','「작품에 대한 의견을 나누어요」 단원에서 가장 중요하게 기를 태도로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X02','K5-2-u1-X03','K5-2-u1-X15']::text[],false,'{"seq":10,"concept":"K5-2-u1-C4","difficulty":3,"kind":"mc","stem":"「작품에 대한 의견을 나누어요」 단원에서 가장 중요하게 기를 태도로 알맞은 것은 어느 것인가요?","options":[{"t":"까닭을 들어 내 생각을 말하고 친구의 다른 생각도 귀 기울여 듣는 태도","correct":true},{"t":"하나뿐인 정답 부분을 먼저 찾아 외우는 태도","mis":"K5-2-u1-X02"},{"t":"까닭은 빼고 좋아하는 부분만 빨리 말하는 태도","mis":"K5-2-u1-X03"},{"t":"나와 다른 의견은 틀렸다고 알려 주는 태도","mis":"K5-2-u1-X15"}],"explanation":["정답 부분이 따로 있지 않아요.","까닭이 함께 가야 해요.","다른 의견에서 배울 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L01_challenge#1','kor',5,2,'u1','L01','g5_2_kor_u1_L01_challenge','lesson_challenge','K5-2-u1-C1',2,'mc','auto','다음 가운데 인상적인 부분이 될 수 없는 것은 어느 것인가요?',ARRAY['K5-2-u1-X08','K5-2-u1-X01','K5-2-u1-X35']::text[],false,'{"seq":1,"concept":"K5-2-u1-C1","difficulty":2,"kind":"mc","stem":"다음 가운데 인상적인 부분이 될 수 없는 것은 어느 것인가요?","options":[{"t":"읽었는데 아무 느낌도 남지 않은 부분","correct":true},{"t":"내 경험이 떠올라 고개가 끄덕여진 부분","mis":"K5-2-u1-X08"},{"t":"「왜 그럴까?」 하고 궁금해진 부분","mis":"K5-2-u1-X01"},{"t":"짧지만 오래 기억에 남는 문장","mis":"K5-2-u1-X35"}],"explanation":["경험이 떠오른 곳도 인상적이에요.","궁금증이 생긴 곳도 인상적이에요.","짧은 문장도 될 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L01_challenge#2','kor',5,2,'u1','L01','g5_2_kor_u1_L01_challenge','lesson_challenge','K5-2-u1-C4',2,'ox','auto','정답이 하나가 아니니까 작품과 아무 관계없는 까닭을 대도 괜찮아요.',ARRAY['K5-2-u1-X04']::text[],false,'{"seq":2,"concept":"K5-2-u1-C4","difficulty":2,"kind":"ox","stem":"정답이 하나가 아니니까 작품과 아무 관계없는 까닭을 대도 괜찮아요.","answer":"X","reason_options":[{"t":"까닭은 작품 속 말이나 장면, 그와 이어진 내 경험과 닿아 있어야 하기 때문에","correct":true},{"t":"인상적인 부분은 사람마다 다르니 무엇이든 까닭이 되기 때문에","mis":"K5-2-u1-X04"}],"mis":"K5-2-u1-X04","explanation":["정답이 없다는 말이 아무거나라는 뜻은 아니에요.","작품과 이어져야 서로 이해해요.","열려 있되 까닭은 작품에 닿아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L01_challenge#3','kor',5,2,'u1','L01','g5_2_kor_u1_L01_challenge','lesson_challenge','K5-2-u1-C3',3,'mc','auto','시우의 까닭 「빗물 튀는 소리가 들리는 것 같아」는 시의 어느 말과 이어지나요?',ARRAY['K5-2-u1-X04']::text[],false,'{"seq":3,"concept":"K5-2-u1-C3","difficulty":3,"kind":"mc","stem":"시우의 까닭 「빗물 튀는 소리가 들리는 것 같아」는 시의 어느 말과 이어지나요?","options":[{"t":"「폴짝폴짝」","correct":true},{"t":"「느릿느릿」","mis":"K5-2-u1-X04"},{"t":"「나란히」","mis":"K5-2-u1-X04"},{"t":"「쏙」","mis":"K5-2-u1-X04"}],"explanation":["「느릿느릿」은 파란 우산이에요.","「나란히」는 넷째 연이에요.","뛰어 건너는 소리를 흉내 낸 말이에요."],"asset":{"type":"speech","turns":[{"who":"시우","text":"나는 「폴짝폴짝 웅덩이를 건너고」가 인상적이야. 빗물 튀는 소리가 들리는 것 같아."},{"who":"나은","text":"나는 「친구 우산 밑으로 쏙」이 좋아. 지난번에 짝꿍이 나를 씌워 준 일이 떠올랐거든."},{"who":"시우","text":"같은 시인데 우리가 고른 데가 다르네."},{"who":"나은","text":"응, 그래도 둘 다 왜 골랐는지 까닭이 있잖아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L01_challenge#4','kor',5,2,'u1','L01','g5_2_kor_u1_L01_challenge','lesson_challenge','K5-2-u1-C2',3,'mc','auto','시우와 나은이의 말에서 알 수 있는 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X02','K5-2-u1-X08','K5-2-u1-X15']::text[],false,'{"seq":4,"concept":"K5-2-u1-C2","difficulty":3,"kind":"mc","stem":"시우와 나은이의 말에서 알 수 있는 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"고른 부분이 달라도 까닭이 있으면 둘 다 의미 있는 감상이다","correct":true},{"t":"먼저 말한 시우의 감상이 정답이다","mis":"K5-2-u1-X02"},{"t":"나은이는 시와 상관없는 이야기를 했다","mis":"K5-2-u1-X08"},{"t":"고른 부분이 다르면 다시 읽어 하나로 맞춰야 한다","mis":"K5-2-u1-X15"}],"explanation":["먼저 말했다고 정답이 아니에요.","경험이 떠오른 것도 까닭이에요.","하나로 맞출 필요가 없어요."],"asset":{"type":"speech","turns":[{"who":"시우","text":"나는 「폴짝폴짝 웅덩이를 건너고」가 인상적이야. 빗물 튀는 소리가 들리는 것 같아."},{"who":"나은","text":"나는 「친구 우산 밑으로 쏙」이 좋아. 지난번에 짝꿍이 나를 씌워 준 일이 떠올랐거든."},{"who":"시우","text":"같은 시인데 우리가 고른 데가 다르네."},{"who":"나은","text":"응, 그래도 둘 다 왜 골랐는지 까닭이 있잖아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L01_challenge#5','kor',5,2,'u1','L01','g5_2_kor_u1_L01_challenge','lesson_challenge','K5-2-u1-C4',3,'mc','auto','이야기를 읽고 인상적인 부분을 찾을 때 가장 먼저 살필 것은 어느 것인가요?',ARRAY['K5-2-u1-X05','K5-2-u1-X01']::text[],false,'{"seq":5,"concept":"K5-2-u1-C4","difficulty":3,"kind":"mc","stem":"이야기를 읽고 인상적인 부분을 찾을 때 가장 먼저 살필 것은 어느 것인가요?","options":[{"t":"인물이 처한 상황과 그때 한 말이나 행동","correct":true},{"t":"행마다 반복되는 흉내 내는 말의 개수","mis":"K5-2-u1-X05"},{"t":"책의 쪽수와 글씨 크기","mis":"K5-2-u1-X01"},{"t":"연과 행이 몇 개인지","mis":"K5-2-u1-X05"}],"explanation":["그건 시의 표현을 볼 때예요.","쪽수는 감상과 관계없어요.","이야기는 인물과 사건을 따라가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L01_challenge#6','kor',5,2,'u1','L01','g5_2_kor_u1_L01_challenge','lesson_challenge','K5-2-u1-C2',3,'error','auto','「우산 셋」을 읽고 나눈 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u1-X02','K5-2-u1-X16','K5-2-u1-X03']::text[],false,'{"seq":6,"concept":"K5-2-u1-C2","difficulty":3,"kind":"error","stem":"「우산 셋」을 읽고 나눈 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「다들 첫째 연을 골라야 맞아. 시의 처음이니까.」","correct":true,"mis_target":"K5-2-u1-X02"},{"t":"「나는 넷째 연이 다정해서 골랐는데, 네가 고른 연도 들어 볼래.」","mis":"K5-2-u1-X16"},{"t":"「나는 셋째 연을 골랐어. 친구를 챙기는 모습이 좋아서.」","mis":"K5-2-u1-X03"}],"explanation":["다른 생각도 들으려 해요.","부분과 까닭을 함께 말했어요.","처음 연이 정답인 것은 아니에요."],"asset":{"type":"passage","lines":["노란 우산은 / 폴짝폴짝 웅덩이를 건너고","파란 우산은 / 느릿느릿 꽃집 앞에 멈추고","빨간 우산은 / 친구 우산 밑으로 쏙 들어갔다","비 그친 하늘이 / 세 우산을 나란히 말려 준다"],"title":"시 「우산 셋」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L01_challenge#7','kor',5,2,'u1','L01','g5_2_kor_u1_L01_challenge','lesson_challenge','K5-2-u1-C5',3,'mc','auto','이 단원의 마지막 활동인 「이달의 책」 고르기에 앞에서 배운 것이 쓰이는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X05','K5-2-u1-X34','K5-2-u1-X31']::text[],false,'{"seq":7,"concept":"K5-2-u1-C5","difficulty":3,"kind":"mc","stem":"이 단원의 마지막 활동인 「이달의 책」 고르기에 앞에서 배운 것이 쓰이는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"책을 추천할 때 인상적인 부분과 그 까닭을 들어 말해야 하기 때문에","correct":true},{"t":"「이달의 책」은 시집만 고를 수 있기 때문에","mis":"K5-2-u1-X05"},{"t":"책 제목만 알면 고를 수 있기 때문에","mis":"K5-2-u1-X34"},{"t":"가장 두꺼운 책을 골라야 하기 때문에","mis":"K5-2-u1-X31"}],"explanation":["시집만 고르는 게 아니에요.","제목만으로는 추천이 안 돼요.","두께는 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L01_challenge#8','kor',5,2,'u1','L01','g5_2_kor_u1_L01_challenge','lesson_challenge','K5-2-u1-C3',4,'essay','teacher','「우산 셋」에서 내가 고른 인상적인 부분을 하나 쓰고, 그 부분이 인상적인 까닭을 시 속 말과 이어서 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u1-C3","difficulty":4,"kind":"essay","stem":"「우산 셋」에서 내가 고른 인상적인 부분을 하나 쓰고, 그 부분이 인상적인 까닭을 시 속 말과 이어서 쓰세요.","answer_guide":{"answer":"예: 넷째 연 「비 그친 하늘이 / 세 우산을 나란히 말려 준다」가 인상적이다. 하늘이 사람처럼 우산을 말려 준다는 말에서 비가 그친 뒤의 맑고 다정한 느낌이 들기 때문이다. 서로 다른 길을 간 우산들이 마지막에 나란히 놓이는 모습도 따뜻하게 느껴졌다.","scoring_points":["인상적인 부분을 시에서 골라 썼는가","까닭을 썼는가","까닭이 시 속 말이나 장면과 이어지는가"]},"explanation":["한 부분을 골라요.","왜 남았는지 써요.","시 속 말과 이어요."],"asset":{"type":"passage","lines":["노란 우산은 / 폴짝폴짝 웅덩이를 건너고","파란 우산은 / 느릿느릿 꽃집 앞에 멈추고","빨간 우산은 / 친구 우산 밑으로 쏙 들어갔다","비 그친 하늘이 / 세 우산을 나란히 말려 준다"],"title":"시 「우산 셋」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L01_challenge#9','kor',5,2,'u1','L01','g5_2_kor_u1_L01_challenge','lesson_challenge','K5-2-u1-C2',4,'essay','teacher','「인상적인 부분에는 정답이 없지만, 아무거나 골라도 되는 것은 아니다」라는 말의 뜻을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u1-C2","difficulty":4,"kind":"essay","stem":"「인상적인 부분에는 정답이 없지만, 아무거나 골라도 되는 것은 아니다」라는 말의 뜻을 쓰세요.","answer_guide":{"answer":"예: 같은 작품을 읽어도 사람마다 경험과 생각이 달라 마음에 남는 부분이 다를 수 있으므로 정답이 하나로 정해져 있지 않다. 하지만 그 부분이 왜 인상적인지 작품 속 말이나 장면, 그와 이어진 내 경험으로 까닭을 대야 친구도 내 생각을 이해할 수 있다. 까닭 없이 고르거나 작품과 상관없는 까닭을 대는 것은 감상이라고 하기 어렵다.","scoring_points":["정답이 없는 까닭을 썼는가","까닭이 작품과 이어져야 함을 썼는가","두 가지를 함께 정리했는가"]},"explanation":["사람마다 다른 까닭을 떠올려요.","까닭의 조건을 써요.","두 말을 이어 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L01_challenge#10','kor',5,2,'u1','L01','g5_2_kor_u1_L01_challenge','lesson_challenge','K5-2-u1-C1',4,'essay','teacher','내가 재미있게 읽었던 이야기나 시를 하나 떠올려, 인상적인 부분이 「마음이 움직인 곳 · 궁금증이 생긴 곳 · 깨달음이 생긴 곳」 가운데 어디에 가까운지 쓰고 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u1-C1","difficulty":4,"kind":"essay","stem":"내가 재미있게 읽었던 이야기나 시를 하나 떠올려, 인상적인 부분이 「마음이 움직인 곳 · 궁금증이 생긴 곳 · 깨달음이 생긴 곳」 가운데 어디에 가까운지 쓰고 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 동화에서 주인공이 잃어버린 강아지를 찾으려고 비 오는 밤에 골목을 헤매는 장면이 인상적이었다. 마음이 움직인 곳에 가깝다. 강아지를 애타게 부르는 주인공의 목소리가 들리는 것 같아 나도 가슴이 조마조마했기 때문이다.","scoring_points":["작품과 인상적인 부분을 썼는가","세 가지 가운데 하나를 골랐는가","까닭을 작품과 이어 썼는가"]},"explanation":["읽은 작품을 떠올려요.","어떤 마음이 들었는지 골라요.","까닭을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L02_basic#1','kor',5,2,'u1','L02','g5_2_kor_u1_L02_basic','lesson_basic','K5-2-u1-C6',1,'mc','auto','「말의 온도」에서 따뜻한 말을 들었을 때의 모습은 어떠한가요?',ARRAY['K5-2-u1-X06','K5-2-u1-X09']::text[],false,'{"seq":1,"concept":"K5-2-u1-C6","difficulty":1,"kind":"mc","stem":"「말의 온도」에서 따뜻한 말을 들었을 때의 모습은 어떠한가요?","options":[{"t":"두 볼이 발그레해진다","correct":true},{"t":"어깨가 움츠러든다","mis":"K5-2-u1-X06"},{"t":"마음이 따끔따끔하다","mis":"K5-2-u1-X06"},{"t":"발자국이 찍힌다","mis":"K5-2-u1-X09"}],"explanation":["차가운 말을 들었을 때예요.","뾰족한 말을 들었을 때예요.","따뜻한 말은 볼을 발그레하게 해요."],"asset":{"type":"passage","lines":["따뜻한 말 들으면 / 두 볼이 발그레","차가운 말 들으면 / 어깨가 움츠러들고","뾰족한 말 들으면 / 마음이 따끔따끔","말은 마음에 찍히는 발자국 / 사뿐사뿐 디뎌야 해"],"title":"시 「말의 온도」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L02_basic#2','kor',5,2,'u1','L02','g5_2_kor_u1_L02_basic','lesson_basic','K5-2-u1-C9',1,'mc','auto','「말의 온도」의 주제로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X11','K5-2-u1-X09','K5-2-u1-X06']::text[],false,'{"seq":2,"concept":"K5-2-u1-C9","difficulty":1,"kind":"mc","stem":"「말의 온도」의 주제로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"말은 듣는 사람의 마음에 남으니 조심해서 말해야 한다","correct":true},{"t":"겨울에는 따뜻하게 입어야 한다","mis":"K5-2-u1-X11"},{"t":"발자국은 사뿐사뿐 남겨야 한다","mis":"K5-2-u1-X09"},{"t":"뾰족한 물건은 위험하다","mis":"K5-2-u1-X06"}],"explanation":["온도는 날씨 이야기가 아니에요.","발자국은 빗댄 말이에요.","마지막 연에 하고 싶은 말이 드러나요."],"asset":{"type":"passage","lines":["따뜻한 말 들으면 / 두 볼이 발그레","차가운 말 들으면 / 어깨가 움츠러들고","뾰족한 말 들으면 / 마음이 따끔따끔","말은 마음에 찍히는 발자국 / 사뿐사뿐 디뎌야 해"],"title":"시 「말의 온도」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L02_basic#3','kor',5,2,'u1','L02','g5_2_kor_u1_L02_basic','lesson_basic','K5-2-u1-C7',1,'ox','auto','「따끔따끔」처럼 느낌을 흉내 낸 말도 인상적인 부분이 될 수 있어요.',ARRAY['K5-2-u1-X01']::text[],false,'{"seq":3,"concept":"K5-2-u1-C7","difficulty":1,"kind":"ox","stem":"「따끔따끔」처럼 느낌을 흉내 낸 말도 인상적인 부분이 될 수 있어요.","answer":"O","reason_options":[{"t":"독특하고 재미있는 표현은 읽는 사람의 마음에 남기 쉽기 때문에","correct":true},{"t":"흉내 내는 말은 쉬운 말이라 인상적일 수 없기 때문에","mis":"K5-2-u1-X01"}],"mis":"K5-2-u1-X01","explanation":["쉬운 말도 마음에 남아요.","느낌이 살아나는 표현이에요.","표현이 주는 느낌까지 말해요."],"asset":{"type":"passage","lines":["따뜻한 말 들으면 / 두 볼이 발그레","차가운 말 들으면 / 어깨가 움츠러들고","뾰족한 말 들으면 / 마음이 따끔따끔","말은 마음에 찍히는 발자국 / 사뿐사뿐 디뎌야 해"],"title":"시 「말의 온도」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L02_basic#4','kor',5,2,'u1','L02','g5_2_kor_u1_L02_basic','lesson_basic','K5-2-u1-C7',1,'match','auto','인상적인 부분을 찾는 방법과 그 예를 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K5-2-u1-C7","difficulty":1,"kind":"match","stem":"인상적인 부분을 찾는 방법과 그 예를 알맞게 이으세요.","pairs":[{"l":"독특하고 재미있는 표현","r":"「마음이 따끔따끔」이 바늘에 찔린 듯 느껴져서"},{"l":"내 경험과 이어지는 공감","r":"나도 차가운 말을 듣고 어깨가 움츠러든 적이 있어서"},{"l":"주제가 잘 드러나는 부분","r":"「사뿐사뿐 디뎌야 해」에 하고 싶은 말이 담겨서"}],"mis":"K5-2-u1-X08","explanation":["표현의 느낌을 말했어요.","내 경험을 말했어요.","하고 싶은 말을 짚었어요."],"asset":{"type":"passage","lines":["따뜻한 말 들으면 / 두 볼이 발그레","차가운 말 들으면 / 어깨가 움츠러들고","뾰족한 말 들으면 / 마음이 따끔따끔","말은 마음에 찍히는 발자국 / 사뿐사뿐 디뎌야 해"],"title":"시 「말의 온도」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L02_basic#5','kor',5,2,'u1','L02','g5_2_kor_u1_L02_basic','lesson_basic','K5-2-u1-C11',2,'mc','auto','「말은 마음에 찍히는 발자국」에서 말과 발자국의 닮은 점은 무엇인가요?',ARRAY['K5-2-u1-X09']::text[],false,'{"seq":5,"concept":"K5-2-u1-C11","difficulty":2,"kind":"mc","stem":"「말은 마음에 찍히는 발자국」에서 말과 발자국의 닮은 점은 무엇인가요?","options":[{"t":"한번 남으면 쉽게 지워지지 않는다","correct":true},{"t":"둘 다 발로 만든다","mis":"K5-2-u1-X09"},{"t":"둘 다 눈 위에만 생긴다","mis":"K5-2-u1-X09"},{"t":"둘 다 소리가 크다","mis":"K5-2-u1-X09"}],"explanation":["글자 그대로 읽지 않아요.","눈 이야기가 아니에요.","마음에 남는다는 점이 닮았어요."],"asset":{"type":"passage","lines":["따뜻한 말 들으면 / 두 볼이 발그레","차가운 말 들으면 / 어깨가 움츠러들고","뾰족한 말 들으면 / 마음이 따끔따끔","말은 마음에 찍히는 발자국 / 사뿐사뿐 디뎌야 해"],"title":"시 「말의 온도」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L02_basic#6','kor',5,2,'u1','L02','g5_2_kor_u1_L02_basic','lesson_basic','K5-2-u1-C8',2,'error','auto','「말의 온도」를 읽고 친구들이 말한 까닭이에요. 알맞지 않은 생각은 어느 것인가요?',ARRAY['K5-2-u1-X08','K5-2-u1-X03','K5-2-u1-X09']::text[],false,'{"seq":6,"concept":"K5-2-u1-C8","difficulty":2,"kind":"error","stem":"「말의 온도」를 읽고 친구들이 말한 까닭이에요. 알맞지 않은 생각은 어느 것인가요?","options":[{"t":"「내 경험이 떠올라 고른 건 시와 상관없으니 까닭이 안 돼.」","correct":true,"mis_target":"K5-2-u1-X08"},{"t":"「친구에게 따뜻한 말을 듣고 볼이 뜨거워진 적이 있어서 첫째 연을 골랐어.」","mis":"K5-2-u1-X03"},{"t":"「발자국에 빗댄 말이 새로워서 마지막 연을 골랐어.」","mis":"K5-2-u1-X09"}],"explanation":["경험과 이어진 좋은 까닭이에요.","표현을 까닭으로 들었어요.","내 경험이 떠오른 것도 까닭이 돼요."],"asset":{"type":"passage","lines":["따뜻한 말 들으면 / 두 볼이 발그레","차가운 말 들으면 / 어깨가 움츠러들고","뾰족한 말 들으면 / 마음이 따끔따끔","말은 마음에 찍히는 발자국 / 사뿐사뿐 디뎌야 해"],"title":"시 「말의 온도」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L02_basic#7','kor',5,2,'u1','L02','g5_2_kor_u1_L02_basic','lesson_basic','K5-2-u1-C10',2,'mc','auto','「말의 온도」에서 시 전체를 읽고 느낀 것을 인상적인 부분으로 말한 것은 어느 것인가요?',ARRAY['K5-2-u1-X01','K5-2-u1-X11']::text[],false,'{"seq":7,"concept":"K5-2-u1-C10","difficulty":2,"kind":"mc","stem":"「말의 온도」에서 시 전체를 읽고 느낀 것을 인상적인 부분으로 말한 것은 어느 것인가요?","options":[{"t":"「말을 조심하자고 다정하게 타이르는 듯한 분위기가 좋아.」","correct":true},{"t":"「〈발그레〉라는 낱말이 어려워서 골랐어.」","mis":"K5-2-u1-X01"},{"t":"「셋째 연이 가장 길어서 골랐어.」","mis":"K5-2-u1-X01"},{"t":"「제목에 온도가 들어가서 날씨 시인 줄 알았어.」","mis":"K5-2-u1-X11"}],"explanation":["어려운 낱말이 까닭이 아니에요.","길이는 까닭이 아니에요.","분위기도 인상적인 부분이 돼요."],"asset":{"type":"passage","lines":["따뜻한 말 들으면 / 두 볼이 발그레","차가운 말 들으면 / 어깨가 움츠러들고","뾰족한 말 들으면 / 마음이 따끔따끔","말은 마음에 찍히는 발자국 / 사뿐사뿐 디뎌야 해"],"title":"시 「말의 온도」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L02_basic#8','kor',5,2,'u1','L02','g5_2_kor_u1_L02_basic','lesson_basic','K5-2-u1-C12',2,'mc','auto','「마음이 따끔따끔」의 느낌을 살려 낭송하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X10']::text[],false,'{"seq":8,"concept":"K5-2-u1-C12","difficulty":2,"kind":"mc","stem":"「마음이 따끔따끔」의 느낌을 살려 낭송하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"「따끔따끔」을 짧게 끊어 또렷하게 읽는다","correct":true},{"t":"모든 행을 같은 빠르기로 크게 읽는다","mis":"K5-2-u1-X10"},{"t":"가장 작은 소리로 웅얼거린다","mis":"K5-2-u1-X10"},{"t":"「따끔따끔」만 빼고 읽는다","mis":"K5-2-u1-X10"}],"explanation":["같은 소리로만 읽으면 느낌이 안 살아요.","들리지 않으면 느낌도 안 전해져요.","찔리는 느낌을 소리로 살려요."],"asset":{"type":"passage","lines":["따뜻한 말 들으면 / 두 볼이 발그레","차가운 말 들으면 / 어깨가 움츠러들고","뾰족한 말 들으면 / 마음이 따끔따끔","말은 마음에 찍히는 발자국 / 사뿐사뿐 디뎌야 해"],"title":"시 「말의 온도」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L02_basic#9','kor',5,2,'u1','L02','g5_2_kor_u1_L02_basic','lesson_basic','K5-2-u1-C6',2,'blank','auto','시는 (     ) 읽으며 장면을 떠올리고, 다시 읽고 싶은 부분을 찾아요.',ARRAY['K5-2-u1-X06','K5-2-u1-X11']::text[],false,'{"seq":9,"concept":"K5-2-u1-C6","difficulty":2,"kind":"blank","stem":"시는 (     ) 읽으며 장면을 떠올리고, 다시 읽고 싶은 부분을 찾아요.","options":[{"t":"여러 번","correct":true},{"t":"한 번만 훑어","mis":"K5-2-u1-X06"},{"t":"제목만","mis":"K5-2-u1-X11"},{"t":"거꾸로","mis":"K5-2-u1-X06"}],"explanation":["한 번으로는 놓치는 게 많아요.","제목만으로는 부족해요.","읽을수록 새로 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L02_basic#10','kor',5,2,'u1','L02','g5_2_kor_u1_L02_basic','lesson_basic','K5-2-u1-C3',3,'mc','auto','「말의 온도」에서 인상적인 부분을 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['K5-2-u1-X03','K5-2-u1-X04','K5-2-u1-X07']::text[],false,'{"seq":10,"concept":"K5-2-u1-C3","difficulty":3,"kind":"mc","stem":"「말의 온도」에서 인상적인 부분을 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"「〈사뿐사뿐 디뎌야 해〉가 인상적이야. 친구 마음을 밟지 않게 말을 고르라는 뜻 같아서.」","correct":true},{"t":"「셋째 연이 인상적이야. 그냥.」","mis":"K5-2-u1-X03"},{"t":"「첫째 연이 인상적이야. 오늘 점심이 맛있었거든.」","mis":"K5-2-u1-X04"},{"t":"「모든 연이 똑같이 인상적이야.」","mis":"K5-2-u1-X07"}],"explanation":["까닭이 빠졌어요.","까닭이 시와 이어지지 않아요.","부분과 까닭이 시 속 말로 이어져요."],"asset":{"type":"passage","lines":["따뜻한 말 들으면 / 두 볼이 발그레","차가운 말 들으면 / 어깨가 움츠러들고","뾰족한 말 들으면 / 마음이 따끔따끔","말은 마음에 찍히는 발자국 / 사뿐사뿐 디뎌야 해"],"title":"시 「말의 온도」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L02_challenge#1','kor',5,2,'u1','L02','g5_2_kor_u1_L02_challenge','lesson_challenge','K5-2-u1-C11',2,'mc','auto','「뭉툭한 내 생각도 / 뾰족하게 깎이는 것 같다」를 바르게 이해한 것은 어느 것인가요?',ARRAY['K5-2-u1-X09']::text[],false,'{"seq":1,"concept":"K5-2-u1-C11","difficulty":2,"kind":"mc","stem":"「뭉툭한 내 생각도 / 뾰족하게 깎이는 것 같다」를 바르게 이해한 것은 어느 것인가요?","options":[{"t":"연필을 깎으니 생각도 또렷해지는 것 같다는 느낌을 빗댄 말이다","correct":true},{"t":"머릿속에 연필깎이가 들어 있다는 말이다","mis":"K5-2-u1-X09"},{"t":"생각이 아파서 따끔거린다는 말이다","mis":"K5-2-u1-X09"},{"t":"연필이 생각을 한다는 말이다","mis":"K5-2-u1-X09"}],"explanation":["글자 그대로가 아니에요.","아프다는 말은 없어요.","또렷해지는 느낌이 닮았어요."],"asset":{"type":"passage","lines":["드르륵드르륵 / 연필깎이가 노래하면","뭉툭한 내 생각도 / 뾰족하게 깎이는 것 같다","그런데 너무 깎으면 / 연필이 금방 짧아지지","오늘은 / 딱 한 번만 돌려야지"],"title":"시 「연필깎이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L02_challenge#2','kor',5,2,'u1','L02','g5_2_kor_u1_L02_challenge','lesson_challenge','K5-2-u1-C7',2,'mc','auto','「연필깎이」에서 소리를 흉내 낸 재미있는 표현은 어느 것인가요?',ARRAY['K5-2-u1-X07']::text[],false,'{"seq":2,"concept":"K5-2-u1-C7","difficulty":2,"kind":"mc","stem":"「연필깎이」에서 소리를 흉내 낸 재미있는 표현은 어느 것인가요?","options":[{"t":"드르륵드르륵","correct":true},{"t":"뭉툭한","mis":"K5-2-u1-X07"},{"t":"금방","mis":"K5-2-u1-X07"},{"t":"딱 한 번","mis":"K5-2-u1-X07"}],"explanation":["모양을 나타내는 말이에요.","때를 나타내는 말이에요.","깎는 소리를 흉내 냈어요."],"asset":{"type":"passage","lines":["드르륵드르륵 / 연필깎이가 노래하면","뭉툭한 내 생각도 / 뾰족하게 깎이는 것 같다","그런데 너무 깎으면 / 연필이 금방 짧아지지","오늘은 / 딱 한 번만 돌려야지"],"title":"시 「연필깎이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L02_challenge#3','kor',5,2,'u1','L02','g5_2_kor_u1_L02_challenge','lesson_challenge','K5-2-u1-C9',3,'mc','auto','「연필깎이」에서 말하는 이의 생각이 가장 잘 드러난 부분은 어느 것인가요?',ARRAY['K5-2-u1-X11','K5-2-u1-X06']::text[],false,'{"seq":3,"concept":"K5-2-u1-C9","difficulty":3,"kind":"mc","stem":"「연필깎이」에서 말하는 이의 생각이 가장 잘 드러난 부분은 어느 것인가요?","options":[{"t":"「오늘은 / 딱 한 번만 돌려야지」","correct":true},{"t":"「드르륵드르륵 / 연필깎이가 노래하면」","mis":"K5-2-u1-X11"},{"t":"제목 「연필깎이」","mis":"K5-2-u1-X11"},{"t":"「뭉툭한 내 생각도」","mis":"K5-2-u1-X06"}],"explanation":["소리를 나타낸 부분이에요.","제목만으로는 생각을 다 알 수 없어요.","아껴 쓰겠다는 다짐이 드러나요."],"asset":{"type":"passage","lines":["드르륵드르륵 / 연필깎이가 노래하면","뭉툭한 내 생각도 / 뾰족하게 깎이는 것 같다","그런데 너무 깎으면 / 연필이 금방 짧아지지","오늘은 / 딱 한 번만 돌려야지"],"title":"시 「연필깎이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L02_challenge#4','kor',5,2,'u1','L02','g5_2_kor_u1_L02_challenge','lesson_challenge','K5-2-u1-C10',3,'ox','auto','「연필깎이」에서는 짧아질까 봐 아끼려는 말하는 이의 마음도 인상적인 부분이 될 수 있어요.',ARRAY['K5-2-u1-X07']::text[],false,'{"seq":4,"concept":"K5-2-u1-C10","difficulty":3,"kind":"ox","stem":"「연필깎이」에서는 짧아질까 봐 아끼려는 말하는 이의 마음도 인상적인 부분이 될 수 있어요.","answer":"O","reason_options":[{"t":"인상적인 부분은 구절만이 아니라 말하는 이의 마음이나 분위기도 될 수 있기 때문에","correct":true},{"t":"인상적인 부분은 멋진 낱말이 든 한 구절뿐이기 때문에","mis":"K5-2-u1-X07"}],"mis":"K5-2-u1-X07","explanation":["마음도 인상적인 부분이에요.","시 전체에서 느낀 것도 돼요.","구절에만 머물지 않아요."],"asset":{"type":"passage","lines":["드르륵드르륵 / 연필깎이가 노래하면","뭉툭한 내 생각도 / 뾰족하게 깎이는 것 같다","그런데 너무 깎으면 / 연필이 금방 짧아지지","오늘은 / 딱 한 번만 돌려야지"],"title":"시 「연필깎이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L02_challenge#5','kor',5,2,'u1','L02','g5_2_kor_u1_L02_challenge','lesson_challenge','K5-2-u1-C12',3,'match','auto','「연필깎이」의 연과 어울리는 낭송 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K5-2-u1-C12","difficulty":3,"kind":"match","stem":"「연필깎이」의 연과 어울리는 낭송 방법을 알맞게 이으세요.","pairs":[{"l":"첫째 연","r":"「드르륵드르륵」을 경쾌하게 빠르게"},{"l":"셋째 연","r":"「너무 깎으면」에서 조금 느리고 걱정스럽게"},{"l":"넷째 연","r":"「딱 한 번만」을 또박또박 다짐하듯"}],"mis":"K5-2-u1-X10","explanation":["신나는 소리는 빠르게 살려요.","걱정이 드는 곳은 느리게 읽어요.","다짐은 또박또박 읽어요."],"asset":{"type":"passage","lines":["드르륵드르륵 / 연필깎이가 노래하면","뭉툭한 내 생각도 / 뾰족하게 깎이는 것 같다","그런데 너무 깎으면 / 연필이 금방 짧아지지","오늘은 / 딱 한 번만 돌려야지"],"title":"시 「연필깎이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L02_challenge#6','kor',5,2,'u1','L02','g5_2_kor_u1_L02_challenge','lesson_challenge','K5-2-u1-C3',3,'error','auto','「연필깎이」를 읽고 쓴 감상이에요. 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u1-X04','K5-2-u1-X08','K5-2-u1-X07']::text[],false,'{"seq":6,"concept":"K5-2-u1-C3","difficulty":3,"kind":"error","stem":"「연필깎이」를 읽고 쓴 감상이에요. 알맞지 않은 것은 어느 것인가요?","options":[{"t":"「넷째 연이 인상적이다. 나는 연필보다 볼펜을 좋아하기 때문이다.」","correct":true,"mis_target":"K5-2-u1-X04"},{"t":"「셋째 연이 인상적이다. 나도 새 연필을 재미 삼아 깎다가 몽당연필로 만든 적이 있다.」","mis":"K5-2-u1-X08"},{"t":"「첫째 연이 인상적이다. 연필깎이가 노래한다는 표현이 재미있다.」","mis":"K5-2-u1-X07"}],"explanation":["경험과 이어진 까닭이에요.","표현과 이어진 까닭이에요.","까닭이 시의 내용과 이어지지 않아요."],"asset":{"type":"passage","lines":["드르륵드르륵 / 연필깎이가 노래하면","뭉툭한 내 생각도 / 뾰족하게 깎이는 것 같다","그런데 너무 깎으면 / 연필이 금방 짧아지지","오늘은 / 딱 한 번만 돌려야지"],"title":"시 「연필깎이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L02_challenge#7','kor',5,2,'u1','L02','g5_2_kor_u1_L02_challenge','lesson_challenge','K5-2-u1-C8',3,'mc','auto','「말의 온도」의 둘째 연 「차가운 말 들으면 / 어깨가 움츠러들고」에 공감한 친구가 할 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X09','K5-2-u1-X01','K5-2-u1-X02']::text[],false,'{"seq":7,"concept":"K5-2-u1-C8","difficulty":3,"kind":"mc","stem":"「말의 온도」의 둘째 연 「차가운 말 들으면 / 어깨가 움츠러들고」에 공감한 친구가 할 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「놀림을 받았을 때 나도 어깨가 저절로 움츠러들었어.」","correct":true},{"t":"「겨울에 손이 시려서 장갑을 꼈어.」","mis":"K5-2-u1-X09"},{"t":"「어깨라는 낱말이 들어가서 좋아.」","mis":"K5-2-u1-X01"},{"t":"「둘째 연은 정답이 아니라서 공감하면 안 돼.」","mis":"K5-2-u1-X02"}],"explanation":["차가운 말 이야기예요, 날씨가 아니에요.","낱말 하나로는 공감이 아니에요.","비슷한 일을 떠올렸어요."],"asset":{"type":"passage","lines":["따뜻한 말 들으면 / 두 볼이 발그레","차가운 말 들으면 / 어깨가 움츠러들고","뾰족한 말 들으면 / 마음이 따끔따끔","말은 마음에 찍히는 발자국 / 사뿐사뿐 디뎌야 해"],"title":"시 「말의 온도」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L02_challenge#8','kor',5,2,'u1','L02','g5_2_kor_u1_L02_challenge','lesson_challenge','K5-2-u1-C11',4,'essay','teacher','「말은 마음에 찍히는 발자국」이라는 표현이 무엇을 무엇에 빗댄 것인지 쓰고, 둘의 닮은 점과 이 표현이 인상적인 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u1-C11","difficulty":4,"kind":"essay","stem":"「말은 마음에 찍히는 발자국」이라는 표현이 무엇을 무엇에 빗댄 것인지 쓰고, 둘의 닮은 점과 이 표현이 인상적인 까닭을 쓰세요.","answer_guide":{"answer":"예: 말을 발자국에 빗댄 표현이다. 발자국이 땅에 찍혀 오래 남듯이 말도 듣는 사람의 마음에 남아 쉽게 지워지지 않는다는 점이 닮았다. 내가 친구에게 무심코 한 말이 오래 마음에 남았다는 이야기를 들은 적이 있어서, 이 표현을 읽고 말을 조심해야겠다는 생각이 들어 인상적이었다.","scoring_points":["무엇을 무엇에 빗댔는지 썼는가","닮은 점을 썼는가","인상적인 까닭을 썼는가"]},"explanation":["빗댄 두 가지를 찾아요.","닮은 점을 생각해요.","까닭을 경험과 이어요."],"asset":{"type":"passage","lines":["따뜻한 말 들으면 / 두 볼이 발그레","차가운 말 들으면 / 어깨가 움츠러들고","뾰족한 말 들으면 / 마음이 따끔따끔","말은 마음에 찍히는 발자국 / 사뿐사뿐 디뎌야 해"],"title":"시 「말의 온도」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L02_challenge#9','kor',5,2,'u1','L02','g5_2_kor_u1_L02_challenge','lesson_challenge','K5-2-u1-C12',4,'essay','teacher','「말의 온도」에서 인상적인 부분을 하나 고르고, 그 느낌을 살려 낭송하려면 빠르기 · 목소리를 어떻게 하면 좋을지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u1-C12","difficulty":4,"kind":"essay","stem":"「말의 온도」에서 인상적인 부분을 하나 고르고, 그 느낌을 살려 낭송하려면 빠르기 · 목소리를 어떻게 하면 좋을지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 넷째 연 「말은 마음에 찍히는 발자국 / 사뿐사뿐 디뎌야 해」를 골랐다. 앞의 연보다 조금 느리게, 부드럽고 낮은 목소리로 읽겠다. 「사뿐사뿐」에서는 발끝으로 걷듯 살짝 끊어 읽겠다. 말을 조심하자고 다정하게 타이르는 느낌이 잘 살아나기 때문이다.","scoring_points":["인상적인 부분을 골랐는가","빠르기와 목소리를 정했는가","느낌과 이어진 까닭을 썼는가"]},"explanation":["한 연을 골라요.","어떻게 읽을지 정해요.","그 느낌과 이어요."],"asset":{"type":"passage","lines":["따뜻한 말 들으면 / 두 볼이 발그레","차가운 말 들으면 / 어깨가 움츠러들고","뾰족한 말 들으면 / 마음이 따끔따끔","말은 마음에 찍히는 발자국 / 사뿐사뿐 디뎌야 해"],"title":"시 「말의 온도」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L02_challenge#10','kor',5,2,'u1','L02','g5_2_kor_u1_L02_challenge','lesson_challenge','K5-2-u1-C9',4,'essay','teacher','「연필깎이」의 주제를 한 문장으로 쓰고, 주제가 잘 드러난 부분과 그 부분을 고른 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u1-C9","difficulty":4,"kind":"essay","stem":"「연필깎이」의 주제를 한 문장으로 쓰고, 주제가 잘 드러난 부분과 그 부분을 고른 까닭을 쓰세요.","answer_guide":{"answer":"예: 주제 — 물건을 아껴 쓰자. 주제가 잘 드러난 부분은 넷째 연 「오늘은 / 딱 한 번만 돌려야지」이다. 셋째 연에서 너무 깎으면 연필이 짧아진다는 것을 깨닫고, 마지막에 한 번만 돌리겠다고 다짐하는 데에서 아껴 쓰려는 마음이 가장 또렷하게 보이기 때문이다.","scoring_points":["주제를 한 문장으로 썼는가","주제가 드러난 부분을 골랐는가","까닭을 시의 흐름과 이어 썼는가"]},"explanation":["하고 싶은 말을 찾아요.","그 말이 드러난 연을 골라요.","앞 연과 이어 까닭을 써요."],"asset":{"type":"passage","lines":["드르륵드르륵 / 연필깎이가 노래하면","뭉툭한 내 생각도 / 뾰족하게 깎이는 것 같다","그런데 너무 깎으면 / 연필이 금방 짧아지지","오늘은 / 딱 한 번만 돌려야지"],"title":"시 「연필깎이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L04_basic#1','kor',5,2,'u1','L04','g5_2_kor_u1_L04_basic','lesson_basic','K5-2-u1-C14',1,'mc','auto','「괜찮아, 나」에 나온 「괜스레」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X13']::text[],false,'{"seq":1,"concept":"K5-2-u1-C14","difficulty":1,"kind":"mc","stem":"「괜찮아, 나」에 나온 「괜스레」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"까닭이나 실속 없이","correct":true},{"t":"괜찮게, 아무렇지 않게","mis":"K5-2-u1-X13"},{"t":"아주 빠르게","mis":"K5-2-u1-X13"},{"t":"조심스럽게","mis":"K5-2-u1-X13"}],"explanation":["「괜찮다」와 소리만 비슷해요.","빠르기를 뜻하지 않아요.","까닭 없이 문지르는 마음이에요."],"asset":{"type":"passage","lines":["틀린 글씨 지우다가 / 종이가 북 찢어졌다","괜스레 지우개만 / 박박 문지른다","내 마음도 / 찢어진 종이처럼 구겨진다","손바닥으로 종이를 펴며 / 나에게 말해 본다 — 괜찮아"],"title":"시 「괜찮아, 나」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L04_basic#2','kor',5,2,'u1','L04','g5_2_kor_u1_L04_basic','lesson_basic','K5-2-u1-C15',1,'mc','auto','「괜찮아, 나」에서 말하는 이가 처음에 겪은 일은 무엇인가요?',ARRAY['K5-2-u1-X06']::text[],false,'{"seq":2,"concept":"K5-2-u1-C15","difficulty":1,"kind":"mc","stem":"「괜찮아, 나」에서 말하는 이가 처음에 겪은 일은 무엇인가요?","options":[{"t":"틀린 글씨를 지우다가 종이가 찢어졌다","correct":true},{"t":"지우개를 잃어버렸다","mis":"K5-2-u1-X06"},{"t":"친구와 다투었다","mis":"K5-2-u1-X06"},{"t":"시험에서 백 점을 받았다","mis":"K5-2-u1-X06"}],"explanation":["지우개는 손에 있어요.","친구 이야기는 없어요.","첫째 연에 나와요."],"asset":{"type":"passage","lines":["틀린 글씨 지우다가 / 종이가 북 찢어졌다","괜스레 지우개만 / 박박 문지른다","내 마음도 / 찢어진 종이처럼 구겨진다","손바닥으로 종이를 펴며 / 나에게 말해 본다 — 괜찮아"],"title":"시 「괜찮아, 나」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L04_basic#3','kor',5,2,'u1','L04','g5_2_kor_u1_L04_basic','lesson_basic','K5-2-u1-C15',1,'ox','auto','「괜찮아, 나」에서 말하는 이의 마음은 처음부터 끝까지 똑같아요.',ARRAY['K5-2-u1-X14']::text[],false,'{"seq":3,"concept":"K5-2-u1-C15","difficulty":1,"kind":"ox","stem":"「괜찮아, 나」에서 말하는 이의 마음은 처음부터 끝까지 똑같아요.","answer":"X","reason_options":[{"t":"속상하고 답답하던 마음이 마지막 연에서 스스로를 달래는 마음으로 바뀌기 때문에","correct":true},{"t":"시 속 말하는 이의 마음은 늘 하나로 정해져 있기 때문에","mis":"K5-2-u1-X14"}],"mis":"K5-2-u1-X14","explanation":["연마다 마음을 따라가요.","마지막 연에서 달라져요.","말하는 이의 마음도 흘러가요."],"asset":{"type":"passage","lines":["틀린 글씨 지우다가 / 종이가 북 찢어졌다","괜스레 지우개만 / 박박 문지른다","내 마음도 / 찢어진 종이처럼 구겨진다","손바닥으로 종이를 펴며 / 나에게 말해 본다 — 괜찮아"],"title":"시 「괜찮아, 나」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L04_basic#4','kor',5,2,'u1','L04','g5_2_kor_u1_L04_basic','lesson_basic','K5-2-u1-C15',1,'match','auto','「괜찮아, 나」의 연과 말하는 이의 마음을 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K5-2-u1-C15","difficulty":1,"kind":"match","stem":"「괜찮아, 나」의 연과 말하는 이의 마음을 알맞게 이으세요.","pairs":[{"l":"첫째 연 — 종이가 북 찢어졌다","r":"속상함"},{"l":"둘째 연 — 지우개만 박박 문지른다","r":"답답함"},{"l":"넷째 연 — 나에게 말해 본다","r":"스스로 달래기"}],"mis":"K5-2-u1-X14","explanation":["놀라고 속상해요.","어쩔 줄 몰라 답답해요.","스스로 다독여요."],"asset":{"type":"passage","lines":["틀린 글씨 지우다가 / 종이가 북 찢어졌다","괜스레 지우개만 / 박박 문지른다","내 마음도 / 찢어진 종이처럼 구겨진다","손바닥으로 종이를 펴며 / 나에게 말해 본다 — 괜찮아"],"title":"시 「괜찮아, 나」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L04_basic#5','kor',5,2,'u1','L04','g5_2_kor_u1_L04_basic','lesson_basic','K5-2-u1-C17',2,'mc','auto','다인이와 로운이가 고른 인상적인 부분이 다른 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X15','K5-2-u1-X02','K5-2-u1-X03']::text[],false,'{"seq":5,"concept":"K5-2-u1-C17","difficulty":2,"kind":"mc","stem":"다인이와 로운이가 고른 인상적인 부분이 다른 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"둘의 경험과 관심이 서로 달라서","correct":true},{"t":"둘 중 한 사람이 시를 잘못 읽어서","mis":"K5-2-u1-X15"},{"t":"시에 인상적인 부분이 하나뿐이어서","mis":"K5-2-u1-X02"},{"t":"둘 다 까닭을 말하지 않아서","mis":"K5-2-u1-X03"}],"explanation":["잘못 읽은 사람은 없어요.","정답 부분이 하나인 게 아니에요.","둘 다 까닭을 말했어요."],"asset":{"type":"speech","turns":[{"who":"다인","text":"나는 「괜스레 지우개만 박박 문지른다」가 인상적이야. 속상할 때 나도 괜히 물건을 만지작거리거든."},{"who":"로운","text":"나는 마지막 「괜찮아」가 좋아. 스스로를 달래는 말이라 마음이 놓였어."},{"who":"다인","text":"그런데 로운이 말을 들으니 이 시가 위로하는 시로도 읽히네."},{"who":"로운","text":"나도 네 말을 듣고 지우개 문지르는 소리가 다시 들렸어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L04_basic#6','kor',5,2,'u1','L04','g5_2_kor_u1_L04_basic','lesson_basic','K5-2-u1-C18',2,'mc','auto','다인이와 로운이가 의견을 나눈 뒤 생긴 일로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X16','K5-2-u1-X02','K5-2-u1-X15']::text[],false,'{"seq":6,"concept":"K5-2-u1-C18","difficulty":2,"kind":"mc","stem":"다인이와 로운이가 의견을 나눈 뒤 생긴 일로 알맞은 것은 어느 것인가요?","options":[{"t":"친구의 의견을 듣고 시를 새로운 관점으로 다시 보게 되었다","correct":true},{"t":"서로 다른 의견 때문에 시가 싫어졌다","mis":"K5-2-u1-X16"},{"t":"먼저 말한 다인이의 의견만 맞게 되었다","mis":"K5-2-u1-X02"},{"t":"둘 다 고른 부분을 바꾸어야 했다","mis":"K5-2-u1-X15"}],"explanation":["다른 의견이 시를 넓혀 줬어요.","먼저 말한 의견이 정답은 아니에요.","바꿀 필요는 없어요."],"asset":{"type":"speech","turns":[{"who":"다인","text":"나는 「괜스레 지우개만 박박 문지른다」가 인상적이야. 속상할 때 나도 괜히 물건을 만지작거리거든."},{"who":"로운","text":"나는 마지막 「괜찮아」가 좋아. 스스로를 달래는 말이라 마음이 놓였어."},{"who":"다인","text":"그런데 로운이 말을 들으니 이 시가 위로하는 시로도 읽히네."},{"who":"로운","text":"나도 네 말을 듣고 지우개 문지르는 소리가 다시 들렸어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L04_basic#7','kor',5,2,'u1','L04','g5_2_kor_u1_L04_basic','lesson_basic','K5-2-u1-C13',2,'mc','auto','공감하며 읽은 시를 친구에게 소개할 때 함께 말하면 좋은 것은 어느 것인가요?',ARRAY['K5-2-u1-X03','K5-2-u1-X01']::text[],false,'{"seq":7,"concept":"K5-2-u1-C13","difficulty":2,"kind":"mc","stem":"공감하며 읽은 시를 친구에게 소개할 때 함께 말하면 좋은 것은 어느 것인가요?","options":[{"t":"그 시에 공감한 까닭","correct":true},{"t":"시가 실린 책의 값","mis":"K5-2-u1-X03"},{"t":"시를 읽은 시각","mis":"K5-2-u1-X03"},{"t":"시의 글자 수","mis":"K5-2-u1-X01"}],"explanation":["값은 공감과 관계없어요.","시각은 까닭이 아니에요.","왜 공감했는지 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L04_basic#8','kor',5,2,'u1','L04','g5_2_kor_u1_L04_basic','lesson_basic','K5-2-u1-C16',2,'blank','auto','「괜찮아, 나」를 낭송할 때 마지막 「괜찮아」는 마음이 바뀌는 곳이므로 (     ) 읽으면 좋아요.',ARRAY['K5-2-u1-X10']::text[],false,'{"seq":8,"concept":"K5-2-u1-C16","difficulty":2,"kind":"blank","stem":"「괜찮아, 나」를 낭송할 때 마지막 「괜찮아」는 마음이 바뀌는 곳이므로 (     ) 읽으면 좋아요.","options":[{"t":"천천히 다독이듯","correct":true},{"t":"가장 빠르게 소리치듯","mis":"K5-2-u1-X10"},{"t":"앞 연과 똑같은 빠르기로","mis":"K5-2-u1-X10"},{"t":"아주 작게 웅얼거리듯","mis":"K5-2-u1-X10"}],"explanation":["달래는 마음과 어울리지 않아요.","마음이 바뀌는 곳은 다르게 읽어요.","스스로를 달래는 느낌을 살려요."],"asset":{"type":"passage","lines":["틀린 글씨 지우다가 / 종이가 북 찢어졌다","괜스레 지우개만 / 박박 문지른다","내 마음도 / 찢어진 종이처럼 구겨진다","손바닥으로 종이를 펴며 / 나에게 말해 본다 — 괜찮아"],"title":"시 「괜찮아, 나」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L04_basic#9','kor',5,2,'u1','L04','g5_2_kor_u1_L04_basic','lesson_basic','K5-2-u1-C19',2,'mc','auto','「방학 마지막 날」을 그림으로 감상할 때 가장 중요한 것은 어느 것인가요?',ARRAY['K5-2-u1-X17','K5-2-u1-X02']::text[],false,'{"seq":9,"concept":"K5-2-u1-C19","difficulty":2,"kind":"mc","stem":"「방학 마지막 날」을 그림으로 감상할 때 가장 중요한 것은 어느 것인가요?","options":[{"t":"어떤 부분을 왜 골라 그렸는지 말하는 것","correct":true},{"t":"누가 가장 잘 그렸는지 겨루는 것","mis":"K5-2-u1-X17"},{"t":"모두 같은 장면을 그리는 것","mis":"K5-2-u1-X02"},{"t":"색칠을 빈틈없이 하는 것","mis":"K5-2-u1-X17"}],"explanation":["솜씨를 겨루는 활동이 아니에요.","고른 장면은 달라도 돼요.","고른 부분과 까닭이 중요해요."],"asset":{"type":"passage","lines":["해가 지붕에서 미끄러지면 / 시곗바늘을 살짝 붙잡고 싶다","책가방은 문 앞에서 / 나를 빤히 쳐다보고","나는 이불 속으로 숨어 / 방학 하루를 한 번 더 접어 둔다"],"title":"시 「방학 마지막 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L04_basic#10','kor',5,2,'u1','L04','g5_2_kor_u1_L04_basic','lesson_basic','K5-2-u1-C14',3,'mc','auto','「괜스레」를 넣어 만든 문장으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X13']::text[],false,'{"seq":10,"concept":"K5-2-u1-C14","difficulty":3,"kind":"mc","stem":"「괜스레」를 넣어 만든 문장으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"말을 꺼내기 어려워서 괜스레 연필만 만지작거렸다.","correct":true},{"t":"숙제를 다 해서 괜스레 마음이 놓였다.","mis":"K5-2-u1-X13"},{"t":"넘어졌지만 괜스레 다치지 않았다.","mis":"K5-2-u1-X13"},{"t":"비가 와서 괜스레 우산을 썼다.","mis":"K5-2-u1-X13"}],"explanation":["까닭이 분명히 있는 일이에요.","「괜찮게」로 잘못 썼어요.","까닭이 분명한 일에는 어울리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L04_challenge#1','kor',5,2,'u1','L04','g5_2_kor_u1_L04_challenge','lesson_challenge','K5-2-u1-C15',2,'mc','auto','「괜찮아, 나」에서 말하는 이의 행동이 어떻게 달라졌는지 바르게 말한 것은 어느 것인가요?',ARRAY['K5-2-u1-X14','K5-2-u1-X06']::text[],false,'{"seq":1,"concept":"K5-2-u1-C15","difficulty":2,"kind":"mc","stem":"「괜찮아, 나」에서 말하는 이의 행동이 어떻게 달라졌는지 바르게 말한 것은 어느 것인가요?","options":[{"t":"지우개를 박박 문지르다가, 손바닥으로 종이를 펴며 스스로를 달랜다","correct":true},{"t":"처음부터 끝까지 지우개만 문지른다","mis":"K5-2-u1-X14"},{"t":"종이를 펴다가 다시 찢어 버린다","mis":"K5-2-u1-X14"},{"t":"친구에게 새 종이를 빌린다","mis":"K5-2-u1-X06"}],"explanation":["행동이 바뀌어요.","찢어 버리지 않았어요.","친구 이야기는 없어요."],"asset":{"type":"passage","lines":["틀린 글씨 지우다가 / 종이가 북 찢어졌다","괜스레 지우개만 / 박박 문지른다","내 마음도 / 찢어진 종이처럼 구겨진다","손바닥으로 종이를 펴며 / 나에게 말해 본다 — 괜찮아"],"title":"시 「괜찮아, 나」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L04_challenge#2','kor',5,2,'u1','L04','g5_2_kor_u1_L04_challenge','lesson_challenge','K5-2-u1-C17',2,'mc','auto','같은 시에서 친구마다 까닭이 다른 이유가 아닌 것은 어느 것인가요?',ARRAY['K5-2-u1-X15']::text[],false,'{"seq":2,"concept":"K5-2-u1-C17","difficulty":2,"kind":"mc","stem":"같은 시에서 친구마다 까닭이 다른 이유가 아닌 것은 어느 것인가요?","options":[{"t":"한 사람만 시를 바르게 읽었기 때문에","correct":true},{"t":"겪어 본 일이 달라서","mis":"K5-2-u1-X15"},{"t":"관심 있는 것이 달라서","mis":"K5-2-u1-X15"},{"t":"알고 있는 배경지식이 달라서","mis":"K5-2-u1-X15"}],"explanation":["경험이 다르면 까닭도 달라요.","관심이 다르면 눈길이 가는 곳도 달라요.","바르게 읽은 사람이 한 명뿐인 게 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L04_challenge#3','kor',5,2,'u1','L04','g5_2_kor_u1_L04_challenge','lesson_challenge','K5-2-u1-C18',3,'error','auto','다인이와 로운이처럼 모둠에서 의견을 나누었어요. 알맞지 않은 태도는 어느 것인가요?',ARRAY['K5-2-u1-X16','K5-2-u1-X15','K5-2-u1-X03']::text[],false,'{"seq":3,"concept":"K5-2-u1-C18","difficulty":3,"kind":"error","stem":"다인이와 로운이처럼 모둠에서 의견을 나누었어요. 알맞지 않은 태도는 어느 것인가요?","options":[{"t":"「내 생각과 다르니까 네 말은 들을 필요가 없어.」","correct":true,"mis_target":"K5-2-u1-X16"},{"t":"「네가 고른 부분은 나와 다르지만, 그 까닭을 들으니 새롭게 보여.」","mis":"K5-2-u1-X15"},{"t":"「너는 왜 그 연을 골랐는지 끝까지 들어 볼게.」","mis":"K5-2-u1-X03"}],"explanation":["다른 의견에서 배웠어요.","끝까지 들으려 해요.","다른 의견을 끝까지 듣고 견줘요."],"asset":{"type":"speech","turns":[{"who":"다인","text":"나는 「괜스레 지우개만 박박 문지른다」가 인상적이야. 속상할 때 나도 괜히 물건을 만지작거리거든."},{"who":"로운","text":"나는 마지막 「괜찮아」가 좋아. 스스로를 달래는 말이라 마음이 놓였어."},{"who":"다인","text":"그런데 로운이 말을 들으니 이 시가 위로하는 시로도 읽히네."},{"who":"로운","text":"나도 네 말을 듣고 지우개 문지르는 소리가 다시 들렸어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L04_challenge#4','kor',5,2,'u1','L04','g5_2_kor_u1_L04_challenge','lesson_challenge','K5-2-u1-C13',3,'mc','auto','공감하며 읽은 시를 소개하는 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X03','K5-2-u1-X12']::text[],false,'{"seq":4,"concept":"K5-2-u1-C13","difficulty":3,"kind":"mc","stem":"공감하며 읽은 시를 소개하는 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「이 시는 이사 간 친구를 그리워하는 시야. 나도 친한 친구가 전학 가서 같은 마음이었어.」","correct":true},{"t":"「이 시는 짧아서 좋아.」","mis":"K5-2-u1-X03"},{"t":"「나는 이사를 가 본 적이 없어서 이 시에 공감할 수 없어.」","mis":"K5-2-u1-X12"},{"t":"「이 시는 우리 반에서 나만 읽었어.」","mis":"K5-2-u1-X03"}],"explanation":["짧다는 건 공감의 까닭이 아니에요.","똑같은 일이 아니어도 비슷한 마음이면 공감해요.","어떤 시인지와 공감한 까닭을 함께 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L04_challenge#5','kor',5,2,'u1','L04','g5_2_kor_u1_L04_challenge','lesson_challenge','K5-2-u1-C19',3,'ox','auto','「방학 마지막 날」을 읽고 친구는 이불 속 장면을, 나는 시곗바늘 장면을 그렸다면 둘 중 하나는 잘못 감상한 거예요.',ARRAY['K5-2-u1-X15']::text[],false,'{"seq":5,"concept":"K5-2-u1-C19","difficulty":3,"kind":"ox","stem":"「방학 마지막 날」을 읽고 친구는 이불 속 장면을, 나는 시곗바늘 장면을 그렸다면 둘 중 하나는 잘못 감상한 거예요.","answer":"X","reason_options":[{"t":"같은 시에서도 인상적인 부분은 다를 수 있고, 고른 까닭을 말하면 둘 다 의미 있는 감상이기 때문에","correct":true},{"t":"한 시에서 그릴 장면은 하나로 정해져 있기 때문에","mis":"K5-2-u1-X15"}],"mis":"K5-2-u1-X15","explanation":["고른 장면은 달라도 돼요.","까닭을 말하면 돼요.","다른 그림이 생각을 넓혀 줘요."],"asset":{"type":"passage","lines":["해가 지붕에서 미끄러지면 / 시곗바늘을 살짝 붙잡고 싶다","책가방은 문 앞에서 / 나를 빤히 쳐다보고","나는 이불 속으로 숨어 / 방학 하루를 한 번 더 접어 둔다"],"title":"시 「방학 마지막 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L04_challenge#6','kor',5,2,'u1','L04','g5_2_kor_u1_L04_challenge','lesson_challenge','K5-2-u1-C11',3,'mc','auto','「해가 지붕에서 미끄러지면 / 시곗바늘을 살짝 붙잡고 싶다」에 담긴 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X09','K5-2-u1-X14']::text[],false,'{"seq":6,"concept":"K5-2-u1-C11","difficulty":3,"kind":"mc","stem":"「해가 지붕에서 미끄러지면 / 시곗바늘을 살짝 붙잡고 싶다」에 담긴 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"방학이 끝나는 것이 아쉬워 시간을 붙잡고 싶은 마음","correct":true},{"t":"시계가 고장 나서 고치고 싶은 마음","mis":"K5-2-u1-X09"},{"t":"지붕에 올라가고 싶은 마음","mis":"K5-2-u1-X09"},{"t":"빨리 학교에 가고 싶은 마음","mis":"K5-2-u1-X14"}],"explanation":["정말 시계를 붙잡는 게 아니에요.","지붕에 오르려는 게 아니에요.","해 지는 게 아쉬운 마음이에요."],"asset":{"type":"passage","lines":["해가 지붕에서 미끄러지면 / 시곗바늘을 살짝 붙잡고 싶다","책가방은 문 앞에서 / 나를 빤히 쳐다보고","나는 이불 속으로 숨어 / 방학 하루를 한 번 더 접어 둔다"],"title":"시 「방학 마지막 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L04_challenge#7','kor',5,2,'u1','L04','g5_2_kor_u1_L04_challenge','lesson_challenge','K5-2-u1-C16',3,'mc','auto','「괜찮아, 나」를 모둠이 연을 나누어 낭송할 때 가장 알맞은 계획은 어느 것인가요?',ARRAY['K5-2-u1-X10','K5-2-u1-X14']::text[],false,'{"seq":7,"concept":"K5-2-u1-C16","difficulty":3,"kind":"mc","stem":"「괜찮아, 나」를 모둠이 연을 나누어 낭송할 때 가장 알맞은 계획은 어느 것인가요?","options":[{"t":"앞의 두 연은 속상하고 빠르게, 마지막 연은 천천히 다독이듯 읽는다","correct":true},{"t":"네 연을 모두 같은 크기와 빠르기로 읽는다","mis":"K5-2-u1-X10"},{"t":"가장 목소리 큰 친구가 혼자 다 읽는다","mis":"K5-2-u1-X10"},{"t":"마지막 연을 가장 빠르게 소리친다","mis":"K5-2-u1-X14"}],"explanation":["마음이 바뀌는 곳을 살려요.","나누어 맡아 이어 읽어요.","달래는 마음과 어울리지 않아요."],"asset":{"type":"passage","lines":["틀린 글씨 지우다가 / 종이가 북 찢어졌다","괜스레 지우개만 / 박박 문지른다","내 마음도 / 찢어진 종이처럼 구겨진다","손바닥으로 종이를 펴며 / 나에게 말해 본다 — 괜찮아"],"title":"시 「괜찮아, 나」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L04_challenge#8','kor',5,2,'u1','L04','g5_2_kor_u1_L04_challenge','lesson_challenge','K5-2-u1-C17',4,'essay','teacher','「괜찮아, 나」에서 내가 고른 인상적인 부분과 까닭을 쓰고, 다인이나 로운이의 의견을 듣고 새롭게 알게 된 점을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u1-C17","difficulty":4,"kind":"essay","stem":"「괜찮아, 나」에서 내가 고른 인상적인 부분과 까닭을 쓰고, 다인이나 로운이의 의견을 듣고 새롭게 알게 된 점을 쓰세요.","answer_guide":{"answer":"예: 나는 셋째 연 「내 마음도 / 찢어진 종이처럼 구겨진다」가 인상적이다. 마음을 구겨진 종이에 빗대어 속상함이 눈에 보이는 것 같기 때문이다. 로운이의 말을 듣고 마지막 「괜찮아」가 스스로를 위로하는 말이라는 것을 알게 되어, 이 시가 속상함에서 끝나지 않고 위로로 끝나는 시라는 것을 새롭게 보았다.","scoring_points":["인상적인 부분을 골랐는가","까닭을 시와 이어 썼는가","친구 의견에서 새롭게 안 점을 썼는가"]},"explanation":["내 부분을 골라요.","까닭을 써요.","친구 말에서 넓어진 생각을 써요."],"asset":{"type":"speech","turns":[{"who":"다인","text":"나는 「괜스레 지우개만 박박 문지른다」가 인상적이야. 속상할 때 나도 괜히 물건을 만지작거리거든."},{"who":"로운","text":"나는 마지막 「괜찮아」가 좋아. 스스로를 달래는 말이라 마음이 놓였어."},{"who":"다인","text":"그런데 로운이 말을 들으니 이 시가 위로하는 시로도 읽히네."},{"who":"로운","text":"나도 네 말을 듣고 지우개 문지르는 소리가 다시 들렸어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L04_challenge#9','kor',5,2,'u1','L04','g5_2_kor_u1_L04_challenge','lesson_challenge','K5-2-u1-C19',4,'essay','teacher','「방학 마지막 날」에서 그림으로 그리고 싶은 장면을 하나 골라, 그림에 무엇을 그릴지와 그 장면을 고른 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u1-C19","difficulty":4,"kind":"essay","stem":"「방학 마지막 날」에서 그림으로 그리고 싶은 장면을 하나 골라, 그림에 무엇을 그릴지와 그 장면을 고른 까닭을 쓰세요.","answer_guide":{"answer":"예: 셋째 연 「나는 이불 속으로 숨어 / 방학 하루를 한 번 더 접어 둔다」를 그리겠다. 이불을 머리끝까지 덮은 아이와, 종이처럼 접힌 달력 한 장을 그리겠다. 하루를 접어 둔다는 표현이 방학을 아끼고 싶은 마음을 재미있게 보여 주고, 나도 방학 마지막 날에 일찍 자기 싫었던 적이 있어서 이 장면을 골랐다.","scoring_points":["장면을 시에서 골랐는가","그릴 모습을 썼는가","고른 까닭을 썼는가"]},"explanation":["장면을 골라요.","무엇을 그릴지 정해요.","까닭을 붙여요."],"asset":{"type":"passage","lines":["해가 지붕에서 미끄러지면 / 시곗바늘을 살짝 붙잡고 싶다","책가방은 문 앞에서 / 나를 빤히 쳐다보고","나는 이불 속으로 숨어 / 방학 하루를 한 번 더 접어 둔다"],"title":"시 「방학 마지막 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L04_challenge#10','kor',5,2,'u1','L04','g5_2_kor_u1_L04_challenge','lesson_challenge','K5-2-u1-C18',4,'essay','teacher','친구와 시에 대한 의견을 나눌 때 지켜야 할 태도 두 가지를 쓰고, 그렇게 하면 좋은 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u1-C18","difficulty":4,"kind":"essay","stem":"친구와 시에 대한 의견을 나눌 때 지켜야 할 태도 두 가지를 쓰고, 그렇게 하면 좋은 점을 쓰세요.","answer_guide":{"answer":"예: 첫째, 친구의 의견을 끝까지 듣는다. 둘째, 나와 다른 의견이라도 틀렸다고 하지 않고 그 까닭을 들어 본다. 이렇게 하면 내가 미처 생각하지 못한 부분을 알게 되어 같은 시를 새로운 관점으로 다시 볼 수 있다.","scoring_points":["태도 두 가지를 썼는가","경청과 존중이 드러나는가","좋은 점을 썼는가"]},"explanation":["듣는 태도를 떠올려요.","다른 의견을 대하는 태도를 써요.","좋은 점을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L07_basic#1','kor',5,2,'u1','L07','g5_2_kor_u1_L07_basic','lesson_basic','K5-2-u1-C20',1,'mc','auto','「전기문」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X18','K5-2-u1-X27']::text[],false,'{"seq":1,"concept":"K5-2-u1-C20","difficulty":1,"kind":"mc","stem":"「전기문」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"실제로 살았던 인물의 삶을 사실에 근거하여 쓴 글","correct":true},{"t":"지어낸 인물이 나오는 옛이야기","mis":"K5-2-u1-X18"},{"t":"날마다 겪은 일을 쓴 일기","mis":"K5-2-u1-X18"},{"t":"책을 읽고 평가한 글","mis":"K5-2-u1-X27"}],"explanation":["지어낸 인물이 아니에요.","일기와 달라요.","그건 서평이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L07_basic#2','kor',5,2,'u1','L07','g5_2_kor_u1_L07_basic','lesson_basic','K5-2-u1-C22',1,'mc','auto','유관순이 살았던 시대의 상황으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X20']::text[],false,'{"seq":2,"concept":"K5-2-u1-C22","difficulty":1,"kind":"mc","stem":"유관순이 살았던 시대의 상황으로 알맞은 것은 어느 것인가요?","options":[{"t":"일본에 나라를 빼앗긴 일제 강점기","correct":true},{"t":"나라를 처음 세운 때","mis":"K5-2-u1-X20"},{"t":"한글을 처음 만든 때","mis":"K5-2-u1-X20"},{"t":"오늘날과 똑같은 때","mis":"K5-2-u1-X20"}],"explanation":["나라를 세운 때가 아니에요.","한글은 훨씬 전에 만들었어요.","만세를 부른 까닭이 이 상황에 있어요."],"asset":{"type":"passage","lines":["1902년, 유관순은 충청남도의 작은 마을에서 태어났어요.","아버지는 「나라의 힘을 기르려면 새 학문을 배워야 한다」며","딸을 서울의 이화학당에 보냈어요.","유관순은 방학이면 고향에 내려가 우리글을 모르는 마을 사람들에게 글을 가르쳤어요.","1919년 3월 1일, 유관순도 친구들과 거리에 나가 「대한 독립 만세」를 불렀어요."],"title":"전기문 「유관순」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L07_basic#3','kor',5,2,'u1','L07','g5_2_kor_u1_L07_basic','lesson_basic','K5-2-u1-C20',1,'ox','auto','「유관순」은 실제로 살았던 인물의 이야기예요.',ARRAY['K5-2-u1-X18']::text[],false,'{"seq":3,"concept":"K5-2-u1-C20","difficulty":1,"kind":"ox","stem":"「유관순」은 실제로 살았던 인물의 이야기예요.","answer":"O","reason_options":[{"t":"실제 인물의 삶을 사실에 근거하여 쓴 전기문이기 때문에","correct":true},{"t":"지어낸 이야기에 나오는 인물이기 때문에","mis":"K5-2-u1-X18"}],"mis":"K5-2-u1-X18","explanation":["실제 인물이에요.","사실에 근거해요.","그래서 전기문이라고 해요."],"asset":{"type":"passage","lines":["1902년, 유관순은 충청남도의 작은 마을에서 태어났어요.","아버지는 「나라의 힘을 기르려면 새 학문을 배워야 한다」며","딸을 서울의 이화학당에 보냈어요.","유관순은 방학이면 고향에 내려가 우리글을 모르는 마을 사람들에게 글을 가르쳤어요.","1919년 3월 1일, 유관순도 친구들과 거리에 나가 「대한 독립 만세」를 불렀어요."],"title":"전기문 「유관순」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L07_basic#4','kor',5,2,'u1','L07','g5_2_kor_u1_L07_basic','lesson_basic','K5-2-u1-C23',1,'mc','auto','유관순이 방학이면 고향 사람들에게 글을 가르친 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X21']::text[],false,'{"seq":4,"concept":"K5-2-u1-C23","difficulty":1,"kind":"mc","stem":"유관순이 방학이면 고향 사람들에게 글을 가르친 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"배운 것을 나누어 사람들의 힘을 기르고 싶어서","correct":true},{"t":"방학 숙제였기 때문에","mis":"K5-2-u1-X21"},{"t":"고향이 심심해서","mis":"K5-2-u1-X21"},{"t":"글을 가르치면 돈을 받아서","mis":"K5-2-u1-X21"}],"explanation":["숙제 이야기는 없어요.","심심해서가 아니에요.","아버지의 말과 이어 생각해요."],"asset":{"type":"passage","lines":["1902년, 유관순은 충청남도의 작은 마을에서 태어났어요.","아버지는 「나라의 힘을 기르려면 새 학문을 배워야 한다」며","딸을 서울의 이화학당에 보냈어요.","유관순은 방학이면 고향에 내려가 우리글을 모르는 마을 사람들에게 글을 가르쳤어요.","1919년 3월 1일, 유관순도 친구들과 거리에 나가 「대한 독립 만세」를 불렀어요."],"title":"전기문 「유관순」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L07_basic#5','kor',5,2,'u1','L07','g5_2_kor_u1_L07_basic','lesson_basic','K5-2-u1-C23',2,'match','auto','유관순이 처한 상황과 그때 한 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K5-2-u1-C23","difficulty":2,"kind":"match","stem":"유관순이 처한 상황과 그때 한 일을 알맞게 이으세요.","pairs":[{"l":"일본이 학교 문을 닫았을 때","r":"고향으로 돌아와 만세 운동을 준비했다"},{"l":"함께할 사람이 필요했을 때","r":"이 마을 저 마을을 다니며 부탁했다"},{"l":"붙잡혀 재판을 받을 때","r":"조금도 굽히지 않았다"}],"mis":"K5-2-u1-X21","explanation":["학교가 닫히자 고향에서 준비했어요.","사람을 모으려 다녔어요.","끝까지 뜻을 지켰어요."],"asset":{"type":"passage","lines":["일본이 학교 문을 닫자 유관순은 고향으로 돌아와 만세 운동을 준비했어요.","사촌 언니와 함께 이 마을 저 마을을 다니며 함께하자고 부탁했어요.","밤에는 가족과 태극기를 만들었어요.","1919년 4월 1일, 아우내 장터에 모인 사람들 앞에서","유관순은 「나라를 되찾아야 합니다」라고 외쳤어요.","붙잡혀 재판을 받을 때도 조금도 굽히지 않았고, 1920년 감옥에서 숨을 거두었어요."],"title":"전기문 「유관순」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L07_basic#6','kor',5,2,'u1','L07','g5_2_kor_u1_L07_basic','lesson_basic','K5-2-u1-C21',2,'mc','auto','전기문에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['K5-2-u1-X19','K5-2-u1-X18']::text[],false,'{"seq":6,"concept":"K5-2-u1-C21","difficulty":2,"kind":"mc","stem":"전기문에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"사건은 사실에 바탕을 두지만 인물의 말은 작가가 다시 꾸몄을 수도 있다","correct":true},{"t":"인물의 말은 모두 그날 그대로 받아 적은 것이다","mis":"K5-2-u1-X19"},{"t":"사실과 상관없이 마음대로 지어낸 글이다","mis":"K5-2-u1-X18"},{"t":"인물의 말은 하나도 실을 수 없다","mis":"K5-2-u1-X19"}],"explanation":["그대로 받아 적었다고 단정할 수 없어요.","사실에 근거해요.","말을 실을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L07_basic#7','kor',5,2,'u1','L07','g5_2_kor_u1_L07_basic','lesson_basic','K5-2-u1-C24',2,'mc','auto','「유관순」 ②에서 인상적인 부분으로 고를 수 있는 것을 바르게 말한 것은 어느 것인가요?',ARRAY['K5-2-u1-X22','K5-2-u1-X01']::text[],false,'{"seq":7,"concept":"K5-2-u1-C24","difficulty":2,"kind":"mc","stem":"「유관순」 ②에서 인상적인 부분으로 고를 수 있는 것을 바르게 말한 것은 어느 것인가요?","options":[{"t":"사건의 흐름, 인물의 말과 행동, 이야기의 분위기 모두 고를 수 있다","correct":true},{"t":"아우내 장터 장면 하나만 고를 수 있다","mis":"K5-2-u1-X22"},{"t":"글의 첫 문장만 고를 수 있다","mis":"K5-2-u1-X22"},{"t":"인물의 이름만 고를 수 있다","mis":"K5-2-u1-X01"}],"explanation":["큰 사건 하나만이 아니에요.","첫 문장만이 아니에요.","여러 가지가 인상적인 부분이 돼요."],"asset":{"type":"passage","lines":["일본이 학교 문을 닫자 유관순은 고향으로 돌아와 만세 운동을 준비했어요.","사촌 언니와 함께 이 마을 저 마을을 다니며 함께하자고 부탁했어요.","밤에는 가족과 태극기를 만들었어요.","1919년 4월 1일, 아우내 장터에 모인 사람들 앞에서","유관순은 「나라를 되찾아야 합니다」라고 외쳤어요.","붙잡혀 재판을 받을 때도 조금도 굽히지 않았고, 1920년 감옥에서 숨을 거두었어요."],"title":"전기문 「유관순」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L07_basic#8','kor',5,2,'u1','L07','g5_2_kor_u1_L07_basic','lesson_basic','K5-2-u1-C25',2,'mc','auto','인상적인 부분을 중심으로 유관순에게 할 질문으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X23']::text[],false,'{"seq":8,"concept":"K5-2-u1-C25","difficulty":2,"kind":"mc","stem":"인상적인 부분을 중심으로 유관순에게 할 질문으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「붙잡혀서도 굽히지 않을 수 있었던 힘은 무엇이었나요?」","correct":true},{"t":"「태어난 해가 언제인가요?」","mis":"K5-2-u1-X23"},{"t":"「좋아하는 음식은 무엇인가요?」","mis":"K5-2-u1-X23"},{"t":"「이화학당은 어느 도시에 있었나요?」","mis":"K5-2-u1-X23"}],"explanation":["글에 답이 그대로 있는 질문이에요.","인상적인 부분과 관계없어요.","마음을 깊이 묻는 질문이에요."],"asset":{"type":"passage","lines":["일본이 학교 문을 닫자 유관순은 고향으로 돌아와 만세 운동을 준비했어요.","사촌 언니와 함께 이 마을 저 마을을 다니며 함께하자고 부탁했어요.","밤에는 가족과 태극기를 만들었어요.","1919년 4월 1일, 아우내 장터에 모인 사람들 앞에서","유관순은 「나라를 되찾아야 합니다」라고 외쳤어요.","붙잡혀 재판을 받을 때도 조금도 굽히지 않았고, 1920년 감옥에서 숨을 거두었어요."],"title":"전기문 「유관순」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L07_basic#9','kor',5,2,'u1','L07','g5_2_kor_u1_L07_basic','lesson_basic','K5-2-u1-C22',2,'blank','auto','유관순이 「나라를 되찾아야 합니다」라고 외친 까닭은 그때 우리나라가 (     ) 상황이었기 때문이에요.',ARRAY['K5-2-u1-X20']::text[],false,'{"seq":9,"concept":"K5-2-u1-C22","difficulty":2,"kind":"blank","stem":"유관순이 「나라를 되찾아야 합니다」라고 외친 까닭은 그때 우리나라가 (     ) 상황이었기 때문이에요.","options":[{"t":"일본에 나라를 빼앗긴","correct":true},{"t":"다른 나라와 친하게 지내던","mis":"K5-2-u1-X20"},{"t":"새 임금을 뽑던","mis":"K5-2-u1-X20"},{"t":"학교가 처음 생기던","mis":"K5-2-u1-X20"}],"explanation":["시대 상황과 맞지 않아요.","임금을 뽑던 때가 아니에요.","시대 상황을 알면 외침이 이해돼요."],"asset":{"type":"passage","lines":["일본이 학교 문을 닫자 유관순은 고향으로 돌아와 만세 운동을 준비했어요.","사촌 언니와 함께 이 마을 저 마을을 다니며 함께하자고 부탁했어요.","밤에는 가족과 태극기를 만들었어요.","1919년 4월 1일, 아우내 장터에 모인 사람들 앞에서","유관순은 「나라를 되찾아야 합니다」라고 외쳤어요.","붙잡혀 재판을 받을 때도 조금도 굽히지 않았고, 1920년 감옥에서 숨을 거두었어요."],"title":"전기문 「유관순」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L07_basic#10','kor',5,2,'u1','L07','g5_2_kor_u1_L07_basic','lesson_basic','K5-2-u1-C26',3,'mc','auto','「유관순」을 읽고 오늘의 나와 이어 생각한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X24','K5-2-u1-X21','K5-2-u1-X18']::text[],false,'{"seq":10,"concept":"K5-2-u1-C26","difficulty":3,"kind":"mc","stem":"「유관순」을 읽고 오늘의 나와 이어 생각한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「내가 옳다고 믿는 일을 끝까지 지키는 용기를 본받고 싶어.」","correct":true},{"t":"「옛날 일이라 지금의 나와는 관계없어.」","mis":"K5-2-u1-X24"},{"t":"「만세를 부르는 장면은 크게 소리 지르는 연습이야.」","mis":"K5-2-u1-X21"},{"t":"「전기문은 다 지어낸 이야기니까 본받을 건 없어.」","mis":"K5-2-u1-X18"}],"explanation":["옛이야기도 오늘에 뜻이 있어요.","상황과 떼어 읽었어요.","실제 인물의 삶이에요."],"asset":{"type":"passage","lines":["일본이 학교 문을 닫자 유관순은 고향으로 돌아와 만세 운동을 준비했어요.","사촌 언니와 함께 이 마을 저 마을을 다니며 함께하자고 부탁했어요.","밤에는 가족과 태극기를 만들었어요.","1919년 4월 1일, 아우내 장터에 모인 사람들 앞에서","유관순은 「나라를 되찾아야 합니다」라고 외쳤어요.","붙잡혀 재판을 받을 때도 조금도 굽히지 않았고, 1920년 감옥에서 숨을 거두었어요."],"title":"전기문 「유관순」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L07_challenge#1','kor',5,2,'u1','L07','g5_2_kor_u1_L07_challenge','lesson_challenge','K5-2-u1-C21',2,'mc','auto','「유관순」 ①에서 작가가 다시 꾸며 표현했을 수 있는 부분으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X19']::text[],false,'{"seq":1,"concept":"K5-2-u1-C21","difficulty":2,"kind":"mc","stem":"「유관순」 ①에서 작가가 다시 꾸며 표현했을 수 있는 부분으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"아버지가 한 말 「나라의 힘을 기르려면 새 학문을 배워야 한다」","correct":true},{"t":"1902년에 태어났다는 것","mis":"K5-2-u1-X19"},{"t":"이화학당에 다녔다는 것","mis":"K5-2-u1-X19"},{"t":"1919년 3월 1일에 만세를 불렀다는 것","mis":"K5-2-u1-X19"}],"explanation":["기록으로 확인되는 사실이에요.","기록으로 확인되는 사실이에요.","그날의 말 그대로인지는 알 수 없어요."],"asset":{"type":"passage","lines":["1902년, 유관순은 충청남도의 작은 마을에서 태어났어요.","아버지는 「나라의 힘을 기르려면 새 학문을 배워야 한다」며","딸을 서울의 이화학당에 보냈어요.","유관순은 방학이면 고향에 내려가 우리글을 모르는 마을 사람들에게 글을 가르쳤어요.","1919년 3월 1일, 유관순도 친구들과 거리에 나가 「대한 독립 만세」를 불렀어요."],"title":"전기문 「유관순」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L07_challenge#2','kor',5,2,'u1','L07','g5_2_kor_u1_L07_challenge','lesson_challenge','K5-2-u1-C22',2,'mc','auto','전기문을 읽을 때 시대적 상황을 알아야 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X20','K5-2-u1-X21']::text[],false,'{"seq":2,"concept":"K5-2-u1-C22","difficulty":2,"kind":"mc","stem":"전기문을 읽을 때 시대적 상황을 알아야 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"인물이 왜 그런 일을 했는지 이해할 수 있기 때문에","correct":true},{"t":"연도를 외우면 시험을 잘 보기 때문에","mis":"K5-2-u1-X20"},{"t":"시대만 알면 인물을 몰라도 되기 때문에","mis":"K5-2-u1-X21"},{"t":"시대 상황은 이야기와 관계없기 때문에","mis":"K5-2-u1-X20"}],"explanation":["외우기가 목적이 아니에요.","인물의 말과 행동도 함께 봐요.","상황이 행동의 까닭이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L07_challenge#3','kor',5,2,'u1','L07','g5_2_kor_u1_L07_challenge','lesson_challenge','K5-2-u1-C21',3,'error','auto','「유관순」 ②를 읽고 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u1-X19','K5-2-u1-X18','K5-2-u1-X22']::text[],false,'{"seq":3,"concept":"K5-2-u1-C21","difficulty":3,"kind":"error","stem":"「유관순」 ②를 읽고 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「장터에서 외친 말은 기록이 남은 그날 그대로의 말이 틀림없어.」","correct":true,"mis_target":"K5-2-u1-X19"},{"t":"「아우내 장터에서 만세 운동이 있었던 것은 역사적 사실이야.」","mis":"K5-2-u1-X18"},{"t":"「밤에 가족과 태극기를 만든 장면에서 긴장된 마음이 느껴져.」","mis":"K5-2-u1-X22"}],"explanation":["사실을 바르게 말했어요.","장면과 이어 감상했어요.","말은 작가가 다시 꾸몄을 수 있어요."],"asset":{"type":"passage","lines":["일본이 학교 문을 닫자 유관순은 고향으로 돌아와 만세 운동을 준비했어요.","사촌 언니와 함께 이 마을 저 마을을 다니며 함께하자고 부탁했어요.","밤에는 가족과 태극기를 만들었어요.","1919년 4월 1일, 아우내 장터에 모인 사람들 앞에서","유관순은 「나라를 되찾아야 합니다」라고 외쳤어요.","붙잡혀 재판을 받을 때도 조금도 굽히지 않았고, 1920년 감옥에서 숨을 거두었어요."],"title":"전기문 「유관순」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L07_challenge#4','kor',5,2,'u1','L07','g5_2_kor_u1_L07_challenge','lesson_challenge','K5-2-u1-C23',3,'mc','auto','유관순이 「이 마을 저 마을을 다니며 함께하자고 부탁한」 행동에서 짐작할 수 있는 마음은 어느 것인가요?',ARRAY['K5-2-u1-X21']::text[],false,'{"seq":4,"concept":"K5-2-u1-C23","difficulty":3,"kind":"mc","stem":"유관순이 「이 마을 저 마을을 다니며 함께하자고 부탁한」 행동에서 짐작할 수 있는 마음은 어느 것인가요?","options":[{"t":"여럿이 함께해야 나라를 되찾을 수 있다는 마음","correct":true},{"t":"마을 구경을 하고 싶은 마음","mis":"K5-2-u1-X21"},{"t":"혼자서도 충분하다는 마음","mis":"K5-2-u1-X21"},{"t":"학교에 빨리 돌아가고 싶은 마음","mis":"K5-2-u1-X21"}],"explanation":["구경이 목적이 아니에요.","함께하자고 부탁했어요.","상황과 행동을 이어 짐작해요."],"asset":{"type":"passage","lines":["일본이 학교 문을 닫자 유관순은 고향으로 돌아와 만세 운동을 준비했어요.","사촌 언니와 함께 이 마을 저 마을을 다니며 함께하자고 부탁했어요.","밤에는 가족과 태극기를 만들었어요.","1919년 4월 1일, 아우내 장터에 모인 사람들 앞에서","유관순은 「나라를 되찾아야 합니다」라고 외쳤어요.","붙잡혀 재판을 받을 때도 조금도 굽히지 않았고, 1920년 감옥에서 숨을 거두었어요."],"title":"전기문 「유관순」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L07_challenge#5','kor',5,2,'u1','L07','g5_2_kor_u1_L07_challenge','lesson_challenge','K5-2-u1-C24',3,'mc','auto','「유관순」 ①과 ②를 이어 읽을 때 인상적인 부분으로 고를 만한 「인물의 변화」는 어느 것인가요?',ARRAY['K5-2-u1-X22','K5-2-u1-X01']::text[],false,'{"seq":5,"concept":"K5-2-u1-C24","difficulty":3,"kind":"mc","stem":"「유관순」 ①과 ②를 이어 읽을 때 인상적인 부분으로 고를 만한 「인물의 변화」는 어느 것인가요?","options":[{"t":"배우던 학생이 고향 사람들을 모아 만세 운동을 이끄는 사람이 된다","correct":true},{"t":"태어난 마을의 이름이 바뀐다","mis":"K5-2-u1-X22"},{"t":"태극기의 색이 바뀐다","mis":"K5-2-u1-X22"},{"t":"글의 첫 문장이 바뀐다","mis":"K5-2-u1-X01"}],"explanation":["마을 이름 이야기는 없어요.","태극기 이야기가 아니에요.","인물이 어떻게 달라졌는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L07_challenge#6','kor',5,2,'u1','L07','g5_2_kor_u1_L07_challenge','lesson_challenge','K5-2-u1-C25',3,'ox','auto','「태어난 해는 언제인가요?」는 인상적인 부분을 중심으로 인물에게 하는 좋은 질문이에요.',ARRAY['K5-2-u1-X23']::text[],false,'{"seq":6,"concept":"K5-2-u1-C25","difficulty":3,"kind":"ox","stem":"「태어난 해는 언제인가요?」는 인상적인 부분을 중심으로 인물에게 하는 좋은 질문이에요.","answer":"X","reason_options":[{"t":"글에 답이 그대로 있어 인물의 마음을 깊이 생각하게 하지 못하기 때문에","correct":true},{"t":"인물에 대한 질문이면 무엇이든 좋은 질문이기 때문에","mis":"K5-2-u1-X23"}],"mis":"K5-2-u1-X23","explanation":["글에 답이 그대로 있어요.","마음을 묻는 질문이 좋아요.","인상적인 부분에서 출발해요."],"asset":{"type":"passage","lines":["1902년, 유관순은 충청남도의 작은 마을에서 태어났어요.","아버지는 「나라의 힘을 기르려면 새 학문을 배워야 한다」며","딸을 서울의 이화학당에 보냈어요.","유관순은 방학이면 고향에 내려가 우리글을 모르는 마을 사람들에게 글을 가르쳤어요.","1919년 3월 1일, 유관순도 친구들과 거리에 나가 「대한 독립 만세」를 불렀어요."],"title":"전기문 「유관순」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L07_challenge#7','kor',5,2,'u1','L07','g5_2_kor_u1_L07_challenge','lesson_challenge','K5-2-u1-C26',3,'mc','auto','「유관순」에서 본받을 점을 지금 우리 생활과 바르게 이은 것은 어느 것인가요?',ARRAY['K5-2-u1-X24','K5-2-u1-X21']::text[],false,'{"seq":7,"concept":"K5-2-u1-C26","difficulty":3,"kind":"mc","stem":"「유관순」에서 본받을 점을 지금 우리 생활과 바르게 이은 것은 어느 것인가요?","options":[{"t":"배운 것을 혼자 갖지 않고 나누었듯, 내가 아는 것을 친구에게 알려 준다","correct":true},{"t":"옛날 일이라 지금 생활과 이을 수 없다","mis":"K5-2-u1-X24"},{"t":"만세를 부르듯 교실에서 크게 소리친다","mis":"K5-2-u1-X21"},{"t":"재판을 받는 장면을 흉내 낸다","mis":"K5-2-u1-X21"}],"explanation":["옛이야기도 오늘과 이어져요.","상황과 떼어 흉내 내면 뜻을 놓쳐요.","흉내가 본받기는 아니에요."],"asset":{"type":"passage","lines":["1902년, 유관순은 충청남도의 작은 마을에서 태어났어요.","아버지는 「나라의 힘을 기르려면 새 학문을 배워야 한다」며","딸을 서울의 이화학당에 보냈어요.","유관순은 방학이면 고향에 내려가 우리글을 모르는 마을 사람들에게 글을 가르쳤어요.","1919년 3월 1일, 유관순도 친구들과 거리에 나가 「대한 독립 만세」를 불렀어요."],"title":"전기문 「유관순」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L07_challenge#8','kor',5,2,'u1','L07','g5_2_kor_u1_L07_challenge','lesson_challenge','K5-2-u1-C24',4,'essay','teacher','「유관순」에서 인상적인 부분을 하나 고르고, 그 부분이 인상적인 까닭을 인물이 처한 상황과 이어서 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u1-C24","difficulty":4,"kind":"essay","stem":"「유관순」에서 인상적인 부분을 하나 고르고, 그 부분이 인상적인 까닭을 인물이 처한 상황과 이어서 쓰세요.","answer_guide":{"answer":"예: 「붙잡혀 재판을 받을 때도 조금도 굽히지 않았고」가 인상적이다. 나라를 빼앗겨 바른말을 하면 붙잡히던 때였는데도 뜻을 꺾지 않았기 때문이다. 나라면 무서워서 말을 바꾸었을지도 모르는데, 그 상황에서 끝까지 굽히지 않은 용기가 크게 느껴졌다.","scoring_points":["인상적인 부분을 글에서 골랐는가","인물이 처한 상황을 썼는가","상황과 이어 까닭을 썼는가"]},"explanation":["한 부분을 골라요.","그때의 상황을 떠올려요.","상황과 까닭을 이어요."],"asset":{"type":"passage","lines":["일본이 학교 문을 닫자 유관순은 고향으로 돌아와 만세 운동을 준비했어요.","사촌 언니와 함께 이 마을 저 마을을 다니며 함께하자고 부탁했어요.","밤에는 가족과 태극기를 만들었어요.","1919년 4월 1일, 아우내 장터에 모인 사람들 앞에서","유관순은 「나라를 되찾아야 합니다」라고 외쳤어요.","붙잡혀 재판을 받을 때도 조금도 굽히지 않았고, 1920년 감옥에서 숨을 거두었어요."],"title":"전기문 「유관순」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L07_challenge#9','kor',5,2,'u1','L07','g5_2_kor_u1_L07_challenge','lesson_challenge','K5-2-u1-C25',4,'essay','teacher','「유관순」에서 인상적인 부분을 하나 고르고, 그 부분에서 유관순에게 묻고 싶은 질문과 내가 짐작한 유관순의 대답을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u1-C25","difficulty":4,"kind":"essay","stem":"「유관순」에서 인상적인 부분을 하나 고르고, 그 부분에서 유관순에게 묻고 싶은 질문과 내가 짐작한 유관순의 대답을 쓰세요.","answer_guide":{"answer":"예: 인상적인 부분 — 밤에 가족과 태극기를 만든 장면. 질문 — 「들키면 위험한데 어떤 마음으로 태극기를 만들었나요?」 짐작한 대답 — 「무서웠지만 다음 날 많은 사람이 태극기를 들고 함께 외칠 모습을 떠올리며 한 장 한 장 정성껏 만들었어요.」","scoring_points":["인상적인 부분을 골랐는가","그 부분에서 나온 질문을 썼는가","상황에 맞게 대답을 짐작했는가"]},"explanation":["인상적인 부분에서 출발해요.","마음을 묻는 질문을 만들어요.","상황에 맞게 짐작해요."],"asset":{"type":"passage","lines":["일본이 학교 문을 닫자 유관순은 고향으로 돌아와 만세 운동을 준비했어요.","사촌 언니와 함께 이 마을 저 마을을 다니며 함께하자고 부탁했어요.","밤에는 가족과 태극기를 만들었어요.","1919년 4월 1일, 아우내 장터에 모인 사람들 앞에서","유관순은 「나라를 되찾아야 합니다」라고 외쳤어요.","붙잡혀 재판을 받을 때도 조금도 굽히지 않았고, 1920년 감옥에서 숨을 거두었어요."],"title":"전기문 「유관순」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L07_challenge#10','kor',5,2,'u1','L07','g5_2_kor_u1_L07_challenge','lesson_challenge','K5-2-u1-C21',4,'essay','teacher','전기문을 읽을 때 「사실」과 「작가가 다시 꾸몄을 수 있는 부분」을 가려 읽어야 하는 까닭을 쓰고, 「유관순」에서 각각 예를 하나씩 드세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u1-C21","difficulty":4,"kind":"essay","stem":"전기문을 읽을 때 「사실」과 「작가가 다시 꾸몄을 수 있는 부분」을 가려 읽어야 하는 까닭을 쓰고, 「유관순」에서 각각 예를 하나씩 드세요.","answer_guide":{"answer":"예: 전기문은 실제 인물의 삶을 사실에 근거하여 쓰지만, 인물이 한 말이나 행동은 기록이 다 남아 있지 않아 작가가 상상하여 다시 꾸민 것일 수 있다. 그래서 무엇이 확인된 사실인지 가려 읽어야 인물을 바르게 알 수 있다. 사실 — 1919년 4월 1일 아우내 장터에서 만세 운동이 있었다. 다시 꾸몄을 수 있는 부분 — 아버지가 「새 학문을 배워야 한다」고 한 말.","scoring_points":["가려 읽어야 하는 까닭을 썼는가","사실의 예를 들었는가","다시 꾸몄을 수 있는 부분의 예를 들었는가"]},"explanation":["전기문의 특성을 떠올려요.","확인된 일을 찾아요.","말과 행동을 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L10_basic#1','kor',5,2,'u1','L10','g5_2_kor_u1_L10_basic','lesson_basic','K5-2-u1-C27',1,'mc','auto','「서평」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X25','K5-2-u1-X27','K5-2-u1-X26']::text[],false,'{"seq":1,"concept":"K5-2-u1-C27","difficulty":1,"kind":"mc","stem":"「서평」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"책에 대한 자신의 의견이나 평가를 까닭과 함께 밝힌 글","correct":true},{"t":"책의 줄거리를 처음부터 끝까지 옮겨 쓴 글","mis":"K5-2-u1-X25"},{"t":"책을 읽고 느낌만 자유롭게 쓴 글","mis":"K5-2-u1-X27"},{"t":"책의 좋은 점만 모아 쓴 광고","mis":"K5-2-u1-X26"}],"explanation":["줄거리를 다 옮기는 글이 아니에요.","그건 독서 감상문에 가까워요.","좋은 점만 쓰는 글이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L10_basic#2','kor',5,2,'u1','L10','g5_2_kor_u1_L10_basic','lesson_basic','K5-2-u1-C28',1,'match','auto','서평 「수요일의 텃밭」의 문장과 서평에 들어갈 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K5-2-u1-C28","difficulty":1,"kind":"match","stem":"서평 「수요일의 텃밭」의 문장과 서평에 들어갈 내용을 알맞게 이으세요.","pairs":[{"l":"5학년 아이들이 학교 텃밭을 가꾸며 겪는 일을 그린 동화예요","r":"책 소개"},{"l":"상추가 뽑히자 서로 의심하다가 다시 씨앗을 심기로 해요","r":"줄거리"},{"l":"뒷부분이 조금 서둘러 끝나는 점은 아쉬워요","r":"책에 대한 평가"}],"mis":"K5-2-u1-X25","explanation":["어떤 책인지 알려 줘요.","중요한 일만 간추렸어요.","아쉬운 점을 평가했어요."],"asset":{"type":"passage","lines":["〔제목〕 흙 묻은 손으로 맺은 약속","「수요일의 텃밭」은 5학년 아이들이 학교 텃밭을 가꾸며 겪는 일을 그린 동화예요.","상추가 밤사이 모두 뽑히자 아이들은 서로를 의심하다가, 다시 씨앗을 심기로 마음을 모아요.","가장 인상적인 부분은 의심받던 친구가 흙 묻은 손을 내미는 장면이에요.","오해가 풀리는 순간이 생생하기 때문이에요.","친구와 다투어 마음이 무거운 친구들에게 이 책을 권해요.","다만 뒷부분이 조금 서둘러 끝나는 점은 아쉬워요."],"title":"서평 「수요일의 텃밭」 (지어낸 책)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L10_basic#3','kor',5,2,'u1','L10','g5_2_kor_u1_L10_basic','lesson_basic','K5-2-u1-C28',1,'mc','auto','서평 「수요일의 텃밭」에서 인상적인 부분으로 고른 장면은 어느 것인가요?',ARRAY['K5-2-u1-X22']::text[],false,'{"seq":3,"concept":"K5-2-u1-C28","difficulty":1,"kind":"mc","stem":"서평 「수요일의 텃밭」에서 인상적인 부분으로 고른 장면은 어느 것인가요?","options":[{"t":"의심받던 친구가 흙 묻은 손을 내미는 장면","correct":true},{"t":"상추가 밤사이 모두 뽑힌 장면","mis":"K5-2-u1-X22"},{"t":"아이들이 처음 텃밭을 가꾸는 장면","mis":"K5-2-u1-X22"},{"t":"책이 끝나는 마지막 장면","mis":"K5-2-u1-X22"}],"explanation":["일어난 일로 소개했어요.","인상적인 부분으로 고르지 않았어요.","오해가 풀리는 순간을 골랐어요."],"asset":{"type":"passage","lines":["〔제목〕 흙 묻은 손으로 맺은 약속","「수요일의 텃밭」은 5학년 아이들이 학교 텃밭을 가꾸며 겪는 일을 그린 동화예요.","상추가 밤사이 모두 뽑히자 아이들은 서로를 의심하다가, 다시 씨앗을 심기로 마음을 모아요.","가장 인상적인 부분은 의심받던 친구가 흙 묻은 손을 내미는 장면이에요.","오해가 풀리는 순간이 생생하기 때문이에요.","친구와 다투어 마음이 무거운 친구들에게 이 책을 권해요.","다만 뒷부분이 조금 서둘러 끝나는 점은 아쉬워요."],"title":"서평 「수요일의 텃밭」 (지어낸 책)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L10_basic#4','kor',5,2,'u1','L10','g5_2_kor_u1_L10_basic','lesson_basic','K5-2-u1-C30',1,'ox','auto','서평에는 책의 좋은 점만 써야 해요.',ARRAY['K5-2-u1-X26']::text[],false,'{"seq":4,"concept":"K5-2-u1-C30","difficulty":1,"kind":"ox","stem":"서평에는 책의 좋은 점만 써야 해요.","answer":"X","reason_options":[{"t":"아쉬운 점도 그렇게 생각한 까닭과 함께 쓸 수 있기 때문에","correct":true},{"t":"서평은 책을 칭찬하는 글이기 때문에","mis":"K5-2-u1-X26"}],"mis":"K5-2-u1-X26","explanation":["아쉬운 점도 평가예요.","까닭과 함께 써요.","「수요일의 텃밭」 서평에도 아쉬운 점이 있어요."],"asset":{"type":"passage","lines":["〔제목〕 흙 묻은 손으로 맺은 약속","「수요일의 텃밭」은 5학년 아이들이 학교 텃밭을 가꾸며 겪는 일을 그린 동화예요.","상추가 밤사이 모두 뽑히자 아이들은 서로를 의심하다가, 다시 씨앗을 심기로 마음을 모아요.","가장 인상적인 부분은 의심받던 친구가 흙 묻은 손을 내미는 장면이에요.","오해가 풀리는 순간이 생생하기 때문이에요.","친구와 다투어 마음이 무거운 친구들에게 이 책을 권해요.","다만 뒷부분이 조금 서둘러 끝나는 점은 아쉬워요."],"title":"서평 「수요일의 텃밭」 (지어낸 책)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L10_basic#5','kor',5,2,'u1','L10','g5_2_kor_u1_L10_basic','lesson_basic','K5-2-u1-C29',2,'mc','auto','서평에 줄거리를 쓰는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X25','K5-2-u1-X29','K5-2-u1-X28']::text[],false,'{"seq":5,"concept":"K5-2-u1-C29","difficulty":2,"kind":"mc","stem":"서평에 줄거리를 쓰는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"중요한 일만 골라 차례대로 간단히 쓴다","correct":true},{"t":"처음부터 끝까지 빠짐없이 자세히 쓴다","mis":"K5-2-u1-X25"},{"t":"마지막 장면만 쓴다","mis":"K5-2-u1-X29"},{"t":"줄거리는 쓰지 않는다","mis":"K5-2-u1-X28"}],"explanation":["서평의 중심은 줄거리가 아니에요.","중요한 일을 차례대로 써요.","간단한 줄거리는 들어가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L10_basic#6','kor',5,2,'u1','L10','g5_2_kor_u1_L10_basic','lesson_basic','K5-2-u1-C30',2,'blank','auto','「수요일의 텃밭」 서평은 (     ) 친구들에게 이 책을 권했어요.',ARRAY['K5-2-u1-X28']::text[],false,'{"seq":6,"concept":"K5-2-u1-C30","difficulty":2,"kind":"blank","stem":"「수요일의 텃밭」 서평은 (     ) 친구들에게 이 책을 권했어요.","options":[{"t":"친구와 다투어 마음이 무거운","correct":true},{"t":"텃밭이 없는 학교의","mis":"K5-2-u1-X28"},{"t":"상추를 싫어하는","mis":"K5-2-u1-X28"},{"t":"책을 많이 읽은","mis":"K5-2-u1-X28"}],"explanation":["추천 대상이 달라요.","글에 없는 말이에요.","누구에게 왜 추천하는지 썼어요."],"asset":{"type":"passage","lines":["〔제목〕 흙 묻은 손으로 맺은 약속","「수요일의 텃밭」은 5학년 아이들이 학교 텃밭을 가꾸며 겪는 일을 그린 동화예요.","상추가 밤사이 모두 뽑히자 아이들은 서로를 의심하다가, 다시 씨앗을 심기로 마음을 모아요.","가장 인상적인 부분은 의심받던 친구가 흙 묻은 손을 내미는 장면이에요.","오해가 풀리는 순간이 생생하기 때문이에요.","친구와 다투어 마음이 무거운 친구들에게 이 책을 권해요.","다만 뒷부분이 조금 서둘러 끝나는 점은 아쉬워요."],"title":"서평 「수요일의 텃밭」 (지어낸 책)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L10_basic#7','kor',5,2,'u1','L10','g5_2_kor_u1_L10_basic','lesson_basic','K5-2-u1-C31',2,'mc','auto','「어떤 친구가 쓴 글」이 서평이 아니라 독서 감상문에 가까운 까닭은 무엇인가요?',ARRAY['K5-2-u1-X27']::text[],false,'{"seq":7,"concept":"K5-2-u1-C31","difficulty":2,"kind":"mc","stem":"「어떤 친구가 쓴 글」이 서평이 아니라 독서 감상문에 가까운 까닭은 무엇인가요?","options":[{"t":"느낀 점만 쓰고 책에 대한 평가와 그 까닭은 쓰지 않았기 때문에","correct":true},{"t":"글이 너무 짧기 때문에","mis":"K5-2-u1-X27"},{"t":"책 제목을 썼기 때문에","mis":"K5-2-u1-X27"},{"t":"「텃밭」이라는 낱말이 나오기 때문에","mis":"K5-2-u1-X27"}],"explanation":["길이로 가르지 않아요.","제목은 둘 다 쓸 수 있어요.","평가와 까닭이 있는지 봐요."],"asset":{"type":"passage","lines":["「수요일의 텃밭」을 읽고 나도 텃밭을 가꾸고 싶어졌다.","상추가 뽑혔을 때 내가 다 속상했다.","친구가 손을 내밀 때는 눈물이 날 뻔했다.","다 읽고 나니 마음이 따뜻해졌다."],"title":"어떤 친구가 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L10_basic#8','kor',5,2,'u1','L10','g5_2_kor_u1_L10_basic','lesson_basic','K5-2-u1-C32',2,'mc','auto','서평 「수요일의 텃밭」의 제목 「흙 묻은 손으로 맺은 약속」이 좋은 까닭은 무엇인가요?',ARRAY['K5-2-u1-X29','K5-2-u1-X01']::text[],false,'{"seq":8,"concept":"K5-2-u1-C32","difficulty":2,"kind":"mc","stem":"서평 「수요일의 텃밭」의 제목 「흙 묻은 손으로 맺은 약속」이 좋은 까닭은 무엇인가요?","options":[{"t":"읽을 사람의 관심을 끌고 책의 핵심 장면을 드러내서","correct":true},{"t":"책 제목과 똑같아서","mis":"K5-2-u1-X29"},{"t":"글자 수가 가장 많아서","mis":"K5-2-u1-X01"},{"t":"어려운 낱말을 써서","mis":"K5-2-u1-X01"}],"explanation":["책 제목과 달라요.","길이는 상관없어요.","핵심을 짧게 담았어요."],"asset":{"type":"passage","lines":["〔제목〕 흙 묻은 손으로 맺은 약속","「수요일의 텃밭」은 5학년 아이들이 학교 텃밭을 가꾸며 겪는 일을 그린 동화예요.","상추가 밤사이 모두 뽑히자 아이들은 서로를 의심하다가, 다시 씨앗을 심기로 마음을 모아요.","가장 인상적인 부분은 의심받던 친구가 흙 묻은 손을 내미는 장면이에요.","오해가 풀리는 순간이 생생하기 때문이에요.","친구와 다투어 마음이 무거운 친구들에게 이 책을 권해요.","다만 뒷부분이 조금 서둘러 끝나는 점은 아쉬워요."],"title":"서평 「수요일의 텃밭」 (지어낸 책)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L10_basic#9','kor',5,2,'u1','L10','g5_2_kor_u1_L10_basic','lesson_basic','K5-2-u1-C28',2,'error','auto','서평의 평가를 쓴 문장이에요. 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u1-X28','K5-2-u1-X30','K5-2-u1-X26']::text[],false,'{"seq":9,"concept":"K5-2-u1-C28","difficulty":2,"kind":"error","stem":"서평의 평가를 쓴 문장이에요. 알맞지 않은 것은 어느 것인가요?","options":[{"t":"「이 책은 재미있다. 끝.」","correct":true,"mis_target":"K5-2-u1-X28"},{"t":"「오해가 풀리는 장면이 생생해서 친구와 다툰 사람에게 권한다.」","mis":"K5-2-u1-X30"},{"t":"「뒷부분이 서둘러 끝나 조금 아쉽다.」","mis":"K5-2-u1-X26"}],"explanation":["까닭과 추천 대상이 있어요.","아쉬운 점도 평가예요.","까닭 없이 「재미있다」만 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L10_basic#10','kor',5,2,'u1','L10','g5_2_kor_u1_L10_basic','lesson_basic','K5-2-u1-C33',3,'mc','auto','서평을 쓴 뒤 고쳐 쓰는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X30','K5-2-u1-X25']::text[],false,'{"seq":10,"concept":"K5-2-u1-C33","difficulty":3,"kind":"mc","stem":"서평을 쓴 뒤 고쳐 쓰는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"친구와 돌려 읽고 받은 의견을 살펴 빠진 내용을 보탠다","correct":true},{"t":"한 번 썼으니 고치지 않는다","mis":"K5-2-u1-X30"},{"t":"글씨만 더 예쁘게 다시 쓴다","mis":"K5-2-u1-X30"},{"t":"줄거리를 더 길게 늘린다","mis":"K5-2-u1-X25"}],"explanation":["고쳐 쓰면 더 좋아져요.","글씨보다 내용을 살펴요.","줄거리를 늘리는 게 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L10_challenge#1','kor',5,2,'u1','L10','g5_2_kor_u1_L10_challenge','lesson_challenge','K5-2-u1-C25',2,'mc','auto','서평 첫 초안 「등대 아래 도서관」의 가장 큰 문제는 무엇인가요?',ARRAY['K5-2-u1-X29','K5-2-u1-X26']::text[],false,'{"seq":1,"concept":"K5-2-u1-C25","difficulty":2,"kind":"mc","stem":"서평 첫 초안 「등대 아래 도서관」의 가장 큰 문제는 무엇인가요?","options":[{"t":"줄거리만 길게 쓰고 인상적인 부분과 평가는 거의 쓰지 않았다","correct":true},{"t":"책 제목이 들어가 있다","mis":"K5-2-u1-X29"},{"t":"줄거리를 너무 짧게 썼다","mis":"K5-2-u1-X29"},{"t":"아쉬운 점을 썼다","mis":"K5-2-u1-X26"}],"explanation":["제목이 있는 건 문제가 아니에요.","오히려 너무 길어요.","아쉬운 점은 쓰지 않았어요."],"asset":{"type":"passage","lines":["〔제목〕 등대 아래 도서관","바닷가 마을 아이 해솔이가 등대 아래 낡은 도서관을 발견한다. 다음 날 해솔이는 또 갔다.","그다음 날에는 동생을 데려갔다. 그다음 날에는 사서 할머니를 만났다.","할머니는 책을 고치는 법을 알려 주었다. 그다음 날에는 비가 왔다. 그래도 갔다.","그다음 날에는 친구들이 따라왔다. 그다음 날에는 …… (이렇게 열 줄이 더 이어진다)","이 책은 재미있다."],"title":"서평 첫 초안 「등대 아래 도서관」 (지어낸 책)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L10_challenge#2','kor',5,2,'u1','L10','g5_2_kor_u1_L10_challenge','lesson_challenge','K5-2-u1-C28',2,'mc','auto','서평 첫 초안 「등대 아래 도서관」에 빠진 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X25','K5-2-u1-X29']::text[],false,'{"seq":2,"concept":"K5-2-u1-C28","difficulty":2,"kind":"mc","stem":"서평 첫 초안 「등대 아래 도서관」에 빠진 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"인상적인 부분과 그 부분이 인상적인 까닭","correct":true},{"t":"줄거리","mis":"K5-2-u1-X25"},{"t":"책 제목","mis":"K5-2-u1-X29"},{"t":"등장인물의 이름","mis":"K5-2-u1-X25"}],"explanation":["줄거리는 넘칠 만큼 있어요.","제목은 있어요.","인물 이름은 있어요."],"asset":{"type":"passage","lines":["〔제목〕 등대 아래 도서관","바닷가 마을 아이 해솔이가 등대 아래 낡은 도서관을 발견한다. 다음 날 해솔이는 또 갔다.","그다음 날에는 동생을 데려갔다. 그다음 날에는 사서 할머니를 만났다.","할머니는 책을 고치는 법을 알려 주었다. 그다음 날에는 비가 왔다. 그래도 갔다.","그다음 날에는 친구들이 따라왔다. 그다음 날에는 …… (이렇게 열 줄이 더 이어진다)","이 책은 재미있다."],"title":"서평 첫 초안 「등대 아래 도서관」 (지어낸 책)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L10_challenge#3','kor',5,2,'u1','L10','g5_2_kor_u1_L10_challenge','lesson_challenge','K5-2-u1-C29',3,'mc','auto','초안의 「그다음 날에는 ……」을 고쳐 쓰는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X25','K5-2-u1-X28','K5-2-u1-X29']::text[],false,'{"seq":3,"concept":"K5-2-u1-C29","difficulty":3,"kind":"mc","stem":"초안의 「그다음 날에는 ……」을 고쳐 쓰는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「해솔이가 낡은 도서관을 발견하고, 할머니에게 책 고치는 법을 배워 친구들과 도서관을 다시 연다」처럼 줄인다","correct":true},{"t":"「그다음 날에는」을 열 번 더 써서 자세히 한다","mis":"K5-2-u1-X25"},{"t":"줄거리를 다 지우고 「재미있다」만 남긴다","mis":"K5-2-u1-X28"},{"t":"마지막 날 이야기 한 줄만 남긴다","mis":"K5-2-u1-X29"}],"explanation":["더 늘리면 안 돼요.","평가에도 까닭이 필요해요.","중요한 일을 차례대로 골라요."],"asset":{"type":"passage","lines":["〔제목〕 등대 아래 도서관","바닷가 마을 아이 해솔이가 등대 아래 낡은 도서관을 발견한다. 다음 날 해솔이는 또 갔다.","그다음 날에는 동생을 데려갔다. 그다음 날에는 사서 할머니를 만났다.","할머니는 책을 고치는 법을 알려 주었다. 그다음 날에는 비가 왔다. 그래도 갔다.","그다음 날에는 친구들이 따라왔다. 그다음 날에는 …… (이렇게 열 줄이 더 이어진다)","이 책은 재미있다."],"title":"서평 첫 초안 「등대 아래 도서관」 (지어낸 책)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L10_challenge#4','kor',5,2,'u1','L10','g5_2_kor_u1_L10_challenge','lesson_challenge','K5-2-u1-C32',3,'ox','auto','서평의 제목은 책 제목 「등대 아래 도서관」을 그대로 쓰는 것이 가장 좋아요.',ARRAY['K5-2-u1-X29']::text[],false,'{"seq":4,"concept":"K5-2-u1-C32","difficulty":3,"kind":"ox","stem":"서평의 제목은 책 제목 「등대 아래 도서관」을 그대로 쓰는 것이 가장 좋아요.","answer":"X","reason_options":[{"t":"서평의 제목은 읽을 사람의 관심을 끌고 책의 핵심이나 내 평가가 드러나게 붙이기 때문에","correct":true},{"t":"서평의 제목은 책 제목과 같아야 하기 때문에","mis":"K5-2-u1-X29"}],"mis":"K5-2-u1-X29","explanation":["책 제목을 옮기기만 하면 아쉬워요.","관심을 끄는 제목을 붙여요.","핵심이 드러나게 해요."],"asset":{"type":"passage","lines":["〔제목〕 등대 아래 도서관","바닷가 마을 아이 해솔이가 등대 아래 낡은 도서관을 발견한다. 다음 날 해솔이는 또 갔다.","그다음 날에는 동생을 데려갔다. 그다음 날에는 사서 할머니를 만났다.","할머니는 책을 고치는 법을 알려 주었다. 그다음 날에는 비가 왔다. 그래도 갔다.","그다음 날에는 친구들이 따라왔다. 그다음 날에는 …… (이렇게 열 줄이 더 이어진다)","이 책은 재미있다."],"title":"서평 첫 초안 「등대 아래 도서관」 (지어낸 책)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L10_challenge#5','kor',5,2,'u1','L10','g5_2_kor_u1_L10_challenge','lesson_challenge','K5-2-u1-C31',3,'mc','auto','같은 책을 읽고 쓴 두 글 가운데 서평의 특징이 드러난 문장은 어느 것인가요?',ARRAY['K5-2-u1-X27']::text[],false,'{"seq":5,"concept":"K5-2-u1-C31","difficulty":3,"kind":"mc","stem":"같은 책을 읽고 쓴 두 글 가운데 서평의 특징이 드러난 문장은 어느 것인가요?","options":[{"t":"「오해가 풀리는 장면이 생생해서, 친구와 다툰 사람에게 이 책을 권한다.」","correct":true},{"t":"「상추가 뽑혔을 때 내가 다 속상했다.」","mis":"K5-2-u1-X27"},{"t":"「다 읽고 나니 마음이 따뜻해졌다.」","mis":"K5-2-u1-X27"},{"t":"「나도 텃밭을 가꾸고 싶어졌다.」","mis":"K5-2-u1-X27"}],"explanation":["느낌을 쓴 문장이에요.","느낌을 쓴 문장이에요.","평가와 까닭, 추천이 담겼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L10_challenge#6','kor',5,2,'u1','L10','g5_2_kor_u1_L10_challenge','lesson_challenge','K5-2-u1-C30',3,'error','auto','서평에 들어갈 평가를 쓴 친구들의 말이에요. 알맞지 않은 생각은 어느 것인가요?',ARRAY['K5-2-u1-X26','K5-2-u1-X30','K5-2-u1-X28']::text[],false,'{"seq":6,"concept":"K5-2-u1-C30","difficulty":3,"kind":"error","stem":"서평에 들어갈 평가를 쓴 친구들의 말이에요. 알맞지 않은 생각은 어느 것인가요?","options":[{"t":"「아쉬운 점을 쓰면 서평이 아니게 되니까 좋은 점만 써야 해.」","correct":true,"mis_target":"K5-2-u1-X26"},{"t":"「책을 아끼는 마음을 기르고 싶은 친구에게 권한다고 쓸래.」","mis":"K5-2-u1-X30"},{"t":"「할머니가 왜 도서관을 지켰는지 안 나와서 아쉽다고 까닭을 쓸래.」","mis":"K5-2-u1-X28"}],"explanation":["누구에게 왜 권하는지 썼어요.","아쉬운 점에 까닭을 붙였어요.","아쉬운 점도 평가가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L10_challenge#7','kor',5,2,'u1','L10','g5_2_kor_u1_L10_challenge','lesson_challenge','K5-2-u1-C33',3,'mc','auto','서평을 쓸 때 스스로에게 할 물음으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X30','K5-2-u1-X25']::text[],false,'{"seq":7,"concept":"K5-2-u1-C33","difficulty":3,"kind":"mc","stem":"서평을 쓸 때 스스로에게 할 물음으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「이 책이 친구들에게 도움이 되는 까닭은 무엇일까?」","correct":true},{"t":"「이 책은 몇 쪽일까?」","mis":"K5-2-u1-X30"},{"t":"「줄거리를 하나도 빠짐없이 썼을까?」","mis":"K5-2-u1-X25"},{"t":"「책값은 얼마일까?」","mis":"K5-2-u1-X30"}],"explanation":["쪽수는 평가와 관계없어요.","빠짐없이 쓰는 게 목적이 아니에요.","평가의 까닭을 찾는 물음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L10_challenge#8','kor',5,2,'u1','L10','g5_2_kor_u1_L10_challenge','lesson_challenge','K5-2-u1-C31',4,'essay','teacher','「어떤 친구가 쓴 글」을 서평으로 고쳐 쓴다고 할 때, 더 넣어야 할 내용 두 가지를 쓰고 그 내용을 넣은 문장을 하나 만들어 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u1-C31","difficulty":4,"kind":"essay","stem":"「어떤 친구가 쓴 글」을 서평으로 고쳐 쓴다고 할 때, 더 넣어야 할 내용 두 가지를 쓰고 그 내용을 넣은 문장을 하나 만들어 쓰세요.","answer_guide":{"answer":"예: 더 넣어야 할 내용 — 책에 대한 평가와 그 까닭, 누구에게 왜 추천하는지. 문장 — 「의심하던 친구들이 다시 마음을 모으는 과정이 잘 그려져 있어서, 친구와 오해가 생겨 고민하는 친구들에게 이 책을 권하고 싶다.」","scoring_points":["더 넣을 내용 두 가지를 썼는가","평가와 까닭이 담긴 문장을 썼는가","추천 대상과 까닭을 썼는가"]},"explanation":["감상문과 서평의 차이를 떠올려요.","평가와 까닭을 넣어요.","추천을 써요."],"asset":{"type":"passage","lines":["「수요일의 텃밭」을 읽고 나도 텃밭을 가꾸고 싶어졌다.","상추가 뽑혔을 때 내가 다 속상했다.","친구가 손을 내밀 때는 눈물이 날 뻔했다.","다 읽고 나니 마음이 따뜻해졌다."],"title":"어떤 친구가 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L10_challenge#9','kor',5,2,'u1','L10','g5_2_kor_u1_L10_challenge','lesson_challenge','K5-2-u1-C28',4,'essay','teacher','최근에 읽은 책 한 권을 떠올려 서평의 다섯 칸(제목 · 책 소개 · 줄거리 · 인상적인 부분과 까닭 · 평가)을 짧게 계획해 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u1-C28","difficulty":4,"kind":"essay","stem":"최근에 읽은 책 한 권을 떠올려 서평의 다섯 칸(제목 · 책 소개 · 줄거리 · 인상적인 부분과 까닭 · 평가)을 짧게 계획해 쓰세요.","answer_guide":{"answer":"예: 제목 — 「느려도 끝까지 가는 편지」. 책 소개 — 「달팽이 우체부 느림이」는 느린 달팽이가 숲속 친구들에게 편지를 전하는 동화이다. 줄거리 — 느림이는 비바람에 늦어지지만 포기하지 않고 마지막 편지까지 전한다. 인상적인 부분과 까닭 — 마지막 편지를 받은 다람쥐가 우는 장면. 기다림이 기쁨으로 바뀌는 순간이 따뜻해서. 평가 — 끝까지 하는 마음을 배우고 싶은 친구에게 권한다. 다만 중간에 비슷한 장면이 되풀이되어 조금 지루하다.","scoring_points":["다섯 칸을 모두 계획했는가","줄거리를 간단히 썼는가","평가에 까닭을 붙였는가"]},"explanation":["책을 떠올려요.","칸마다 짧게 써요.","평가에 까닭을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L10_challenge#10','kor',5,2,'u1','L10','g5_2_kor_u1_L10_challenge','lesson_challenge','K5-2-u1-C33',4,'essay','teacher','서평 첫 초안과 고쳐 쓴 글 「낡은 책이 다시 숨 쉬는 곳」을 견주어, 고쳐 쓰면서 나아진 점 세 가지를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u1-C33","difficulty":4,"kind":"essay","stem":"서평 첫 초안과 고쳐 쓴 글 「낡은 책이 다시 숨 쉬는 곳」을 견주어, 고쳐 쓰면서 나아진 점 세 가지를 쓰세요.","answer_guide":{"answer":"예: 첫째, 제목을 책 제목 그대로 쓰지 않고 「낡은 책이 다시 숨 쉬는 곳」으로 바꾸어 관심을 끈다. 둘째, 날마다 일어난 일을 늘어놓던 줄거리를 중요한 일만 간추려 두 문장으로 줄였다. 셋째, 「재미있다」만 있던 평가에 인상적인 부분과 까닭, 추천할 사람, 아쉬운 점을 까닭과 함께 넣었다.","scoring_points":["제목이 나아진 점을 썼는가","줄거리가 나아진 점을 썼는가","평가가 나아진 점을 썼는가"]},"explanation":["두 글을 나란히 봐요.","칸마다 견줘요.","나아진 점을 정리해요."],"asset":{"type":"passage","lines":["〔제목〕 낡은 책이 다시 숨 쉬는 곳","「등대 아래 도서관」은 바닷가 마을 아이가 등대 아래 낡은 도서관을 지키는 이야기예요.","해솔이는 사서 할머니에게 찢어진 책을 고치는 법을 배우고, 친구들과 도서관을 다시 열어요.","가장 인상적인 부분은 해솔이가 젖은 책을 한 장씩 말리는 장면이에요.","작은 일을 끝까지 해내는 마음이 잘 보이기 때문이에요.","책을 아끼는 마음을 기르고 싶은 친구들에게 권해요.","다만 할머니가 왜 혼자 도서관을 지켰는지가 나오지 않아 조금 아쉬워요."],"title":"서평 고쳐 쓴 글 「등대 아래 도서관」 (지어낸 책)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L12_basic#1','kor',5,2,'u1','L12','g5_2_kor_u1_L12_basic','lesson_basic','K5-2-u1-C34',1,'mc','auto','「이달의 책」을 추천할 때 정리할 것으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X31','K5-2-u1-X34']::text[],false,'{"seq":1,"concept":"K5-2-u1-C34","difficulty":1,"kind":"mc","stem":"「이달의 책」을 추천할 때 정리할 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"추천할 책, 추천하는 까닭, 인상적인 부분","correct":true},{"t":"책의 값과 쪽수","mis":"K5-2-u1-X31"},{"t":"내가 그 책을 산 날짜","mis":"K5-2-u1-X31"},{"t":"책 표지의 색깔","mis":"K5-2-u1-X34"}],"explanation":["값은 추천 까닭이 아니에요.","산 날은 상관없어요.","표지 색만으로는 부족해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L12_basic#2','kor',5,2,'u1','L12','g5_2_kor_u1_L12_basic','lesson_basic','K5-2-u1-C35',1,'mc','auto','모둠 토의에서 친구의 추천 까닭을 들을 때 알맞은 태도는 어느 것인가요?',ARRAY['K5-2-u1-X16']::text[],false,'{"seq":2,"concept":"K5-2-u1-C35","difficulty":1,"kind":"mc","stem":"모둠 토의에서 친구의 추천 까닭을 들을 때 알맞은 태도는 어느 것인가요?","options":[{"t":"끝까지 듣고 나와 같은 점과 다른 점을 견준다","correct":true},{"t":"내 차례가 오기 전에 말을 끊는다","mis":"K5-2-u1-X16"},{"t":"나와 다르면 바로 틀렸다고 한다","mis":"K5-2-u1-X16"},{"t":"듣지 않고 내 책만 생각한다","mis":"K5-2-u1-X16"}],"explanation":["끝까지 들어요.","다른 의견도 견줘요.","들어야 견줄 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L12_basic#3','kor',5,2,'u1','L12','g5_2_kor_u1_L12_basic','lesson_basic','K5-2-u1-C37',1,'ox','auto','내가 추천한 책이 뽑히지 않으면 내 의견은 쓸모없었던 거예요.',ARRAY['K5-2-u1-X33']::text[],false,'{"seq":3,"concept":"K5-2-u1-C37","difficulty":1,"kind":"ox","stem":"내가 추천한 책이 뽑히지 않으면 내 의견은 쓸모없었던 거예요.","answer":"X","reason_options":[{"t":"뽑히지 않은 책의 추천 까닭도 친구들이 새 책을 알게 하고 다음 후보가 될 수 있기 때문에","correct":true},{"t":"토의에서는 뽑힌 의견만 의미가 있기 때문에","mis":"K5-2-u1-X33"}],"mis":"K5-2-u1-X33","explanation":["다른 의견도 쓸모가 있어요.","다음 달 후보가 돼요.","토의는 견주고 조정하는 과정이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L12_basic#4','kor',5,2,'u1','L12','g5_2_kor_u1_L12_basic','lesson_basic','K5-2-u1-C36',1,'mc','auto','나은이가 의견이 갈렸을 때 제안한 방법은 무엇인가요?',ARRAY['K5-2-u1-X32']::text[],false,'{"seq":4,"concept":"K5-2-u1-C36","difficulty":1,"kind":"mc","stem":"나은이가 의견이 갈렸을 때 제안한 방법은 무엇인가요?","options":[{"t":"반 친구들 모두에게 두루 도움이 되는지로 견주기","correct":true},{"t":"목소리가 가장 큰 친구의 책으로 정하기","mis":"K5-2-u1-X32"},{"t":"가장 먼저 말한 친구의 책으로 정하기","mis":"K5-2-u1-X32"},{"t":"제비뽑기로만 정하기","mis":"K5-2-u1-X32"}],"explanation":["목소리로 정하지 않아요.","말한 차례로 정하지 않아요.","함께 정한 기준에 대어요."],"asset":{"type":"speech","turns":[{"who":"시우","text":"나는 「달팽이 우체부 느림이」를 추천해. 느려도 끝까지 편지를 전하는 모습이 인상적이었어."},{"who":"다인","text":"나는 「밤하늘 별자리 백과」! 별자리 이름이 엄청 많이 나와서 좋아."},{"who":"로운","text":"「등대 아래 도서관」은 어때? 책을 고치는 장면이 따뜻하고 누구나 읽기 쉬워."},{"who":"나은","text":"의견이 셋으로 갈렸네. 우리 반 친구들 모두에게 두루 도움이 되는지로 견주어 보자."},{"who":"다인","text":"내 책은 별을 좋아하는 친구만 좋아할 수도 있겠다. 다음 달 후보로 남겨 둘래."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L12_basic#5','kor',5,2,'u1','L12','g5_2_kor_u1_L12_basic','lesson_basic','K5-2-u1-C34',2,'mc','auto','다인이가 추천한 책이 「이달의 책」으로 아쉬운 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X34','K5-2-u1-X32','K5-2-u1-X31']::text[],false,'{"seq":5,"concept":"K5-2-u1-C34","difficulty":2,"kind":"mc","stem":"다인이가 추천한 책이 「이달의 책」으로 아쉬운 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"한 분야에 치우쳐 별을 좋아하는 친구만 좋아할 수 있어서","correct":true},{"t":"제목이 너무 짧아서","mis":"K5-2-u1-X34"},{"t":"다인이가 먼저 말하지 않아서","mis":"K5-2-u1-X32"},{"t":"별 이야기는 책이 될 수 없어서","mis":"K5-2-u1-X31"}],"explanation":["제목 길이는 상관없어요.","말한 차례와는 관계없어요.","별 책도 좋은 책이에요."],"asset":{"type":"speech","turns":[{"who":"시우","text":"나는 「달팽이 우체부 느림이」를 추천해. 느려도 끝까지 편지를 전하는 모습이 인상적이었어."},{"who":"다인","text":"나는 「밤하늘 별자리 백과」! 별자리 이름이 엄청 많이 나와서 좋아."},{"who":"로운","text":"「등대 아래 도서관」은 어때? 책을 고치는 장면이 따뜻하고 누구나 읽기 쉬워."},{"who":"나은","text":"의견이 셋으로 갈렸네. 우리 반 친구들 모두에게 두루 도움이 되는지로 견주어 보자."},{"who":"다인","text":"내 책은 별을 좋아하는 친구만 좋아할 수도 있겠다. 다음 달 후보로 남겨 둘래."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L12_basic#6','kor',5,2,'u1','L12','g5_2_kor_u1_L12_basic','lesson_basic','K5-2-u1-C35',2,'match','auto','친구와 그 친구가 든 추천 까닭을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K5-2-u1-C35","difficulty":2,"kind":"match","stem":"친구와 그 친구가 든 추천 까닭을 알맞게 이으세요.","pairs":[{"l":"시우","r":"느려도 끝까지 편지를 전하는 모습이 인상적이다"},{"l":"다인","r":"별자리 이름이 많이 나온다"},{"l":"로운","r":"책을 고치는 장면이 따뜻하고 누구나 읽기 쉽다"}],"mis":"K5-2-u1-X16","explanation":["시우는 인물의 모습을 들었어요.","다인이는 담긴 지식을 들었어요.","로운이는 장면과 읽기 쉬움을 들었어요."],"asset":{"type":"speech","turns":[{"who":"시우","text":"나는 「달팽이 우체부 느림이」를 추천해. 느려도 끝까지 편지를 전하는 모습이 인상적이었어."},{"who":"다인","text":"나는 「밤하늘 별자리 백과」! 별자리 이름이 엄청 많이 나와서 좋아."},{"who":"로운","text":"「등대 아래 도서관」은 어때? 책을 고치는 장면이 따뜻하고 누구나 읽기 쉬워."},{"who":"나은","text":"의견이 셋으로 갈렸네. 우리 반 친구들 모두에게 두루 도움이 되는지로 견주어 보자."},{"who":"다인","text":"내 책은 별을 좋아하는 친구만 좋아할 수도 있겠다. 다음 달 후보로 남겨 둘래."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L12_basic#7','kor',5,2,'u1','L12','g5_2_kor_u1_L12_basic','lesson_basic','K5-2-u1-C37',2,'mc','auto','다인이가 「다음 달 후보로 남겨 둘래」라고 한 말에서 알 수 있는 태도는 어느 것인가요?',ARRAY['K5-2-u1-X33','K5-2-u1-X16','K5-2-u1-X32']::text[],false,'{"seq":7,"concept":"K5-2-u1-C37","difficulty":2,"kind":"mc","stem":"다인이가 「다음 달 후보로 남겨 둘래」라고 한 말에서 알 수 있는 태도는 어느 것인가요?","options":[{"t":"조정된 의견을 받아들이면서 내 의견도 소중히 여기는 태도","correct":true},{"t":"내 책이 안 되면 토의를 그만두는 태도","mis":"K5-2-u1-X33"},{"t":"다른 친구 책을 깎아내리는 태도","mis":"K5-2-u1-X16"},{"t":"기준 없이 아무 책이나 고르는 태도","mis":"K5-2-u1-X32"}],"explanation":["토의를 이어 가요.","깎아내리지 않았어요.","기준에 대어 스스로 견줬어요."],"asset":{"type":"speech","turns":[{"who":"시우","text":"나는 「달팽이 우체부 느림이」를 추천해. 느려도 끝까지 편지를 전하는 모습이 인상적이었어."},{"who":"다인","text":"나는 「밤하늘 별자리 백과」! 별자리 이름이 엄청 많이 나와서 좋아."},{"who":"로운","text":"「등대 아래 도서관」은 어때? 책을 고치는 장면이 따뜻하고 누구나 읽기 쉬워."},{"who":"나은","text":"의견이 셋으로 갈렸네. 우리 반 친구들 모두에게 두루 도움이 되는지로 견주어 보자."},{"who":"다인","text":"내 책은 별을 좋아하는 친구만 좋아할 수도 있겠다. 다음 달 후보로 남겨 둘래."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L12_basic#8','kor',5,2,'u1','L12','g5_2_kor_u1_L12_basic','lesson_basic','K5-2-u1-C38',2,'blank','auto','고른 「이달의 책」을 알리는 소개 자료에는 간단한 책 소개, 추천 까닭, (     )을/를 담아요.',ARRAY['K5-2-u1-X34']::text[],false,'{"seq":8,"concept":"K5-2-u1-C38","difficulty":2,"kind":"blank","stem":"고른 「이달의 책」을 알리는 소개 자료에는 간단한 책 소개, 추천 까닭, (     )을/를 담아요.","options":[{"t":"인상적인 문장","correct":true},{"t":"책값","mis":"K5-2-u1-X34"},{"t":"지은이의 주소","mis":"K5-2-u1-X34"},{"t":"다 읽는 데 걸린 날짜","mis":"K5-2-u1-X34"}],"explanation":["값은 알릴 거리가 아니에요.","주소는 필요 없어요.","마음에 남은 문장을 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L12_basic#9','kor',5,2,'u1','L12','g5_2_kor_u1_L12_basic','lesson_basic','K5-2-u1-C36',2,'mc','auto','모둠에서 「이달의 책」 고르는 기준으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X31','K5-2-u1-X32']::text[],false,'{"seq":9,"concept":"K5-2-u1-C36","difficulty":2,"kind":"mc","stem":"모둠에서 「이달의 책」 고르는 기준으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"반 친구들이 두루 흥미롭게 읽을 수 있는가","correct":true},{"t":"가장 두꺼운 책인가","mis":"K5-2-u1-X31"},{"t":"추천한 친구가 반장인가","mis":"K5-2-u1-X32"},{"t":"가장 비싼 책인가","mis":"K5-2-u1-X31"}],"explanation":["두께가 기준은 아니에요.","누가 추천했는지가 기준은 아니에요.","반 친구 모두를 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L12_basic#10','kor',5,2,'u1','L12','g5_2_kor_u1_L12_basic','lesson_basic','K5-2-u1-C38',3,'mc','auto','「이달의 책」 소개 자료로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X34','K5-2-u1-X25','K5-2-u1-X28']::text[],false,'{"seq":10,"concept":"K5-2-u1-C38","difficulty":3,"kind":"mc","stem":"「이달의 책」 소개 자료로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"책 소개 한 줄, 추천 까닭, 인상적인 문장을 함께 담은 광고지","correct":true},{"t":"책 제목만 크게 쓴 종이","mis":"K5-2-u1-X34"},{"t":"줄거리를 처음부터 끝까지 옮긴 종이","mis":"K5-2-u1-X25"},{"t":"「무조건 읽어!」만 쓴 종이","mis":"K5-2-u1-X28"}],"explanation":["제목만으로는 왜 읽을지 몰라요.","줄거리를 다 옮기지 않아요.","까닭 없는 말은 설득이 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L12_challenge#1','kor',5,2,'u1','L12','g5_2_kor_u1_L12_challenge','lesson_challenge','K5-2-u1-C34',2,'mc','auto','「이달의 책」에 어울리는 조건으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u1-X31']::text[],false,'{"seq":1,"concept":"K5-2-u1-C34","difficulty":2,"kind":"mc","stem":"「이달의 책」에 어울리는 조건으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"반에서 한두 명만 읽을 수 있을 만큼 어려운 이야기","correct":true},{"t":"흥미로운 이야기","mis":"K5-2-u1-X31"},{"t":"교훈을 주는 이야기","mis":"K5-2-u1-X31"},{"t":"여러 친구가 함께 이야기 나눌 거리가 있는 책","mis":"K5-2-u1-X31"}],"explanation":["흥미는 좋은 조건이에요.","교훈도 좋은 조건이에요.","너무 어려운 책은 피해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L12_challenge#2','kor',5,2,'u1','L12','g5_2_kor_u1_L12_challenge','lesson_challenge','K5-2-u1-C36',2,'error','auto','모둠 토의에서 의견이 갈렸을 때 한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u1-X32','K5-2-u1-X36','K5-2-u1-X35']::text[],false,'{"seq":2,"concept":"K5-2-u1-C36","difficulty":2,"kind":"error","stem":"모둠 토의에서 의견이 갈렸을 때 한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「내가 제일 먼저 말했으니까 내 책으로 하자.」","correct":true,"mis_target":"K5-2-u1-X32"},{"t":"「반 친구들에게 두루 도움이 되는지로 견주어 보자.」","mis":"K5-2-u1-X36"},{"t":"「두 책의 추천 까닭에서 같은 점부터 찾아보자.」","mis":"K5-2-u1-X35"}],"explanation":["기준을 세웠어요.","견주기부터 했어요.","말한 차례로 정하지 않아요."],"asset":{"type":"speech","turns":[{"who":"시우","text":"나는 「달팽이 우체부 느림이」를 추천해. 느려도 끝까지 편지를 전하는 모습이 인상적이었어."},{"who":"다인","text":"나는 「밤하늘 별자리 백과」! 별자리 이름이 엄청 많이 나와서 좋아."},{"who":"로운","text":"「등대 아래 도서관」은 어때? 책을 고치는 장면이 따뜻하고 누구나 읽기 쉬워."},{"who":"나은","text":"의견이 셋으로 갈렸네. 우리 반 친구들 모두에게 두루 도움이 되는지로 견주어 보자."},{"who":"다인","text":"내 책은 별을 좋아하는 친구만 좋아할 수도 있겠다. 다음 달 후보로 남겨 둘래."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L12_challenge#3','kor',5,2,'u1','L12','g5_2_kor_u1_L12_challenge','lesson_challenge','K5-2-u1-C35',3,'mc','auto','시우와 로운이의 추천 까닭에서 같은 점은 무엇인가요?',ARRAY['K5-2-u1-X16','K5-2-u1-X31','K5-2-u1-X03']::text[],false,'{"seq":3,"concept":"K5-2-u1-C35","difficulty":3,"kind":"mc","stem":"시우와 로운이의 추천 까닭에서 같은 점은 무엇인가요?","options":[{"t":"둘 다 책 속 장면이나 인물의 모습을 까닭으로 들었다","correct":true},{"t":"둘 다 지식이 많이 나온다는 것을 들었다","mis":"K5-2-u1-X16"},{"t":"둘 다 책값이 싸다는 것을 들었다","mis":"K5-2-u1-X31"},{"t":"둘 다 까닭을 말하지 않았다","mis":"K5-2-u1-X03"}],"explanation":["지식은 다인이가 든 까닭이에요.","값 이야기는 없어요.","같은 점을 찾으면 조정이 쉬워요."],"asset":{"type":"speech","turns":[{"who":"시우","text":"나는 「달팽이 우체부 느림이」를 추천해. 느려도 끝까지 편지를 전하는 모습이 인상적이었어."},{"who":"다인","text":"나는 「밤하늘 별자리 백과」! 별자리 이름이 엄청 많이 나와서 좋아."},{"who":"로운","text":"「등대 아래 도서관」은 어때? 책을 고치는 장면이 따뜻하고 누구나 읽기 쉬워."},{"who":"나은","text":"의견이 셋으로 갈렸네. 우리 반 친구들 모두에게 두루 도움이 되는지로 견주어 보자."},{"who":"다인","text":"내 책은 별을 좋아하는 친구만 좋아할 수도 있겠다. 다음 달 후보로 남겨 둘래."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L12_challenge#4','kor',5,2,'u1','L12','g5_2_kor_u1_L12_challenge','lesson_challenge','K5-2-u1-C36',3,'mc','auto','나은이가 제안한 기준에 대면 가장 알맞게 고른 책은 어느 것이고, 왜 그런가요?',ARRAY['K5-2-u1-X31','K5-2-u1-X32','K5-2-u1-X04']::text[],false,'{"seq":4,"concept":"K5-2-u1-C36","difficulty":3,"kind":"mc","stem":"나은이가 제안한 기준에 대면 가장 알맞게 고른 책은 어느 것이고, 왜 그런가요?","options":[{"t":"「등대 아래 도서관」 — 누구나 읽기 쉽고 따뜻한 장면이 있어 반 친구들에게 두루 맞아서","correct":true},{"t":"「밤하늘 별자리 백과」 — 이름이 가장 많이 나와서","mis":"K5-2-u1-X31"},{"t":"「달팽이 우체부 느림이」 — 시우가 먼저 말해서","mis":"K5-2-u1-X32"},{"t":"아무 책이나 — 어차피 정답이 없어서","mis":"K5-2-u1-X04"}],"explanation":["한 분야에 치우칠 수 있어요.","말한 차례는 기준이 아니에요.","기준에 대어 까닭을 들었어요."],"asset":{"type":"speech","turns":[{"who":"시우","text":"나는 「달팽이 우체부 느림이」를 추천해. 느려도 끝까지 편지를 전하는 모습이 인상적이었어."},{"who":"다인","text":"나는 「밤하늘 별자리 백과」! 별자리 이름이 엄청 많이 나와서 좋아."},{"who":"로운","text":"「등대 아래 도서관」은 어때? 책을 고치는 장면이 따뜻하고 누구나 읽기 쉬워."},{"who":"나은","text":"의견이 셋으로 갈렸네. 우리 반 친구들 모두에게 두루 도움이 되는지로 견주어 보자."},{"who":"다인","text":"내 책은 별을 좋아하는 친구만 좋아할 수도 있겠다. 다음 달 후보로 남겨 둘래."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L12_challenge#5','kor',5,2,'u1','L12','g5_2_kor_u1_L12_challenge','lesson_challenge','K5-2-u1-C37',3,'ox','auto','「이달의 책」을 알릴 때 아깝게 뽑히지 않은 책 목록도 함께 나누면 좋아요.',ARRAY['K5-2-u1-X33']::text[],false,'{"seq":5,"concept":"K5-2-u1-C37","difficulty":3,"kind":"ox","stem":"「이달의 책」을 알릴 때 아깝게 뽑히지 않은 책 목록도 함께 나누면 좋아요.","answer":"O","reason_options":[{"t":"다른 의견도 인정하고 친구들이 더 많은 책을 알게 되기 때문에","correct":true},{"t":"뽑히지 않은 책은 나쁜 책이라고 알려 주어야 하기 때문에","mis":"K5-2-u1-X33"}],"mis":"K5-2-u1-X33","explanation":["뽑히지 않았다고 나쁜 책이 아니에요.","다음 후보가 될 수 있어요.","다양한 의견을 인정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L12_challenge#6','kor',5,2,'u1','L12','g5_2_kor_u1_L12_challenge','lesson_challenge','K5-2-u1-C38',3,'mc','auto','「이달의 책」 광고지의 문구로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X34','K5-2-u1-X28']::text[],false,'{"seq":6,"concept":"K5-2-u1-C38","difficulty":3,"kind":"mc","stem":"「이달의 책」 광고지의 문구로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「젖은 책을 한 장씩 말리는 아이 — 작은 일을 끝까지 해내는 마음을 만나 보세요.」","correct":true},{"t":"「이달의 책! 꼭 읽어!」","mis":"K5-2-u1-X34"},{"t":"「이 책은 이백 쪽입니다.」","mis":"K5-2-u1-X34"},{"t":"「안 읽으면 후회함!」","mis":"K5-2-u1-X28"}],"explanation":["까닭이 빠졌어요.","쪽수는 끌림이 없어요.","인상적인 장면과 까닭을 담았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L12_challenge#7','kor',5,2,'u1','L12','g5_2_kor_u1_L12_challenge','lesson_challenge','K5-2-u1-C18',3,'mc','auto','모둠 토의를 마친 뒤 되돌아보기로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X33','K5-2-u1-X32','K5-2-u1-X16']::text[],false,'{"seq":7,"concept":"K5-2-u1-C18","difficulty":3,"kind":"mc","stem":"모둠 토의를 마친 뒤 되돌아보기로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「친구의 추천 까닭을 듣고 내가 몰랐던 책의 좋은 점을 알게 되었다.」","correct":true},{"t":"「내 책이 안 뽑혀서 아무것도 얻지 못했다.」","mis":"K5-2-u1-X33"},{"t":"「목소리가 큰 친구가 이겨서 다행이다.」","mis":"K5-2-u1-X32"},{"t":"「다른 친구 말은 듣지 않아도 됐다.」","mis":"K5-2-u1-X16"}],"explanation":["얻은 것이 있어요.","목소리로 정하지 않아요.","들었기에 배운 게 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L12_challenge#8','kor',5,2,'u1','L12','g5_2_kor_u1_L12_challenge','lesson_challenge','K5-2-u1-C34',4,'essay','teacher','내가 「이달의 책」으로 추천할 책을 하나 정해, 추천하는 까닭과 인상적인 부분을 함께 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u1-C34","difficulty":4,"kind":"essay","stem":"내가 「이달의 책」으로 추천할 책을 하나 정해, 추천하는 까닭과 인상적인 부분을 함께 쓰세요.","answer_guide":{"answer":"예: 「달팽이 우체부 느림이」를 추천한다. 느린 달팽이가 비바람 속에서도 포기하지 않고 마지막 편지까지 전하는 이야기여서, 무엇이든 빨리 하려다 쉽게 그만두는 우리에게 끝까지 하는 마음을 알려 준다. 인상적인 부분은 편지를 받은 다람쥐가 기쁨에 우는 장면이다. 기다림이 기쁨으로 바뀌는 순간이 따뜻하게 느껴졌기 때문이다.","scoring_points":["추천할 책을 정했는가","반 친구들을 생각한 추천 까닭을 썼는가","인상적인 부분과 까닭을 썼는가"]},"explanation":["책을 정해요.","반 친구들에게 맞는 까닭을 써요.","인상적인 부분을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L12_challenge#9','kor',5,2,'u1','L12','g5_2_kor_u1_L12_challenge','lesson_challenge','K5-2-u1-C36',4,'essay','teacher','모둠의 의견이 둘로 갈렸을 때 의견을 조정하는 방법을 차례대로 쓰고, 그렇게 하면 좋은 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u1-C36","difficulty":4,"kind":"essay","stem":"모둠의 의견이 둘로 갈렸을 때 의견을 조정하는 방법을 차례대로 쓰고, 그렇게 하면 좋은 까닭을 쓰세요.","answer_guide":{"answer":"예: 먼저 서로의 추천 까닭을 끝까지 듣는다. 다음으로 두 의견의 같은 점과 다른 점을 견준다. 그리고 「반 친구들에게 두루 도움이 되는가」처럼 함께 기준을 정해 대어 본다. 마지막으로 기준에 더 맞는 책을 고르고, 뽑히지 않은 책은 다음 달 후보로 남긴다. 이렇게 하면 목소리 크기나 차례가 아니라 까닭에 따라 정하게 되어 모두가 받아들이기 쉽다.","scoring_points":["듣기 · 견주기 · 기준 세우기를 차례대로 썼는가","뽑히지 않은 의견을 존중하는 내용이 있는가","좋은 까닭을 썼는가"]},"explanation":["듣기부터 시작해요.","기준에 대어요.","모두가 받아들이기 쉬운 까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L12_challenge#10','kor',5,2,'u1','L12','g5_2_kor_u1_L12_challenge','lesson_challenge','K5-2-u1-C38',4,'essay','teacher','고른 「이달의 책」을 반 친구들에게 알리는 광고지에 넣을 내용 세 가지를 쓰고, 그 가운데 하나를 실제 문구로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u1-C38","difficulty":4,"kind":"essay","stem":"고른 「이달의 책」을 반 친구들에게 알리는 광고지에 넣을 내용 세 가지를 쓰고, 그 가운데 하나를 실제 문구로 쓰세요.","answer_guide":{"answer":"예: 넣을 내용 — 책을 간단히 소개하는 한 줄, 추천하는 까닭, 책 속 인상적인 문장. 실제 문구 — 「〈조금씩이라도 매일 가면 끝내 닿아.〉 느린 달팽이가 알려 주는 끝까지 하는 힘, 이번 달 우리 반이 함께 읽어요!」","scoring_points":["넣을 내용 세 가지를 썼는가","실제 문구를 썼는가","문구가 친구들의 관심을 끌 수 있는가"]},"explanation":["소개 · 까닭 · 문장을 떠올려요.","하나를 골라 써요.","관심을 끌게 다듬어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#1','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C39',1,'mc','auto','인상적인 문장에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['K5-2-u1-X35','K5-2-u1-X02']::text[],false,'{"seq":1,"concept":"K5-2-u1-C39","difficulty":1,"kind":"mc","stem":"인상적인 문장에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"짧고 쉬운 문장도 마음이 움직였다면 인상적인 문장이 된다","correct":true},{"t":"어려운 낱말이 많을수록 인상적인 문장이다","mis":"K5-2-u1-X35"},{"t":"가장 긴 문장이 인상적인 문장이다","mis":"K5-2-u1-X35"},{"t":"책의 첫 문장만 인상적인 문장이다","mis":"K5-2-u1-X02"}],"explanation":["어려움은 기준이 아니에요.","길이는 기준이 아니에요.","마음이 움직였는지가 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#2','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C2',1,'ox','auto','「운동장 그림자」를 읽고 하람이와 도윤이가 고른 연이 다르니 한 사람은 틀렸어요.',ARRAY['K5-2-u1-X15']::text[],false,'{"seq":2,"concept":"K5-2-u1-C2","difficulty":1,"kind":"ox","stem":"「운동장 그림자」를 읽고 하람이와 도윤이가 고른 연이 다르니 한 사람은 틀렸어요.","answer":"X","reason_options":[{"t":"같은 시를 읽어도 사람마다 인상적인 부분이 다를 수 있기 때문에","correct":true},{"t":"한 시에서 인상적인 연은 하나로 정해져 있기 때문에","mis":"K5-2-u1-X15"}],"mis":"K5-2-u1-X15","explanation":["다르게 고를 수 있어요.","둘 다 까닭이 있어요.","틀린 사람은 없어요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"나는 셋째 연이 인상적이야. 그림자가 먼저 집으로 달려간다니 재미있어."},{"who":"도윤","text":"나는 마지막 연! 혼자 있을 때도 그림자가 친구 같았던 적이 있거든."},{"who":"하람","text":"뭐야, 그건 시랑 상관없는 네 이야기잖아."},{"who":"도윤","text":"내 경험이 떠올라서 고른 거야. 그것도 까닭이 되지 않을까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#3','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C40',1,'mc','auto','「책을 주제별로 (     )」에 들어갈 낱말로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X36']::text[],false,'{"seq":3,"concept":"K5-2-u1-C40","difficulty":1,"kind":"mc","stem":"「책을 주제별로 (     )」에 들어갈 낱말로 알맞은 것은 어느 것인가요?","options":[{"t":"분류하다","correct":true},{"t":"분배하다","mis":"K5-2-u1-X36"},{"t":"분석하다","mis":"K5-2-u1-X36"},{"t":"분실하다","mis":"K5-2-u1-X36"}],"explanation":["몫을 나누어 주는 게 아니에요.","자세히 살피는 게 아니에요.","기준에 따라 종류별로 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#4','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C40',1,'mc','auto','「축구 감독이 선수들의 움직임을 (     )」에 들어갈 낱말은 어느 것인가요?',ARRAY['K5-2-u1-X36']::text[],false,'{"seq":4,"concept":"K5-2-u1-C40","difficulty":1,"kind":"mc","stem":"「축구 감독이 선수들의 움직임을 (     )」에 들어갈 낱말은 어느 것인가요?","options":[{"t":"분석하다","correct":true},{"t":"분류하다","mis":"K5-2-u1-X36"},{"t":"분배하다","mis":"K5-2-u1-X36"},{"t":"분리하다","mis":"K5-2-u1-X36"}],"explanation":["종류별로 나누는 게 아니에요.","몫을 나누는 게 아니에요.","움직임을 자세히 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#5','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C20',1,'mc','auto','「세종 대왕」 같은 글을 무엇이라고 하나요?',ARRAY['K5-2-u1-X27','K5-2-u1-X18']::text[],false,'{"seq":5,"concept":"K5-2-u1-C20","difficulty":1,"kind":"mc","stem":"「세종 대왕」 같은 글을 무엇이라고 하나요?","options":[{"t":"전기문","correct":true},{"t":"서평","mis":"K5-2-u1-X27"},{"t":"동시","mis":"K5-2-u1-X18"},{"t":"일기","mis":"K5-2-u1-X18"}],"explanation":["책을 평가한 글이 아니에요.","시가 아니에요.","실제 인물의 삶을 쓴 글이에요."],"asset":{"type":"passage","lines":["세종 대왕은 조선의 넷째 임금이에요.","그 무렵 백성들은 어려운 한자를 몰라 하고 싶은 말을 글로 남기지 못했어요.","세종 대왕은 학자들과 함께 오랫동안 연구하여 우리글 훈민정음을 만들었어요.","어떤 책에서는 세종 대왕이 밤늦도록 촛불 아래에서 글자를 다듬으며","「백성이 쉽게 익혀 날마다 편히 쓰면 좋겠구나」라고 혼잣말을 했다고 그려요."],"title":"짧은 전기문 「세종 대왕」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#6','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C31',1,'mc','auto','독서 감상문과 서평의 차이로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X25','K5-2-u1-X27']::text[],false,'{"seq":6,"concept":"K5-2-u1-C31","difficulty":1,"kind":"mc","stem":"독서 감상문과 서평의 차이로 알맞은 것은 어느 것인가요?","options":[{"t":"서평은 책을 평가하고 그 까닭을 밝힌다","correct":true},{"t":"서평은 줄거리만 쓴다","mis":"K5-2-u1-X25"},{"t":"독서 감상문은 책의 아쉬운 점을 꼭 쓴다","mis":"K5-2-u1-X27"},{"t":"둘은 같은 글이다","mis":"K5-2-u1-X27"}],"explanation":["줄거리만 쓰는 글이 아니에요.","아쉬운 점은 서평의 평가예요.","둘은 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#7','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C6',1,'mc','auto','「종이비행기」에서 말하는 이가 괜찮다고 한 것은 무엇인가요?',ARRAY['K5-2-u1-X06']::text[],false,'{"seq":7,"concept":"K5-2-u1-C6","difficulty":1,"kind":"mc","stem":"「종이비행기」에서 말하는 이가 괜찮다고 한 것은 무엇인가요?","options":[{"t":"접는 선이 삐뚤어진 것","correct":true},{"t":"비행기를 잃어버린 것","mis":"K5-2-u1-X06"},{"t":"비행기를 접지 않은 것","mis":"K5-2-u1-X06"},{"t":"비행기가 찢어진 것","mis":"K5-2-u1-X06"}],"explanation":["잃어버린 이야기는 없어요.","접은 것을 칭찬해요.","첫째 줄에 나와요."],"asset":{"type":"passage","lines":["접는 선이 삐뚤어도 괜찮아","처음 접은 한 줄만 기억하면","너의 비행기는 날 수 있어","멀리 가도 좋고 / 빙글 돌아와도 좋아","네가 접었다는 게 중요해"],"title":"시 「종이비행기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#8','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C18',1,'mc','auto','친구와 작품에 대한 의견을 나눌 때 알맞은 태도는 어느 것인가요?',ARRAY['K5-2-u1-X16']::text[],false,'{"seq":8,"concept":"K5-2-u1-C18","difficulty":1,"kind":"mc","stem":"친구와 작품에 대한 의견을 나눌 때 알맞은 태도는 어느 것인가요?","options":[{"t":"친구의 의견을 끝까지 듣고 존중한다","correct":true},{"t":"나와 다르면 말을 끊는다","mis":"K5-2-u1-X16"},{"t":"내 의견만 여러 번 말한다","mis":"K5-2-u1-X16"},{"t":"친구 의견은 듣지 않는다","mis":"K5-2-u1-X16"}],"explanation":["끝까지 들어요.","번갈아 나눠요.","들어야 생각이 넓어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#9','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C3',2,'mc','auto','하람이의 말 「셋째 연이 인상적이야. 그림자가 먼저 집으로 달려간다니 재미있어」에서 까닭에 해당하는 것은 어느 것인가요?',ARRAY['K5-2-u1-X03','K5-2-u1-X04']::text[],false,'{"seq":9,"concept":"K5-2-u1-C3","difficulty":2,"kind":"mc","stem":"하람이의 말 「셋째 연이 인상적이야. 그림자가 먼저 집으로 달려간다니 재미있어」에서 까닭에 해당하는 것은 어느 것인가요?","options":[{"t":"그림자가 먼저 집으로 달려간다는 표현이 재미있다","correct":true},{"t":"셋째 연을 골랐다","mis":"K5-2-u1-X03"},{"t":"하람이가 그림자를 좋아한다","mis":"K5-2-u1-X04"},{"t":"저녁에 운동장에 갔다","mis":"K5-2-u1-X04"}],"explanation":["그건 고른 부분이에요.","글에 없는 말이에요.","표현이 주는 느낌이 까닭이에요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"나는 셋째 연이 인상적이야. 그림자가 먼저 집으로 달려간다니 재미있어."},{"who":"도윤","text":"나는 마지막 연! 혼자 있을 때도 그림자가 친구 같았던 적이 있거든."},{"who":"하람","text":"뭐야, 그건 시랑 상관없는 네 이야기잖아."},{"who":"도윤","text":"내 경험이 떠올라서 고른 거야. 그것도 까닭이 되지 않을까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#10','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C8',2,'mc','auto','하람이가 도윤이에게 한 말 「그건 시랑 상관없는 네 이야기잖아」에 대한 판단으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X08','K5-2-u1-X02','K5-2-u1-X03']::text[],false,'{"seq":10,"concept":"K5-2-u1-C8","difficulty":2,"kind":"mc","stem":"하람이가 도윤이에게 한 말 「그건 시랑 상관없는 네 이야기잖아」에 대한 판단으로 알맞은 것은 어느 것인가요?","options":[{"t":"도윤이가 떠올린 경험은 시의 마지막 연과 이어지므로 까닭이 될 수 있다","correct":true},{"t":"하람이 말이 맞다. 경험은 까닭이 될 수 없다","mis":"K5-2-u1-X08"},{"t":"둘 다 틀렸다. 인상적인 부분은 셋째 연뿐이다","mis":"K5-2-u1-X02"},{"t":"도윤이는 까닭을 말하지 않았다","mis":"K5-2-u1-X03"}],"explanation":["경험도 까닭이 돼요.","정해진 연이 없어요.","도윤이는 까닭을 말했어요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"나는 셋째 연이 인상적이야. 그림자가 먼저 집으로 달려간다니 재미있어."},{"who":"도윤","text":"나는 마지막 연! 혼자 있을 때도 그림자가 친구 같았던 적이 있거든."},{"who":"하람","text":"뭐야, 그건 시랑 상관없는 네 이야기잖아."},{"who":"도윤","text":"내 경험이 떠올라서 고른 거야. 그것도 까닭이 되지 않을까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#11','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C11',2,'mc','auto','「그림자가 발밑에 쪼그려 앉고」를 바르게 이해한 것은 어느 것인가요?',ARRAY['K5-2-u1-X09','K5-2-u1-X06']::text[],false,'{"seq":11,"concept":"K5-2-u1-C11","difficulty":2,"kind":"mc","stem":"「그림자가 발밑에 쪼그려 앉고」를 바르게 이해한 것은 어느 것인가요?","options":[{"t":"해가 높이 뜬 점심에 그림자가 아주 짧아진 모습을 사람처럼 나타냈다","correct":true},{"t":"그림자가 정말 다리를 굽혀 앉았다","mis":"K5-2-u1-X09"},{"t":"그림자가 다쳐서 주저앉았다","mis":"K5-2-u1-X09"},{"t":"점심에는 그림자가 사라진다","mis":"K5-2-u1-X06"}],"explanation":["글자 그대로가 아니에요.","다친 게 아니에요.","짧아진 모습을 빗댔어요."],"asset":{"type":"passage","lines":["아침 운동장에선 / 내 그림자가 나보다 길다","점심 운동장에선 / 그림자가 발밑에 쪼그려 앉고","저녁 운동장에선 / 그림자가 먼저 집으로 달려간다","나는 하루 종일 / 나를 따라다니는 친구가 있다"],"title":"시 「운동장 그림자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#12','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C21',2,'mc','auto','「세종 대왕」에서 작가가 다시 꾸며 표현한 부분으로 볼 수 있는 것은 어느 것인가요?',ARRAY['K5-2-u1-X19']::text[],false,'{"seq":12,"concept":"K5-2-u1-C21","difficulty":2,"kind":"mc","stem":"「세종 대왕」에서 작가가 다시 꾸며 표현한 부분으로 볼 수 있는 것은 어느 것인가요?","options":[{"t":"촛불 아래에서 「백성이 쉽게 익혀 날마다 편히 쓰면 좋겠구나」라고 혼잣말을 했다는 장면","correct":true},{"t":"조선의 넷째 임금이었다는 것","mis":"K5-2-u1-X19"},{"t":"학자들과 함께 훈민정음을 만들었다는 것","mis":"K5-2-u1-X19"},{"t":"백성들이 한자를 어려워했다는 것","mis":"K5-2-u1-X19"}],"explanation":["확인되는 사실이에요.","확인되는 사실이에요.","「어떤 책에서는 …… 그려요」라고 밝혔어요."],"asset":{"type":"passage","lines":["세종 대왕은 조선의 넷째 임금이에요.","그 무렵 백성들은 어려운 한자를 몰라 하고 싶은 말을 글로 남기지 못했어요.","세종 대왕은 학자들과 함께 오랫동안 연구하여 우리글 훈민정음을 만들었어요.","어떤 책에서는 세종 대왕이 밤늦도록 촛불 아래에서 글자를 다듬으며","「백성이 쉽게 익혀 날마다 편히 쓰면 좋겠구나」라고 혼잣말을 했다고 그려요."],"title":"짧은 전기문 「세종 대왕」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#13','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C23',2,'mc','auto','세종 대왕이 훈민정음을 만든 까닭을 그 무렵 상황과 이어 말한 것은 어느 것인가요?',ARRAY['K5-2-u1-X21']::text[],false,'{"seq":13,"concept":"K5-2-u1-C23","difficulty":2,"kind":"mc","stem":"세종 대왕이 훈민정음을 만든 까닭을 그 무렵 상황과 이어 말한 것은 어느 것인가요?","options":[{"t":"백성들이 한자를 몰라 하고 싶은 말을 글로 남기지 못했기 때문이다","correct":true},{"t":"임금이 글자 놀이를 좋아했기 때문이다","mis":"K5-2-u1-X21"},{"t":"다른 나라에 자랑하려고 했기 때문이다","mis":"K5-2-u1-X21"},{"t":"학자들이 심심해했기 때문이다","mis":"K5-2-u1-X21"}],"explanation":["글에 없는 짐작이에요.","글에 없는 짐작이에요.","상황과 행동을 이어요."],"asset":{"type":"passage","lines":["세종 대왕은 조선의 넷째 임금이에요.","그 무렵 백성들은 어려운 한자를 몰라 하고 싶은 말을 글로 남기지 못했어요.","세종 대왕은 학자들과 함께 오랫동안 연구하여 우리글 훈민정음을 만들었어요.","어떤 책에서는 세종 대왕이 밤늦도록 촛불 아래에서 글자를 다듬으며","「백성이 쉽게 익혀 날마다 편히 쓰면 좋겠구나」라고 혼잣말을 했다고 그려요."],"title":"짧은 전기문 「세종 대왕」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#14','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C28',2,'match','auto','서평 「낡은 책이 다시 숨 쉬는 곳」의 문장과 서평에 들어갈 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":14,"concept":"K5-2-u1-C28","difficulty":2,"kind":"match","stem":"서평 「낡은 책이 다시 숨 쉬는 곳」의 문장과 서평에 들어갈 내용을 알맞게 이으세요.","pairs":[{"l":"바닷가 마을 아이가 등대 아래 낡은 도서관을 지키는 이야기예요","r":"책 소개"},{"l":"젖은 책을 한 장씩 말리는 장면이에요","r":"인상적인 부분"},{"l":"책을 아끼는 마음을 기르고 싶은 친구들에게 권해요","r":"책에 대한 평가"}],"mis":"K5-2-u1-X25","explanation":["어떤 책인지 알려요.","기억에 남는 장면이에요.","추천은 평가에 들어가요."],"asset":{"type":"passage","lines":["〔제목〕 낡은 책이 다시 숨 쉬는 곳","「등대 아래 도서관」은 바닷가 마을 아이가 등대 아래 낡은 도서관을 지키는 이야기예요.","해솔이는 사서 할머니에게 찢어진 책을 고치는 법을 배우고, 친구들과 도서관을 다시 열어요.","가장 인상적인 부분은 해솔이가 젖은 책을 한 장씩 말리는 장면이에요.","작은 일을 끝까지 해내는 마음이 잘 보이기 때문이에요.","책을 아끼는 마음을 기르고 싶은 친구들에게 권해요.","다만 할머니가 왜 혼자 도서관을 지켰는지가 나오지 않아 조금 아쉬워요."],"title":"서평 고쳐 쓴 글 「등대 아래 도서관」 (지어낸 책)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#15','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C36',2,'mc','auto','「이달의 책」 고르기에서 의견이 갈렸을 때 가장 알맞은 방법은 어느 것인가요?',ARRAY['K5-2-u1-X32','K5-2-u1-X33']::text[],false,'{"seq":15,"concept":"K5-2-u1-C36","difficulty":2,"kind":"mc","stem":"「이달의 책」 고르기에서 의견이 갈렸을 때 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"함께 정한 기준에 각 책을 대어 견준다","correct":true},{"t":"목소리가 가장 큰 친구의 책으로 한다","mis":"K5-2-u1-X32"},{"t":"가장 먼저 말한 친구의 책으로 한다","mis":"K5-2-u1-X32"},{"t":"토의를 그만두고 선생님께 맡긴다","mis":"K5-2-u1-X33"}],"explanation":["목소리로 정하지 않아요.","차례로 정하지 않아요.","기준에 대어 조정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#16','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C40',2,'blank','auto','「실험에서 얻은 자료를 (     )」에 들어갈 낱말은 무엇인가요?',ARRAY['K5-2-u1-X36']::text[],false,'{"seq":16,"concept":"K5-2-u1-C40","difficulty":2,"kind":"blank","stem":"「실험에서 얻은 자료를 (     )」에 들어갈 낱말은 무엇인가요?","options":[{"t":"분석하다","correct":true},{"t":"분배하다","mis":"K5-2-u1-X36"},{"t":"분류하다","mis":"K5-2-u1-X36"},{"t":"분실하다","mis":"K5-2-u1-X36"}],"explanation":["자료를 나눠 주지 않아요.","종류별로 묶는 게 아니에요.","자세히 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#17','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C10',3,'mc','auto','「종이비행기」 전체에서 느껴지는 분위기로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X07','K5-2-u1-X11']::text[],false,'{"seq":17,"concept":"K5-2-u1-C10","difficulty":3,"kind":"mc","stem":"「종이비행기」 전체에서 느껴지는 분위기로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"실수해도 괜찮다고 다정하게 응원하는 분위기","correct":true},{"t":"잘못을 꾸짖는 무서운 분위기","mis":"K5-2-u1-X07"},{"t":"비행기 접는 법을 알려 주는 설명 같은 분위기","mis":"K5-2-u1-X11"},{"t":"멀리 날린 사람만 칭찬하는 분위기","mis":"K5-2-u1-X07"}],"explanation":["꾸짖는 말은 없어요.","접는 법을 설명하는 시가 아니에요.","멀리 가지 않아도 좋다고 했어요."],"asset":{"type":"passage","lines":["접는 선이 삐뚤어도 괜찮아","처음 접은 한 줄만 기억하면","너의 비행기는 날 수 있어","멀리 가도 좋고 / 빙글 돌아와도 좋아","네가 접었다는 게 중요해"],"title":"시 「종이비행기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#18','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C12',3,'mc','auto','「운동장 그림자」를 낭송할 때 셋째 연 「그림자가 먼저 집으로 달려간다」를 읽는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X10']::text[],false,'{"seq":18,"concept":"K5-2-u1-C12","difficulty":3,"kind":"mc","stem":"「운동장 그림자」를 낭송할 때 셋째 연 「그림자가 먼저 집으로 달려간다」를 읽는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"앞 연보다 조금 빠르고 경쾌하게 읽는다","correct":true},{"t":"모든 연과 똑같은 빠르기로 읽는다","mis":"K5-2-u1-X10"},{"t":"가장 느리고 슬프게 읽는다","mis":"K5-2-u1-X10"},{"t":"읽지 않고 건너뛴다","mis":"K5-2-u1-X10"}],"explanation":["느낌이 살지 않아요.","달려가는 느낌과 어울리지 않아요.","달려가는 느낌을 살려요."],"asset":{"type":"passage","lines":["아침 운동장에선 / 내 그림자가 나보다 길다","점심 운동장에선 / 그림자가 발밑에 쪼그려 앉고","저녁 운동장에선 / 그림자가 먼저 집으로 달려간다","나는 하루 종일 / 나를 따라다니는 친구가 있다"],"title":"시 「운동장 그림자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#19','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C25',3,'mc','auto','「세종 대왕」의 인상적인 부분을 중심으로 만든 질문으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X23']::text[],false,'{"seq":19,"concept":"K5-2-u1-C25","difficulty":3,"kind":"mc","stem":"「세종 대왕」의 인상적인 부분을 중심으로 만든 질문으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「글자를 만들다 지칠 때 무엇을 떠올리며 힘을 냈나요?」","correct":true},{"t":"「몇째 임금이었나요?」","mis":"K5-2-u1-X23"},{"t":"「좋아하는 음식은 무엇이었나요?」","mis":"K5-2-u1-X23"},{"t":"「궁궐은 몇 칸이었나요?」","mis":"K5-2-u1-X23"}],"explanation":["글에 답이 그대로 있어요.","인상적인 부분과 관계없어요.","마음을 깊이 묻는 질문이에요."],"asset":{"type":"passage","lines":["세종 대왕은 조선의 넷째 임금이에요.","그 무렵 백성들은 어려운 한자를 몰라 하고 싶은 말을 글로 남기지 못했어요.","세종 대왕은 학자들과 함께 오랫동안 연구하여 우리글 훈민정음을 만들었어요.","어떤 책에서는 세종 대왕이 밤늦도록 촛불 아래에서 글자를 다듬으며","「백성이 쉽게 익혀 날마다 편히 쓰면 좋겠구나」라고 혼잣말을 했다고 그려요."],"title":"짧은 전기문 「세종 대왕」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#20','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C30',3,'mc','auto','「낡은 책이 다시 숨 쉬는 곳」의 아쉬운 점 평가가 알맞은 까닭은 무엇인가요?',ARRAY['K5-2-u1-X26','K5-2-u1-X25','K5-2-u1-X29']::text[],false,'{"seq":20,"concept":"K5-2-u1-C30","difficulty":3,"kind":"mc","stem":"「낡은 책이 다시 숨 쉬는 곳」의 아쉬운 점 평가가 알맞은 까닭은 무엇인가요?","options":[{"t":"아쉬운 점과 함께 그렇게 생각한 까닭을 밝혔기 때문에","correct":true},{"t":"아쉬운 점은 서평에 쓰면 안 되기 때문에","mis":"K5-2-u1-X26"},{"t":"줄거리를 길게 썼기 때문에","mis":"K5-2-u1-X25"},{"t":"책 제목을 그대로 썼기 때문에","mis":"K5-2-u1-X29"}],"explanation":["아쉬운 점도 쓸 수 있어요.","줄거리는 짧아요.","제목은 바꾸었어요."],"asset":{"type":"passage","lines":["〔제목〕 낡은 책이 다시 숨 쉬는 곳","「등대 아래 도서관」은 바닷가 마을 아이가 등대 아래 낡은 도서관을 지키는 이야기예요.","해솔이는 사서 할머니에게 찢어진 책을 고치는 법을 배우고, 친구들과 도서관을 다시 열어요.","가장 인상적인 부분은 해솔이가 젖은 책을 한 장씩 말리는 장면이에요.","작은 일을 끝까지 해내는 마음이 잘 보이기 때문이에요.","책을 아끼는 마음을 기르고 싶은 친구들에게 권해요.","다만 할머니가 왜 혼자 도서관을 지켰는지가 나오지 않아 조금 아쉬워요."],"title":"서평 고쳐 쓴 글 「등대 아래 도서관」 (지어낸 책)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#21','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C17',3,'mc','auto','하람이와 도윤이가 고른 연이 다른 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X15','K5-2-u1-X02','K5-2-u1-X03']::text[],false,'{"seq":21,"concept":"K5-2-u1-C17","difficulty":3,"kind":"mc","stem":"하람이와 도윤이가 고른 연이 다른 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"하람이는 표현의 재미에, 도윤이는 자기 경험에 마음이 움직여서","correct":true},{"t":"도윤이가 시를 잘못 읽어서","mis":"K5-2-u1-X15"},{"t":"셋째 연만 정답이라서","mis":"K5-2-u1-X02"},{"t":"하람이가 까닭을 말하지 않아서","mis":"K5-2-u1-X03"}],"explanation":["잘못 읽은 게 아니에요.","정답 연은 없어요.","하람이도 까닭을 말했어요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"나는 셋째 연이 인상적이야. 그림자가 먼저 집으로 달려간다니 재미있어."},{"who":"도윤","text":"나는 마지막 연! 혼자 있을 때도 그림자가 친구 같았던 적이 있거든."},{"who":"하람","text":"뭐야, 그건 시랑 상관없는 네 이야기잖아."},{"who":"도윤","text":"내 경험이 떠올라서 고른 거야. 그것도 까닭이 되지 않을까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#22','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C39',3,'mc','auto','좋아하는 책에서 인상적인 문장을 골라 친구와 나누는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X35','K5-2-u1-X03']::text[],false,'{"seq":22,"concept":"K5-2-u1-C39","difficulty":3,"kind":"mc","stem":"좋아하는 책에서 인상적인 문장을 골라 친구와 나누는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"문장과 그 문장이 인상적인 까닭을 함께 써서 돌려 읽는다","correct":true},{"t":"가장 긴 문장을 골라 낭독만 한다","mis":"K5-2-u1-X35"},{"t":"어려운 낱말이 많은 문장을 고른다","mis":"K5-2-u1-X35"},{"t":"문장만 쓰고 까닭은 쓰지 않는다","mis":"K5-2-u1-X03"}],"explanation":["길이가 기준이 아니에요.","어려움이 기준이 아니에요.","까닭이 함께 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#23','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C3',4,'essay','teacher','「운동장 그림자」에서 내가 고른 인상적인 부분과 그 까닭을 시 속 말과 이어 쓰고, 그 부분의 느낌을 살려 낭송할 방법을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u1-C3","difficulty":4,"kind":"essay","stem":"「운동장 그림자」에서 내가 고른 인상적인 부분과 그 까닭을 시 속 말과 이어 쓰고, 그 부분의 느낌을 살려 낭송할 방법을 쓰세요.","answer_guide":{"answer":"예: 둘째 연 「점심 운동장에선 / 그림자가 발밑에 쪼그려 앉고」가 인상적이다. 해가 높이 뜬 점심에 그림자가 짧아진 모습을 쪼그려 앉는 아이처럼 나타내어 귀엽게 느껴지기 때문이다. 「쪼그려 앉고」를 조금 작고 느리게, 몸을 웅크리듯 읽겠다.","scoring_points":["인상적인 부분을 골랐는가","까닭을 시 속 말과 이어 썼는가","느낌에 맞는 낭송 방법을 썼는가"]},"explanation":["한 연을 골라요.","까닭을 시와 이어요.","느낌을 소리로 살려요."],"asset":{"type":"passage","lines":["아침 운동장에선 / 내 그림자가 나보다 길다","점심 운동장에선 / 그림자가 발밑에 쪼그려 앉고","저녁 운동장에선 / 그림자가 먼저 집으로 달려간다","나는 하루 종일 / 나를 따라다니는 친구가 있다"],"title":"시 「운동장 그림자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#24','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C21',4,'essay','teacher','「세종 대왕」에서 확인된 사실 두 가지와 작가가 다시 꾸며 표현한 부분 한 가지를 찾아 쓰고, 그렇게 가려 읽어야 하는 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u1-C21","difficulty":4,"kind":"essay","stem":"「세종 대왕」에서 확인된 사실 두 가지와 작가가 다시 꾸며 표현한 부분 한 가지를 찾아 쓰고, 그렇게 가려 읽어야 하는 까닭을 쓰세요.","answer_guide":{"answer":"예: 사실 — 세종 대왕은 조선의 넷째 임금이다. 학자들과 함께 훈민정음을 만들었다. 다시 꾸민 부분 — 촛불 아래에서 「백성이 쉽게 익혀 날마다 편히 쓰면 좋겠구나」라고 혼잣말을 했다는 장면. 전기문은 사실에 근거하지만 인물의 말이나 행동은 작가가 상상해 꾸밀 수 있으므로, 가려 읽어야 인물을 바르게 알 수 있다.","scoring_points":["사실 두 가지를 썼는가","다시 꾸민 부분을 찾았는가","가려 읽는 까닭을 썼는가"]},"explanation":["확인된 일을 찾아요.","「어떤 책에서는」을 봐요.","까닭을 정리해요."],"asset":{"type":"passage","lines":["세종 대왕은 조선의 넷째 임금이에요.","그 무렵 백성들은 어려운 한자를 몰라 하고 싶은 말을 글로 남기지 못했어요.","세종 대왕은 학자들과 함께 오랫동안 연구하여 우리글 훈민정음을 만들었어요.","어떤 책에서는 세종 대왕이 밤늦도록 촛불 아래에서 글자를 다듬으며","「백성이 쉽게 익혀 날마다 편히 쓰면 좋겠구나」라고 혼잣말을 했다고 그려요."],"title":"짧은 전기문 「세종 대왕」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#25','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C2',4,'essay','teacher','이 단원에서 배운 「작품에 대한 의견을 나눌 때 꼭 지킬 것」 세 가지를 쓰고, 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u1-C2","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 「작품에 대한 의견을 나눌 때 꼭 지킬 것」 세 가지를 쓰고, 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 첫째, 인상적인 부분을 고르고 그 까닭을 작품과 이어 말한다. 둘째, 친구의 의견을 끝까지 듣고 존중한다. 셋째, 나와 다른 의견도 틀렸다고 하지 않고 그 까닭을 들어 본다. 같은 작품도 사람마다 다르게 느낄 수 있어서, 까닭을 나누고 들어야 서로의 생각을 이해하고 작품을 더 넓게 볼 수 있기 때문이다.","scoring_points":["까닭 들어 말하기를 썼는가","경청 · 존중을 썼는가","다른 의견을 인정하는 까닭을 썼는가"]},"explanation":["말하기를 떠올려요.","듣기를 떠올려요.","까닭을 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#1','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C39',1,'ox','auto','「네가 접었다는 게 중요해」처럼 짧은 문장도 인상적인 문장이 될 수 있어요.',ARRAY['K5-2-u1-X35']::text[],false,'{"seq":1,"concept":"K5-2-u1-C39","difficulty":1,"kind":"ox","stem":"「네가 접었다는 게 중요해」처럼 짧은 문장도 인상적인 문장이 될 수 있어요.","answer":"O","reason_options":[{"t":"마음이 움직이거나 깨달음이 생기면 짧고 쉬운 문장도 인상적이기 때문에","correct":true},{"t":"인상적인 문장은 길고 어려워야 하기 때문에","mis":"K5-2-u1-X35"}],"mis":"K5-2-u1-X35","explanation":["짧아도 마음에 남아요.","쉬운 말도 깊어요.","내 경험과 이어지면 더 그래요."],"asset":{"type":"passage","lines":["접는 선이 삐뚤어도 괜찮아","처음 접은 한 줄만 기억하면","너의 비행기는 날 수 있어","멀리 가도 좋고 / 빙글 돌아와도 좋아","네가 접었다는 게 중요해"],"title":"시 「종이비행기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#2','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C2',1,'mc','auto','「종이비행기」를 반 친구들이 읽고 인상적인 부분을 고르면 어떻게 될까요?',ARRAY['K5-2-u1-X02']::text[],false,'{"seq":2,"concept":"K5-2-u1-C2","difficulty":1,"kind":"mc","stem":"「종이비행기」를 반 친구들이 읽고 인상적인 부분을 고르면 어떻게 될까요?","options":[{"t":"친구마다 고른 부분이 다를 수 있다","correct":true},{"t":"모두 첫째 줄을 고르게 된다","mis":"K5-2-u1-X02"},{"t":"정답인 줄을 고른 친구만 맞는다","mis":"K5-2-u1-X02"},{"t":"아무도 고를 수 없다","mis":"K5-2-u1-X02"}],"explanation":["모두 같지 않아요.","정답 줄이 따로 있지 않아요.","누구나 고를 수 있어요."],"asset":{"type":"passage","lines":["접는 선이 삐뚤어도 괜찮아","처음 접은 한 줄만 기억하면","너의 비행기는 날 수 있어","멀리 가도 좋고 / 빙글 돌아와도 좋아","네가 접었다는 게 중요해"],"title":"시 「종이비행기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#3','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C40',1,'mc','auto','「분류하다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X36']::text[],false,'{"seq":3,"concept":"K5-2-u1-C40","difficulty":1,"kind":"mc","stem":"「분류하다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"기준에 따라 종류별로 나누거나 묶다","correct":true},{"t":"몫으로 나누어 주다","mis":"K5-2-u1-X36"},{"t":"여러 부분으로 나누어 자세히 살피다","mis":"K5-2-u1-X36"},{"t":"물건을 잃어버리다","mis":"K5-2-u1-X36"}],"explanation":["그건 분배하다예요.","그건 분석하다예요.","종류별로 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#4','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C40',1,'mc','auto','「모둠마다 색종이를 고르게 (     )」에 들어갈 낱말은 어느 것인가요?',ARRAY['K5-2-u1-X36']::text[],false,'{"seq":4,"concept":"K5-2-u1-C40","difficulty":1,"kind":"mc","stem":"「모둠마다 색종이를 고르게 (     )」에 들어갈 낱말은 어느 것인가요?","options":[{"t":"분배하다","correct":true},{"t":"분석하다","mis":"K5-2-u1-X36"},{"t":"분류하다","mis":"K5-2-u1-X36"},{"t":"분해하다","mis":"K5-2-u1-X36"}],"explanation":["자세히 살피는 게 아니에요.","종류별 나누기가 아니에요.","몫으로 나누어 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#5','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C20',1,'ox','auto','전기문은 지어낸 인물의 이야기예요.',ARRAY['K5-2-u1-X18']::text[],false,'{"seq":5,"concept":"K5-2-u1-C20","difficulty":1,"kind":"ox","stem":"전기문은 지어낸 인물의 이야기예요.","answer":"X","reason_options":[{"t":"실제로 살았던 인물의 삶을 사실에 근거하여 쓴 글이기 때문에","correct":true},{"t":"작가가 마음대로 꾸며 낸 인물이 나오기 때문에","mis":"K5-2-u1-X18"}],"mis":"K5-2-u1-X18","explanation":["실제 인물이에요.","사실에 근거해요.","그래서 감동과 교훈을 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#6','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C31',1,'ox','auto','서평과 독서 감상문은 같은 글이에요.',ARRAY['K5-2-u1-X27']::text[],false,'{"seq":6,"concept":"K5-2-u1-C31","difficulty":1,"kind":"ox","stem":"서평과 독서 감상문은 같은 글이에요.","answer":"X","reason_options":[{"t":"서평은 느낌을 넘어 책을 평가하고 그 까닭을 밝힌 글이기 때문에","correct":true},{"t":"둘 다 책을 읽고 쓴 글이기 때문에","mis":"K5-2-u1-X27"}],"mis":"K5-2-u1-X27","explanation":["책을 읽고 쓴 것은 같아요.","평가와 까닭이 있는지 달라요.","서평은 추천도 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#7','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C6',1,'mc','auto','「운동장 그림자」에서 점심 운동장의 그림자는 어떠한가요?',ARRAY['K5-2-u1-X06']::text[],false,'{"seq":7,"concept":"K5-2-u1-C6","difficulty":1,"kind":"mc","stem":"「운동장 그림자」에서 점심 운동장의 그림자는 어떠한가요?","options":[{"t":"발밑에 쪼그려 앉는다","correct":true},{"t":"나보다 길다","mis":"K5-2-u1-X06"},{"t":"먼저 집으로 달려간다","mis":"K5-2-u1-X06"},{"t":"사라져 버린다","mis":"K5-2-u1-X06"}],"explanation":["아침 그림자예요.","저녁 그림자예요.","둘째 연에 나와요."],"asset":{"type":"passage","lines":["아침 운동장에선 / 내 그림자가 나보다 길다","점심 운동장에선 / 그림자가 발밑에 쪼그려 앉고","저녁 운동장에선 / 그림자가 먼저 집으로 달려간다","나는 하루 종일 / 나를 따라다니는 친구가 있다"],"title":"시 「운동장 그림자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#8','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C18',1,'ox','auto','친구의 다른 의견을 들으면 작품을 새로운 관점으로 볼 수 있어요.',ARRAY['K5-2-u1-X16']::text[],false,'{"seq":8,"concept":"K5-2-u1-C18","difficulty":1,"kind":"ox","stem":"친구의 다른 의견을 들으면 작품을 새로운 관점으로 볼 수 있어요.","answer":"O","reason_options":[{"t":"내가 미처 생각하지 못한 부분을 알게 되기 때문에","correct":true},{"t":"다른 의견은 내 생각을 헷갈리게만 하기 때문에","mis":"K5-2-u1-X16"}],"mis":"K5-2-u1-X16","explanation":["다른 의견이 생각을 넓혀요.","헷갈리게 하는 게 아니에요.","귀 기울여 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#9','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C3',2,'error','auto','「운동장 그림자」를 읽고 쓴 감상이에요. 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u1-X03','K5-2-u1-X01','K5-2-u1-X07']::text[],false,'{"seq":9,"concept":"K5-2-u1-C3","difficulty":2,"kind":"error","stem":"「운동장 그림자」를 읽고 쓴 감상이에요. 알맞지 않은 것은 어느 것인가요?","options":[{"t":"「넷째 연이 좋다. 그냥 좋다.」","correct":true,"mis_target":"K5-2-u1-X03"},{"t":"「첫째 연이 인상적이다. 아침 그림자가 나보다 길다는 것을 처음 알아차리게 되었다.」","mis":"K5-2-u1-X01"},{"t":"「둘째 연이 인상적이다. 그림자가 쪼그려 앉는다는 말이 귀엽다.」","mis":"K5-2-u1-X07"}],"explanation":["깨달음이 까닭이에요.","표현이 주는 느낌이 까닭이에요.","까닭이 없어요."],"asset":{"type":"passage","lines":["아침 운동장에선 / 내 그림자가 나보다 길다","점심 운동장에선 / 그림자가 발밑에 쪼그려 앉고","저녁 운동장에선 / 그림자가 먼저 집으로 달려간다","나는 하루 종일 / 나를 따라다니는 친구가 있다"],"title":"시 「운동장 그림자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#10','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C8',2,'ox','auto','도윤이처럼 「혼자 있을 때 그림자가 친구 같았던 경험」을 까닭으로 드는 것은 알맞아요.',ARRAY['K5-2-u1-X08']::text[],false,'{"seq":10,"concept":"K5-2-u1-C8","difficulty":2,"kind":"ox","stem":"도윤이처럼 「혼자 있을 때 그림자가 친구 같았던 경험」을 까닭으로 드는 것은 알맞아요.","answer":"O","reason_options":[{"t":"시의 마지막 연과 이어지는 내 경험은 인상적인 까닭이 될 수 있기 때문에","correct":true},{"t":"내 경험은 작품 밖의 이야기라 까닭이 될 수 없기 때문에","mis":"K5-2-u1-X08"}],"mis":"K5-2-u1-X08","explanation":["공감도 까닭이에요.","시와 이어진 경험이에요.","「나도 그랬지」가 까닭이 돼요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"나는 셋째 연이 인상적이야. 그림자가 먼저 집으로 달려간다니 재미있어."},{"who":"도윤","text":"나는 마지막 연! 혼자 있을 때도 그림자가 친구 같았던 적이 있거든."},{"who":"하람","text":"뭐야, 그건 시랑 상관없는 네 이야기잖아."},{"who":"도윤","text":"내 경험이 떠올라서 고른 거야. 그것도 까닭이 되지 않을까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#11','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C11',2,'mc','auto','「그림자가 먼저 집으로 달려간다」에서 그림자를 무엇처럼 나타냈나요?',ARRAY['K5-2-u1-X09']::text[],false,'{"seq":11,"concept":"K5-2-u1-C11","difficulty":2,"kind":"mc","stem":"「그림자가 먼저 집으로 달려간다」에서 그림자를 무엇처럼 나타냈나요?","options":[{"t":"먼저 뛰어가는 사람이나 친구","correct":true},{"t":"멈춰 있는 돌","mis":"K5-2-u1-X09"},{"t":"하늘의 구름","mis":"K5-2-u1-X09"},{"t":"운동장의 모래","mis":"K5-2-u1-X09"}],"explanation":["움직이는 모습이에요.","구름 이야기는 없어요.","사람처럼 나타냈어요."],"asset":{"type":"passage","lines":["아침 운동장에선 / 내 그림자가 나보다 길다","점심 운동장에선 / 그림자가 발밑에 쪼그려 앉고","저녁 운동장에선 / 그림자가 먼저 집으로 달려간다","나는 하루 종일 / 나를 따라다니는 친구가 있다"],"title":"시 「운동장 그림자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#12','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C21',2,'ox','auto','「세종 대왕」에 나온 혼잣말은 그날 그대로 받아 적은 말이 틀림없어요.',ARRAY['K5-2-u1-X19']::text[],false,'{"seq":12,"concept":"K5-2-u1-C21","difficulty":2,"kind":"ox","stem":"「세종 대왕」에 나온 혼잣말은 그날 그대로 받아 적은 말이 틀림없어요.","answer":"X","reason_options":[{"t":"전기문 속 인물의 말은 작가가 상상하거나 다시 꾸며 표현한 것일 수 있기 때문에","correct":true},{"t":"전기문에 나온 말은 모두 그대로 받아 적은 것이기 때문에","mis":"K5-2-u1-X19"}],"mis":"K5-2-u1-X19","explanation":["「어떤 책에서는 그려요」라고 했어요.","그대로라고 단정할 수 없어요.","사실과 꾸민 부분을 가려요."],"asset":{"type":"passage","lines":["세종 대왕은 조선의 넷째 임금이에요.","그 무렵 백성들은 어려운 한자를 몰라 하고 싶은 말을 글로 남기지 못했어요.","세종 대왕은 학자들과 함께 오랫동안 연구하여 우리글 훈민정음을 만들었어요.","어떤 책에서는 세종 대왕이 밤늦도록 촛불 아래에서 글자를 다듬으며","「백성이 쉽게 익혀 날마다 편히 쓰면 좋겠구나」라고 혼잣말을 했다고 그려요."],"title":"짧은 전기문 「세종 대왕」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#13','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C22',2,'mc','auto','전기문 속 인물이 한 일을 이해하려면 무엇을 함께 알아야 하나요?',ARRAY['K5-2-u1-X20']::text[],false,'{"seq":13,"concept":"K5-2-u1-C22","difficulty":2,"kind":"mc","stem":"전기문 속 인물이 한 일을 이해하려면 무엇을 함께 알아야 하나요?","options":[{"t":"인물이 살았던 때와 곳의 상황","correct":true},{"t":"인물의 키와 몸무게","mis":"K5-2-u1-X20"},{"t":"인물이 좋아한 색깔","mis":"K5-2-u1-X20"},{"t":"책의 쪽수","mis":"K5-2-u1-X20"}],"explanation":["행동의 까닭과 관계없어요.","행동의 까닭과 관계없어요.","시대 상황이 행동의 까닭이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#14','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C29',2,'mc','auto','고쳐 쓴 서평 「낡은 책이 다시 숨 쉬는 곳」에서 줄거리는 어떻게 쓰였나요?',ARRAY['K5-2-u1-X25','K5-2-u1-X28','K5-2-u1-X29']::text[],false,'{"seq":14,"concept":"K5-2-u1-C29","difficulty":2,"kind":"mc","stem":"고쳐 쓴 서평 「낡은 책이 다시 숨 쉬는 곳」에서 줄거리는 어떻게 쓰였나요?","options":[{"t":"중요한 일만 골라 한 문장으로 간추렸다","correct":true},{"t":"날마다 일어난 일을 빠짐없이 썼다","mis":"K5-2-u1-X25"},{"t":"줄거리를 하나도 쓰지 않았다","mis":"K5-2-u1-X28"},{"t":"마지막 장면만 썼다","mis":"K5-2-u1-X29"}],"explanation":["첫 초안이 그랬어요.","간단한 줄거리는 있어요.","중요한 일을 차례대로 썼어요."],"asset":{"type":"passage","lines":["〔제목〕 낡은 책이 다시 숨 쉬는 곳","「등대 아래 도서관」은 바닷가 마을 아이가 등대 아래 낡은 도서관을 지키는 이야기예요.","해솔이는 사서 할머니에게 찢어진 책을 고치는 법을 배우고, 친구들과 도서관을 다시 열어요.","가장 인상적인 부분은 해솔이가 젖은 책을 한 장씩 말리는 장면이에요.","작은 일을 끝까지 해내는 마음이 잘 보이기 때문이에요.","책을 아끼는 마음을 기르고 싶은 친구들에게 권해요.","다만 할머니가 왜 혼자 도서관을 지켰는지가 나오지 않아 조금 아쉬워요."],"title":"서평 고쳐 쓴 글 「등대 아래 도서관」 (지어낸 책)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#15','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C36',2,'ox','auto','의견이 갈리면 먼저 말한 친구의 책으로 정하는 것이 공평해요.',ARRAY['K5-2-u1-X32']::text[],false,'{"seq":15,"concept":"K5-2-u1-C36","difficulty":2,"kind":"ox","stem":"의견이 갈리면 먼저 말한 친구의 책으로 정하는 것이 공평해요.","answer":"X","reason_options":[{"t":"말한 차례가 아니라 함께 정한 기준에 대어 견주어야 모두가 받아들일 수 있기 때문에","correct":true},{"t":"먼저 말한 친구가 가장 깊이 생각했기 때문에","mis":"K5-2-u1-X32"}],"mis":"K5-2-u1-X32","explanation":["차례는 기준이 아니에요.","기준을 함께 정해요.","까닭으로 조정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#16','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C40',2,'blank','auto','「수확한 감자를 마을 사람들에게 (     )」에 들어갈 낱말은 무엇인가요?',ARRAY['K5-2-u1-X36']::text[],false,'{"seq":16,"concept":"K5-2-u1-C40","difficulty":2,"kind":"blank","stem":"「수확한 감자를 마을 사람들에게 (     )」에 들어갈 낱말은 무엇인가요?","options":[{"t":"분배하다","correct":true},{"t":"분석하다","mis":"K5-2-u1-X36"},{"t":"분류하다","mis":"K5-2-u1-X36"},{"t":"분해하다","mis":"K5-2-u1-X36"}],"explanation":["살피는 게 아니에요.","종류별로 묶는 게 아니에요.","몫으로 나누어 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#17','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C10',3,'mc','auto','「종이비행기」의 말하는 이는 누구에게 말하는 것 같나요?',ARRAY['K5-2-u1-X09']::text[],false,'{"seq":17,"concept":"K5-2-u1-C10","difficulty":3,"kind":"mc","stem":"「종이비행기」의 말하는 이는 누구에게 말하는 것 같나요?","options":[{"t":"처음 무엇을 해 보며 실수할까 걱정하는 친구","correct":true},{"t":"비행기를 만드는 공장 사람","mis":"K5-2-u1-X09"},{"t":"종이비행기 대회 심사 위원","mis":"K5-2-u1-X09"},{"t":"하늘을 나는 새","mis":"K5-2-u1-X09"}],"explanation":["글자 그대로만 읽었어요.","대회 이야기는 없어요.","「너」에게 응원하는 말이에요."],"asset":{"type":"passage","lines":["접는 선이 삐뚤어도 괜찮아","처음 접은 한 줄만 기억하면","너의 비행기는 날 수 있어","멀리 가도 좋고 / 빙글 돌아와도 좋아","네가 접었다는 게 중요해"],"title":"시 「종이비행기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#18','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C15',3,'mc','auto','「운동장 그림자」에서 그림자의 모습은 어떻게 바뀌나요?',ARRAY['K5-2-u1-X14']::text[],false,'{"seq":18,"concept":"K5-2-u1-C15","difficulty":3,"kind":"mc","stem":"「운동장 그림자」에서 그림자의 모습은 어떻게 바뀌나요?","options":[{"t":"길다가 → 발밑에 짧게 쪼그렸다가 → 먼저 달려간다","correct":true},{"t":"하루 종일 똑같이 길다","mis":"K5-2-u1-X14"},{"t":"짧다가 → 사라졌다가 → 다시 짧아진다","mis":"K5-2-u1-X14"},{"t":"아침부터 저녁까지 보이지 않는다","mis":"K5-2-u1-X14"}],"explanation":["하루 동안 바뀌어요.","사라지지 않아요.","연마다 따라가요."],"asset":{"type":"passage","lines":["아침 운동장에선 / 내 그림자가 나보다 길다","점심 운동장에선 / 그림자가 발밑에 쪼그려 앉고","저녁 운동장에선 / 그림자가 먼저 집으로 달려간다","나는 하루 종일 / 나를 따라다니는 친구가 있다"],"title":"시 「운동장 그림자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#19','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C24',3,'mc','auto','「세종 대왕」에서 인상적인 부분으로 고를 만한 것을 가장 넓게 말한 것은 어느 것인가요?',ARRAY['K5-2-u1-X22','K5-2-u1-X01']::text[],false,'{"seq":19,"concept":"K5-2-u1-C24","difficulty":3,"kind":"mc","stem":"「세종 대왕」에서 인상적인 부분으로 고를 만한 것을 가장 넓게 말한 것은 어느 것인가요?","options":[{"t":"백성의 어려움을 살핀 마음, 오랜 연구, 촛불 아래 장면처럼 여러 가지가 될 수 있다","correct":true},{"t":"훈민정음을 만든 한 문장뿐이다","mis":"K5-2-u1-X22"},{"t":"첫 문장뿐이다","mis":"K5-2-u1-X22"},{"t":"임금이라는 낱말뿐이다","mis":"K5-2-u1-X01"}],"explanation":["하나만이 아니에요.","첫 문장만이 아니에요.","여러 가지가 될 수 있어요."],"asset":{"type":"passage","lines":["세종 대왕은 조선의 넷째 임금이에요.","그 무렵 백성들은 어려운 한자를 몰라 하고 싶은 말을 글로 남기지 못했어요.","세종 대왕은 학자들과 함께 오랫동안 연구하여 우리글 훈민정음을 만들었어요.","어떤 책에서는 세종 대왕이 밤늦도록 촛불 아래에서 글자를 다듬으며","「백성이 쉽게 익혀 날마다 편히 쓰면 좋겠구나」라고 혼잣말을 했다고 그려요."],"title":"짧은 전기문 「세종 대왕」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#20','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C32',3,'mc','auto','「등대 아래 도서관」 서평의 제목으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X29','K5-2-u1-X28']::text[],false,'{"seq":20,"concept":"K5-2-u1-C32","difficulty":3,"kind":"mc","stem":"「등대 아래 도서관」 서평의 제목으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「젖은 책을 말리던 손, 다시 열린 도서관」","correct":true},{"t":"「등대 아래 도서관」","mis":"K5-2-u1-X29"},{"t":"「서평」","mis":"K5-2-u1-X29"},{"t":"「재미있는 책」","mis":"K5-2-u1-X28"}],"explanation":["책 제목 그대로예요.","무엇에 대한 글인지 몰라요.","핵심 장면이 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#21','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C18',3,'error','auto','「운동장 그림자」를 읽고 모둠에서 나눈 말이에요. 알맞지 않은 태도는 어느 것인가요?',ARRAY['K5-2-u1-X16','K5-2-u1-X18','K5-2-u1-X17']::text[],false,'{"seq":21,"concept":"K5-2-u1-C18","difficulty":3,"kind":"error","stem":"「운동장 그림자」를 읽고 모둠에서 나눈 말이에요. 알맞지 않은 태도는 어느 것인가요?","options":[{"t":"「그건 시랑 상관없는 네 이야기잖아.」","correct":true,"mis_target":"K5-2-u1-X16"},{"t":"「네 경험을 들으니 마지막 연이 다르게 읽혀.」","mis":"K5-2-u1-X18"},{"t":"「나는 셋째 연을 골랐는데, 네가 고른 까닭도 들어 볼래.」","mis":"K5-2-u1-X17"}],"explanation":["친구 말에서 배웠어요.","끝까지 들으려 해요.","친구의 까닭을 듣기 전에 깎아내렸어요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"나는 셋째 연이 인상적이야. 그림자가 먼저 집으로 달려간다니 재미있어."},{"who":"도윤","text":"나는 마지막 연! 혼자 있을 때도 그림자가 친구 같았던 적이 있거든."},{"who":"하람","text":"뭐야, 그건 시랑 상관없는 네 이야기잖아."},{"who":"도윤","text":"내 경험이 떠올라서 고른 거야. 그것도 까닭이 되지 않을까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#22','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C26',3,'mc','auto','「세종 대왕」에서 본받을 점을 오늘의 나와 바르게 이은 것은 어느 것인가요?',ARRAY['K5-2-u1-X24','K5-2-u1-X21']::text[],false,'{"seq":22,"concept":"K5-2-u1-C26","difficulty":3,"kind":"mc","stem":"「세종 대왕」에서 본받을 점을 오늘의 나와 바르게 이은 것은 어느 것인가요?","options":[{"t":"어려워하는 친구를 위해 쉽게 설명하는 방법을 고민한다","correct":true},{"t":"옛날 임금 이야기라 나와는 관계없다","mis":"K5-2-u1-X24"},{"t":"글자를 새로 만들어 친구들에게 쓰라고 한다","mis":"K5-2-u1-X21"},{"t":"밤늦게 촛불을 켜고 공부한다","mis":"K5-2-u1-X21"}],"explanation":["옛이야기도 오늘과 이어져요.","흉내가 본받기는 아니에요.","장면만 따라 하면 뜻을 놓쳐요."],"asset":{"type":"passage","lines":["세종 대왕은 조선의 넷째 임금이에요.","그 무렵 백성들은 어려운 한자를 몰라 하고 싶은 말을 글로 남기지 못했어요.","세종 대왕은 학자들과 함께 오랫동안 연구하여 우리글 훈민정음을 만들었어요.","어떤 책에서는 세종 대왕이 밤늦도록 촛불 아래에서 글자를 다듬으며","「백성이 쉽게 익혀 날마다 편히 쓰면 좋겠구나」라고 혼잣말을 했다고 그려요."],"title":"짧은 전기문 「세종 대왕」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#23','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C10',4,'essay','teacher','「종이비행기」의 말하는 이가 누구에게 어떤 마음으로 하는 말인지 쓰고, 시 전체의 분위기와 그렇게 느낀 까닭을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u1-C10","difficulty":4,"kind":"essay","stem":"「종이비행기」의 말하는 이가 누구에게 어떤 마음으로 하는 말인지 쓰고, 시 전체의 분위기와 그렇게 느낀 까닭을 쓰세요.","answer_guide":{"answer":"예: 처음 무엇을 해 보며 실수할까 걱정하는 친구에게 응원하는 마음으로 하는 말이다. 시 전체가 다정하고 따뜻한 분위기이다. 「삐뚤어도 괜찮아」, 「빙글 돌아와도 좋아」처럼 잘못해도 괜찮다고 감싸 주는 말이 이어지고, 마지막에 「네가 접었다는 게 중요해」라고 해서 잘 날았는지보다 해 본 것을 칭찬하기 때문이다.","scoring_points":["누구에게 하는 말인지 썼는가","말하는 이의 마음을 썼는가","분위기와 까닭을 시와 이어 썼는가"]},"explanation":["「너」가 누구일지 떠올려요.","마음을 짐작해요.","분위기의 까닭을 시에서 찾아요."],"asset":{"type":"passage","lines":["접는 선이 삐뚤어도 괜찮아","처음 접은 한 줄만 기억하면","너의 비행기는 날 수 있어","멀리 가도 좋고 / 빙글 돌아와도 좋아","네가 접었다는 게 중요해"],"title":"시 「종이비행기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#24','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C23',4,'essay','teacher','「세종 대왕」에서 인상적인 부분을 하나 고르고, 그 무렵의 상황과 이어 인상적인 까닭을 쓴 뒤 세종 대왕에게 묻고 싶은 질문을 하나 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u1-C23","difficulty":4,"kind":"essay","stem":"「세종 대왕」에서 인상적인 부분을 하나 고르고, 그 무렵의 상황과 이어 인상적인 까닭을 쓴 뒤 세종 대왕에게 묻고 싶은 질문을 하나 쓰세요.","answer_guide":{"answer":"예: 학자들과 오랫동안 연구하여 훈민정음을 만든 부분이 인상적이다. 그 무렵 백성들은 한자를 몰라 억울한 일이 있어도 글로 남기지 못했는데, 임금이 그 어려움을 살펴 누구나 쓸 수 있는 글자를 만들었기 때문이다. 질문 — 「글자를 만들자고 했을 때 반대하는 사람은 없었나요? 그때 어떻게 마음을 지켰나요?」","scoring_points":["인상적인 부분을 골랐는가","시대 상황과 이어 까닭을 썼는가","인상적인 부분에서 나온 질문을 썼는가"]},"explanation":["부분을 골라요.","그 무렵 상황과 이어요.","마음을 묻는 질문을 만들어요."],"asset":{"type":"passage","lines":["세종 대왕은 조선의 넷째 임금이에요.","그 무렵 백성들은 어려운 한자를 몰라 하고 싶은 말을 글로 남기지 못했어요.","세종 대왕은 학자들과 함께 오랫동안 연구하여 우리글 훈민정음을 만들었어요.","어떤 책에서는 세종 대왕이 밤늦도록 촛불 아래에서 글자를 다듬으며","「백성이 쉽게 익혀 날마다 편히 쓰면 좋겠구나」라고 혼잣말을 했다고 그려요."],"title":"짧은 전기문 「세종 대왕」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#25','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C4',4,'essay','teacher','시와 이야기에서 인상적인 부분을 찾을 때 살피는 것이 어떻게 다른지 쓰고, 이 단원에서 읽은 작품으로 예를 하나씩 드세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u1-C4","difficulty":4,"kind":"essay","stem":"시와 이야기에서 인상적인 부분을 찾을 때 살피는 것이 어떻게 다른지 쓰고, 이 단원에서 읽은 작품으로 예를 하나씩 드세요.","answer_guide":{"answer":"예: 시에서는 독특한 표현, 말하는 이의 마음, 분위기를 살핀다. 예를 들어 「말의 온도」에서는 「말은 마음에 찍히는 발자국」이라는 빗댄 표현이 인상적이다. 이야기에서는 인물이 처한 상황, 인물의 말과 행동, 사건의 흐름을 살핀다. 예를 들어 「유관순」에서는 재판에서도 굽히지 않은 행동이 나라를 빼앗긴 상황과 이어져 인상적이다.","scoring_points":["시에서 살필 것을 썼는가","이야기에서 살필 것을 썼는가","작품 예를 하나씩 들었는가"]},"explanation":["시를 떠올려요.","이야기를 떠올려요.","예를 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#1','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C39',1,'mc','auto','「종이비행기」에서 「나도 실수했을 때 이런 말을 듣고 싶었어」라는 까닭과 가장 잘 어울리는 문장은 어느 것인가요?',ARRAY['K5-2-u1-X04','K5-2-u1-X11']::text[],false,'{"seq":1,"concept":"K5-2-u1-C39","difficulty":1,"kind":"mc","stem":"「종이비행기」에서 「나도 실수했을 때 이런 말을 듣고 싶었어」라는 까닭과 가장 잘 어울리는 문장은 어느 것인가요?","options":[{"t":"「접는 선이 삐뚤어도 괜찮아」","correct":true},{"t":"「멀리 가도 좋고」","mis":"K5-2-u1-X04"},{"t":"「너의 비행기는 날 수 있어」","mis":"K5-2-u1-X04"},{"t":"제목 「종이비행기」","mis":"K5-2-u1-X11"}],"explanation":["실수 이야기와 이어지지 않아요.","실수 이야기와 이어지지 않아요.","실수를 감싸 주는 말이에요."],"asset":{"type":"passage","lines":["접는 선이 삐뚤어도 괜찮아","처음 접은 한 줄만 기억하면","너의 비행기는 날 수 있어","멀리 가도 좋고 / 빙글 돌아와도 좋아","네가 접었다는 게 중요해"],"title":"시 「종이비행기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#2','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C17',1,'mc','auto','친구마다 인상적인 부분이 다른 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X15']::text[],false,'{"seq":2,"concept":"K5-2-u1-C17","difficulty":1,"kind":"mc","stem":"친구마다 인상적인 부분이 다른 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"경험 · 관심사 · 배경지식이 서로 달라서","correct":true},{"t":"시를 읽는 속도가 달라서","mis":"K5-2-u1-X15"},{"t":"앉은 줄이 달라서","mis":"K5-2-u1-X15"},{"t":"한 사람만 시를 바르게 읽어서","mis":"K5-2-u1-X15"}],"explanation":["속도가 까닭이 아니에요.","앉은 곳과 관계없어요.","바르게 읽은 사람이 하나인 게 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#3','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C40',1,'ox','auto','「옷을 계절별로 분류하다」는 낱말을 알맞게 쓴 문장이에요.',ARRAY['K5-2-u1-X36']::text[],false,'{"seq":3,"concept":"K5-2-u1-C40","difficulty":1,"kind":"ox","stem":"「옷을 계절별로 분류하다」는 낱말을 알맞게 쓴 문장이에요.","answer":"O","reason_options":[{"t":"계절이라는 기준에 따라 종류별로 나누는 일이기 때문에","correct":true},{"t":"옷을 여러 사람에게 몫으로 나누어 주는 일이기 때문에","mis":"K5-2-u1-X36"}],"mis":"K5-2-u1-X36","explanation":["기준이 있어요.","종류별로 나눠요.","분류하다가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#4','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C40',1,'match','auto','낱말과 알맞은 문장을 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K5-2-u1-C40","difficulty":1,"kind":"match","stem":"낱말과 알맞은 문장을 이으세요.","pairs":[{"l":"분류하다","r":"자료를 시대별로 나누어 묶는다"},{"l":"분석하다","r":"인물의 성격을 자세히 살핀다"},{"l":"분배하다","r":"도시락을 사람들에게 나누어 준다"}],"mis":"K5-2-u1-X36","explanation":["기준에 따라 묶어요.","부분으로 나누어 살펴요.","몫으로 나누어 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#5','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C22',1,'mc','auto','「세종 대왕」에서 그 무렵 백성들이 겪은 어려움은 무엇인가요?',ARRAY['K5-2-u1-X20']::text[],false,'{"seq":5,"concept":"K5-2-u1-C22","difficulty":1,"kind":"mc","stem":"「세종 대왕」에서 그 무렵 백성들이 겪은 어려움은 무엇인가요?","options":[{"t":"어려운 한자를 몰라 하고 싶은 말을 글로 남기지 못했다","correct":true},{"t":"먹을 것이 너무 많았다","mis":"K5-2-u1-X20"},{"t":"글자가 너무 많아 고르기 어려웠다","mis":"K5-2-u1-X20"},{"t":"학교가 너무 멀었다","mis":"K5-2-u1-X20"}],"explanation":["글에 없는 말이에요.","글자가 많아서가 아니에요.","이 상황이 훈민정음을 만든 까닭이에요."],"asset":{"type":"passage","lines":["세종 대왕은 조선의 넷째 임금이에요.","그 무렵 백성들은 어려운 한자를 몰라 하고 싶은 말을 글로 남기지 못했어요.","세종 대왕은 학자들과 함께 오랫동안 연구하여 우리글 훈민정음을 만들었어요.","어떤 책에서는 세종 대왕이 밤늦도록 촛불 아래에서 글자를 다듬으며","「백성이 쉽게 익혀 날마다 편히 쓰면 좋겠구나」라고 혼잣말을 했다고 그려요."],"title":"짧은 전기문 「세종 대왕」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#6','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C31',1,'match','auto','글의 종류와 그 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K5-2-u1-C31","difficulty":1,"kind":"match","stem":"글의 종류와 그 특징을 알맞게 이으세요.","pairs":[{"l":"독서 감상문","r":"떠오른 생각이나 느낌을 자유롭게 쓴다"},{"l":"서평","r":"좋은 점 · 아쉬운 점을 평가하고 까닭을 밝힌다"},{"l":"전기문","r":"실제 인물의 삶을 사실에 근거해 쓴다"}],"mis":"K5-2-u1-X27","explanation":["느낌을 자유롭게 써요.","평가와 까닭을 밝혀요.","실제 인물의 삶을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#7','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C6',1,'mc','auto','「운동장 그림자」에서 「나를 따라다니는 친구」는 무엇인가요?',ARRAY['K5-2-u1-X06']::text[],false,'{"seq":7,"concept":"K5-2-u1-C6","difficulty":1,"kind":"mc","stem":"「운동장 그림자」에서 「나를 따라다니는 친구」는 무엇인가요?","options":[{"t":"내 그림자","correct":true},{"t":"짝꿍","mis":"K5-2-u1-X06"},{"t":"운동장","mis":"K5-2-u1-X06"},{"t":"해","mis":"K5-2-u1-X06"}],"explanation":["사람 친구가 아니에요.","운동장은 곳이에요.","하루 종일 따라다니는 것은 그림자예요."],"asset":{"type":"passage","lines":["아침 운동장에선 / 내 그림자가 나보다 길다","점심 운동장에선 / 그림자가 발밑에 쪼그려 앉고","저녁 운동장에선 / 그림자가 먼저 집으로 달려간다","나는 하루 종일 / 나를 따라다니는 친구가 있다"],"title":"시 「운동장 그림자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#8','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C37',1,'mc','auto','모둠 토의에서 다양한 의견을 대하는 태도로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X33','K5-2-u1-X32','K5-2-u1-X16']::text[],false,'{"seq":8,"concept":"K5-2-u1-C37","difficulty":1,"kind":"mc","stem":"모둠 토의에서 다양한 의견을 대하는 태도로 알맞은 것은 어느 것인가요?","options":[{"t":"나와 다른 의견도 인정한다","correct":true},{"t":"뽑히지 않은 의견은 무시한다","mis":"K5-2-u1-X33"},{"t":"내 의견이 뽑힐 때까지 고집한다","mis":"K5-2-u1-X32"},{"t":"다른 의견은 놀린다","mis":"K5-2-u1-X16"}],"explanation":["뽑히지 않은 의견도 소중해요.","기준에 대어 조정해요.","존중해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#9','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C4',2,'mc','auto','「종이비행기」에서 인상적인 부분을 말할 때 정답이 없다는 것의 바른 뜻은 어느 것인가요?',ARRAY['K5-2-u1-X04','K5-2-u1-X02','K5-2-u1-X03']::text[],false,'{"seq":9,"concept":"K5-2-u1-C4","difficulty":2,"kind":"mc","stem":"「종이비행기」에서 인상적인 부분을 말할 때 정답이 없다는 것의 바른 뜻은 어느 것인가요?","options":[{"t":"어느 줄을 골라도 되지만 그 까닭은 시와 이어져야 한다","correct":true},{"t":"아무 까닭이나 대도 된다","mis":"K5-2-u1-X04"},{"t":"첫째 줄만 골라야 한다","mis":"K5-2-u1-X02"},{"t":"까닭은 말하지 않아도 된다","mis":"K5-2-u1-X03"}],"explanation":["까닭은 시와 이어져야 해요.","정해진 줄이 없어요.","까닭이 함께 가요."],"asset":{"type":"passage","lines":["접는 선이 삐뚤어도 괜찮아","처음 접은 한 줄만 기억하면","너의 비행기는 날 수 있어","멀리 가도 좋고 / 빙글 돌아와도 좋아","네가 접었다는 게 중요해"],"title":"시 「종이비행기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#10','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C13',2,'mc','auto','「종이비행기」에 공감한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X12','K5-2-u1-X01']::text[],false,'{"seq":10,"concept":"K5-2-u1-C13","difficulty":2,"kind":"mc","stem":"「종이비행기」에 공감한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「만들기를 망쳤을 때 선생님이 〈네가 만든 게 중요해〉라고 해 주셔서 힘이 났던 일이 떠올라.」","correct":true},{"t":"「나는 비행기를 타 본 적이 없어서 공감할 수 없어.」","mis":"K5-2-u1-X12"},{"t":"「종이라는 낱말이 쉬워서.」","mis":"K5-2-u1-X01"},{"t":"「다섯 줄이라서.」","mis":"K5-2-u1-X01"}],"explanation":["똑같은 일을 겪지 않아도 공감해요.","낱말이 쉬운 것은 까닭이 아니에요.","줄 수는 까닭이 아니에요."],"asset":{"type":"passage","lines":["접는 선이 삐뚤어도 괜찮아","처음 접은 한 줄만 기억하면","너의 비행기는 날 수 있어","멀리 가도 좋고 / 빙글 돌아와도 좋아","네가 접었다는 게 중요해"],"title":"시 「종이비행기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#11','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C11',2,'ox','auto','「종이비행기」의 「처음 접은 한 줄」은 처음 시작한 마음을 빗대어 나타냈다고 볼 수 있어요.',ARRAY['K5-2-u1-X09']::text[],false,'{"seq":11,"concept":"K5-2-u1-C11","difficulty":2,"kind":"ox","stem":"「종이비행기」의 「처음 접은 한 줄」은 처음 시작한 마음을 빗대어 나타냈다고 볼 수 있어요.","answer":"O","reason_options":[{"t":"첫 줄을 기억하면 날 수 있다는 말이 처음 마음을 잃지 말라는 뜻과 닮았기 때문에","correct":true},{"t":"종이에 접은 선 한 줄만을 글자 그대로 말하기 때문에","mis":"K5-2-u1-X09"}],"mis":"K5-2-u1-X09","explanation":["닮은 점을 찾아요.","글자 그대로만 읽지 않아요.","처음 마음과 닮았어요."],"asset":{"type":"passage","lines":["접는 선이 삐뚤어도 괜찮아","처음 접은 한 줄만 기억하면","너의 비행기는 날 수 있어","멀리 가도 좋고 / 빙글 돌아와도 좋아","네가 접었다는 게 중요해"],"title":"시 「종이비행기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#12','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C21',2,'mc','auto','전기문을 바르게 읽는 방법은 어느 것인가요?',ARRAY['K5-2-u1-X19','K5-2-u1-X18','K5-2-u1-X20']::text[],false,'{"seq":12,"concept":"K5-2-u1-C21","difficulty":2,"kind":"mc","stem":"전기문을 바르게 읽는 방법은 어느 것인가요?","options":[{"t":"확인된 사실과 작가가 다시 꾸몄을 수 있는 부분을 가려 읽는다","correct":true},{"t":"적힌 말을 모두 그날 그대로의 말로 믿는다","mis":"K5-2-u1-X19"},{"t":"지어낸 이야기로 여기고 가볍게 읽는다","mis":"K5-2-u1-X18"},{"t":"연도만 골라 외운다","mis":"K5-2-u1-X20"}],"explanation":["그대로라고 단정할 수 없어요.","사실에 근거한 글이에요.","외우기가 목적이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#13','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C22',2,'ox','auto','유관순과 세종 대왕이 한 일은 그 시대의 상황을 알아야 더 잘 이해할 수 있어요.',ARRAY['K5-2-u1-X20']::text[],false,'{"seq":13,"concept":"K5-2-u1-C22","difficulty":2,"kind":"ox","stem":"유관순과 세종 대왕이 한 일은 그 시대의 상황을 알아야 더 잘 이해할 수 있어요.","answer":"O","reason_options":[{"t":"인물이 처한 상황이 그 일을 한 까닭이 되기 때문에","correct":true},{"t":"인물이 한 일은 시대와 관계없이 이해되기 때문에","mis":"K5-2-u1-X20"}],"mis":"K5-2-u1-X20","explanation":["시대가 까닭을 알려 줘요.","상황과 행동을 이어요.","때와 곳을 알아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#14','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C28',2,'mc','auto','서평에 꼭 들어갈 내용이 아닌 것은 어느 것인가요?',ARRAY['K5-2-u1-X25','K5-2-u1-X26']::text[],false,'{"seq":14,"concept":"K5-2-u1-C28","difficulty":2,"kind":"mc","stem":"서평에 꼭 들어갈 내용이 아닌 것은 어느 것인가요?","options":[{"t":"책을 산 가게의 이름","correct":true},{"t":"인상적인 부분과 그 까닭","mis":"K5-2-u1-X25"},{"t":"책에 대한 평가","mis":"K5-2-u1-X26"},{"t":"간단한 줄거리","mis":"K5-2-u1-X25"}],"explanation":["서평에 들어가요.","서평에 들어가요.","서평에 들어가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#15','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C34',2,'mc','auto','「이달의 책」 후보로 가장 알맞지 않은 책은 어느 것인가요?',ARRAY['K5-2-u1-X31']::text[],false,'{"seq":15,"concept":"K5-2-u1-C34","difficulty":2,"kind":"mc","stem":"「이달의 책」 후보로 가장 알맞지 않은 책은 어느 것인가요?","options":[{"t":"어려운 낱말이 가득해 반에서 한두 명만 읽을 수 있는 책","correct":true},{"t":"친구와의 우정을 다룬 흥미로운 동화","mis":"K5-2-u1-X31"},{"t":"끝까지 하는 마음을 알려 주는 이야기","mis":"K5-2-u1-X31"},{"t":"누구나 읽기 쉬운 따뜻한 이야기","mis":"K5-2-u1-X31"}],"explanation":["흥미로운 이야기는 좋아요.","교훈을 주는 이야기는 좋아요.","너무 어려운 책은 피해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#16','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C40',2,'blank','auto','「도서관 책을 과학 · 역사 · 동화로 (     )」에 들어갈 낱말은 무엇인가요?',ARRAY['K5-2-u1-X36']::text[],false,'{"seq":16,"concept":"K5-2-u1-C40","difficulty":2,"kind":"blank","stem":"「도서관 책을 과학 · 역사 · 동화로 (     )」에 들어갈 낱말은 무엇인가요?","options":[{"t":"분류하다","correct":true},{"t":"분배하다","mis":"K5-2-u1-X36"},{"t":"분석하다","mis":"K5-2-u1-X36"},{"t":"분리수거하다","mis":"K5-2-u1-X36"}],"explanation":["나누어 주는 게 아니에요.","살피는 게 아니에요.","종류별로 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#17','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C10',3,'mc','auto','「운동장 그림자」의 말하는 이의 마음으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X07']::text[],false,'{"seq":17,"concept":"K5-2-u1-C10","difficulty":3,"kind":"mc","stem":"「운동장 그림자」의 말하는 이의 마음으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"하루 종일 함께하는 그림자가 친구처럼 반갑고 든든한 마음","correct":true},{"t":"그림자가 무서운 마음","mis":"K5-2-u1-X07"},{"t":"그림자가 귀찮은 마음","mis":"K5-2-u1-X07"},{"t":"운동장이 싫은 마음","mis":"K5-2-u1-X07"}],"explanation":["무섭다는 말은 없어요.","귀찮다는 말은 없어요.","마지막 연에서 친구라고 했어요."],"asset":{"type":"passage","lines":["아침 운동장에선 / 내 그림자가 나보다 길다","점심 운동장에선 / 그림자가 발밑에 쪼그려 앉고","저녁 운동장에선 / 그림자가 먼저 집으로 달려간다","나는 하루 종일 / 나를 따라다니는 친구가 있다"],"title":"시 「운동장 그림자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#18','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C16',3,'mc','auto','「종이비행기」를 모둠이 나누어 낭송할 때 가장 알맞은 계획은 어느 것인가요?',ARRAY['K5-2-u1-X10']::text[],false,'{"seq":18,"concept":"K5-2-u1-C16","difficulty":3,"kind":"mc","stem":"「종이비행기」를 모둠이 나누어 낭송할 때 가장 알맞은 계획은 어느 것인가요?","options":[{"t":"마지막 줄 「네가 접었다는 게 중요해」를 모두 함께 힘주어 천천히 읽는다","correct":true},{"t":"한 사람이 모든 줄을 빠르게 읽는다","mis":"K5-2-u1-X10"},{"t":"마지막 줄만 빼고 읽는다","mis":"K5-2-u1-X10"},{"t":"모든 줄을 같은 크기로 읽는다","mis":"K5-2-u1-X10"}],"explanation":["나누어 맡아요.","하고 싶은 말이 마지막 줄에 있어요.","강약을 살려요."],"asset":{"type":"passage","lines":["접는 선이 삐뚤어도 괜찮아","처음 접은 한 줄만 기억하면","너의 비행기는 날 수 있어","멀리 가도 좋고 / 빙글 돌아와도 좋아","네가 접었다는 게 중요해"],"title":"시 「종이비행기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#19','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C25',3,'error','auto','「유관순」을 읽고 만든 질문이에요. 인상적인 부분을 중심으로 만든 질문이 아닌 것은 어느 것인가요?',ARRAY['K5-2-u1-X23','K5-2-u1-X25']::text[],false,'{"seq":19,"concept":"K5-2-u1-C25","difficulty":3,"kind":"error","stem":"「유관순」을 읽고 만든 질문이에요. 인상적인 부분을 중심으로 만든 질문이 아닌 것은 어느 것인가요?","options":[{"t":"「충청남도는 어디에 있나요?」","correct":true,"mis_target":"K5-2-u1-X23"},{"t":"「사람들 앞에서 외칠 때 떨리지 않았나요?」","mis":"K5-2-u1-X25"},{"t":"「고향 사람들에게 글을 가르치며 무엇을 바랐나요?」","mis":"K5-2-u1-X25"}],"explanation":["장면에서 나온 질문이에요.","장면에서 나온 질문이에요.","인물의 마음과 관계없는 질문이에요."],"asset":{"type":"passage","lines":["1902년, 유관순은 충청남도의 작은 마을에서 태어났어요.","아버지는 「나라의 힘을 기르려면 새 학문을 배워야 한다」며","딸을 서울의 이화학당에 보냈어요.","유관순은 방학이면 고향에 내려가 우리글을 모르는 마을 사람들에게 글을 가르쳤어요.","1919년 3월 1일, 유관순도 친구들과 거리에 나가 「대한 독립 만세」를 불렀어요."],"title":"전기문 「유관순」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#20','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C30',3,'error','auto','「등대 아래 도서관」의 평가로 쓴 문장이에요. 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u1-X26','K5-2-u1-X30']::text[],false,'{"seq":20,"concept":"K5-2-u1-C30","difficulty":3,"kind":"error","stem":"「등대 아래 도서관」의 평가로 쓴 문장이에요. 알맞지 않은 것은 어느 것인가요?","options":[{"t":"「완벽한 책이다. 아쉬운 점은 쓰면 안 된다.」","correct":true,"mis_target":"K5-2-u1-X26"},{"t":"「작은 일을 끝까지 해내는 마음이 잘 보여 책을 아끼는 친구에게 권한다.」","mis":"K5-2-u1-X30"},{"t":"「할머니 이야기가 더 나오지 않아 아쉽다.」","mis":"K5-2-u1-X30"}],"explanation":["까닭과 추천이 있어요.","아쉬운 점도 평가예요.","좋은 점만 쓰려 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#21','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C18',3,'mc','auto','하람이가 도윤이의 말을 끝까지 들었다면 얻을 수 있었던 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X02','K5-2-u1-X15','K5-2-u1-X06']::text[],false,'{"seq":21,"concept":"K5-2-u1-C18","difficulty":3,"kind":"mc","stem":"하람이가 도윤이의 말을 끝까지 들었다면 얻을 수 있었던 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"마지막 연을 외로울 때 곁을 지켜 주는 친구 이야기로 새롭게 읽게 된다","correct":true},{"t":"셋째 연이 정답이라는 확신","mis":"K5-2-u1-X02"},{"t":"도윤이가 틀렸다는 증거","mis":"K5-2-u1-X15"},{"t":"시를 다시 읽지 않아도 된다는 생각","mis":"K5-2-u1-X06"}],"explanation":["정답 연은 없어요.","틀린 사람은 없어요.","다른 의견이 생각을 넓혀요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"나는 셋째 연이 인상적이야. 그림자가 먼저 집으로 달려간다니 재미있어."},{"who":"도윤","text":"나는 마지막 연! 혼자 있을 때도 그림자가 친구 같았던 적이 있거든."},{"who":"하람","text":"뭐야, 그건 시랑 상관없는 네 이야기잖아."},{"who":"도윤","text":"내 경험이 떠올라서 고른 거야. 그것도 까닭이 되지 않을까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#22','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C39',3,'error','auto','친구들이 고른 인상적인 문장과 까닭이에요. 알맞지 않은 생각은 어느 것인가요?',ARRAY['K5-2-u1-X35','K5-2-u1-X08','K5-2-u1-X01']::text[],false,'{"seq":22,"concept":"K5-2-u1-C39","difficulty":3,"kind":"error","stem":"친구들이 고른 인상적인 문장과 까닭이에요. 알맞지 않은 생각은 어느 것인가요?","options":[{"t":"「〈괜찮아〉는 너무 짧고 쉬워서 인상적인 문장이 될 수 없어.」","correct":true,"mis_target":"K5-2-u1-X35"},{"t":"「〈괜찮아〉가 속상할 때 나를 다독이던 엄마 말 같아서 골랐어.」","mis":"K5-2-u1-X08"},{"t":"「〈사뿐사뿐 디뎌야 해〉에서 말을 조심하자는 깨달음이 생겼어.」","mis":"K5-2-u1-X01"}],"explanation":["경험과 이어진 까닭이에요.","깨달음이 까닭이에요.","짧은 문장도 인상적일 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#23','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C8',4,'essay','teacher','하람이가 「그건 시랑 상관없는 네 이야기잖아」라고 했을 때, 도윤이 편에서 해 줄 말을 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u1-C8","difficulty":4,"kind":"essay","stem":"하람이가 「그건 시랑 상관없는 네 이야기잖아」라고 했을 때, 도윤이 편에서 해 줄 말을 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 도윤이가 고른 마지막 연은 「하루 종일 / 나를 따라다니는 친구가 있다」이다. 혼자 있을 때 그림자가 친구 같았던 경험은 바로 이 연의 내용과 이어진다. 시 속 일과 닮은 내 경험이 떠올라 공감하는 것도 인상적인 까닭이 될 수 있으니, 도윤이의 까닭도 들어 볼 만하다.","scoring_points":["도윤이가 고른 연을 짚었는가","경험이 시와 이어짐을 썼는가","경험도 까닭이 된다는 뜻을 썼는가"]},"explanation":["도윤이가 고른 연을 봐요.","경험과 시를 이어요.","공감도 까닭임을 말해요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"나는 셋째 연이 인상적이야. 그림자가 먼저 집으로 달려간다니 재미있어."},{"who":"도윤","text":"나는 마지막 연! 혼자 있을 때도 그림자가 친구 같았던 적이 있거든."},{"who":"하람","text":"뭐야, 그건 시랑 상관없는 네 이야기잖아."},{"who":"도윤","text":"내 경험이 떠올라서 고른 거야. 그것도 까닭이 되지 않을까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#24','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C30',4,'essay','teacher','「낡은 책이 다시 숨 쉬는 곳」을 읽고 이 서평의 좋은 점 한 가지와 더 보태면 좋을 점 한 가지를 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u1-C30","difficulty":4,"kind":"essay","stem":"「낡은 책이 다시 숨 쉬는 곳」을 읽고 이 서평의 좋은 점 한 가지와 더 보태면 좋을 점 한 가지를 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 좋은 점 — 인상적인 부분으로 젖은 책을 말리는 장면을 고르고, 작은 일을 끝까지 해내는 마음이 보인다는 까닭을 들어 읽는 사람도 그 장면이 궁금해진다. 보탤 점 — 지은이와 이 책이 어떤 독자를 위한 책인지 책 소개에 더 넣으면 좋겠다. 책을 고를 때 누가 읽기 좋은지 미리 알 수 있기 때문이다.","scoring_points":["좋은 점을 까닭과 함께 썼는가","보탤 점을 까닭과 함께 썼는가","서평에 들어갈 내용과 이어 썼는가"]},"explanation":["잘된 칸을 찾아요.","빠진 칸을 찾아요.","까닭을 붙여요."],"asset":{"type":"passage","lines":["〔제목〕 낡은 책이 다시 숨 쉬는 곳","「등대 아래 도서관」은 바닷가 마을 아이가 등대 아래 낡은 도서관을 지키는 이야기예요.","해솔이는 사서 할머니에게 찢어진 책을 고치는 법을 배우고, 친구들과 도서관을 다시 열어요.","가장 인상적인 부분은 해솔이가 젖은 책을 한 장씩 말리는 장면이에요.","작은 일을 끝까지 해내는 마음이 잘 보이기 때문이에요.","책을 아끼는 마음을 기르고 싶은 친구들에게 권해요.","다만 할머니가 왜 혼자 도서관을 지켰는지가 나오지 않아 조금 아쉬워요."],"title":"서평 고쳐 쓴 글 「등대 아래 도서관」 (지어낸 책)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#25','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C31',4,'essay','teacher','독서 감상문과 서평의 차이를 쓰고, 친구에게 책을 추천하려면 어느 글이 더 알맞은지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u1-C31","difficulty":4,"kind":"essay","stem":"독서 감상문과 서평의 차이를 쓰고, 친구에게 책을 추천하려면 어느 글이 더 알맞은지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 독서 감상문은 책을 읽고 떠오른 생각이나 느낌을 자유롭게 쓴 글이고, 서평은 책의 좋은 점이나 아쉬운 점을 평가하고 그렇게 생각한 까닭을 함께 밝힌 글이다. 친구에게 책을 추천하려면 서평이 더 알맞다. 서평에는 누구에게 왜 이 책을 권하는지가 들어 있어 친구가 읽을지 말지 판단하기 쉽기 때문이다.","scoring_points":["두 글의 차이를 썼는가","어느 글이 알맞은지 골랐는가","까닭을 썼는가"]},"explanation":["두 글을 견줘요.","추천에 맞는 글을 골라요.","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#1','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C39',1,'blank','auto','인상적인 문장은 길고 어려운 문장이 아니라 (     ) 문장이에요.',ARRAY['K5-2-u1-X35','K5-2-u1-X02']::text[],false,'{"seq":1,"concept":"K5-2-u1-C39","difficulty":1,"kind":"blank","stem":"인상적인 문장은 길고 어려운 문장이 아니라 (     ) 문장이에요.","options":[{"t":"마음이 움직이거나 깨달음이 생긴","correct":true},{"t":"어려운 낱말이 가장 많은","mis":"K5-2-u1-X35"},{"t":"책에서 가장 긴","mis":"K5-2-u1-X35"},{"t":"선생님이 밑줄 그어 준","mis":"K5-2-u1-X02"}],"explanation":["낱말의 어려움이 기준이 아니에요.","길이가 기준이 아니에요.","정해 준 문장이 따로 있지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#2','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C2',1,'ox','auto','작품의 인상적인 부분은 사람마다 다를 수 있어요.',ARRAY['K5-2-u1-X02']::text[],false,'{"seq":2,"concept":"K5-2-u1-C2","difficulty":1,"kind":"ox","stem":"작품의 인상적인 부분은 사람마다 다를 수 있어요.","answer":"O","reason_options":[{"t":"같은 작품도 저마다의 경험과 생각에 따라 마음에 남는 곳이 다르기 때문에","correct":true},{"t":"작품마다 정답인 부분이 하나씩 있기 때문에","mis":"K5-2-u1-X02"}],"mis":"K5-2-u1-X02","explanation":["사람마다 달라요.","정답이 하나가 아니에요.","그래서 의견을 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#3','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C40',1,'mc','auto','「분류하다」를 알맞게 쓴 문장은 어느 것인가요?',ARRAY['K5-2-u1-X36']::text[],false,'{"seq":3,"concept":"K5-2-u1-C40","difficulty":1,"kind":"mc","stem":"「분류하다」를 알맞게 쓴 문장은 어느 것인가요?","options":[{"t":"식물을 잎의 모양에 따라 분류했다.","correct":true},{"t":"우승 상금을 고르게 분류했다.","mis":"K5-2-u1-X36"},{"t":"실험에서 얻은 자료를 꼼꼼히 분류했다.","mis":"K5-2-u1-X36"},{"t":"간식을 친구들에게 분류했다.","mis":"K5-2-u1-X36"}],"explanation":["상금은 분배해요.","자료를 살필 때는 분석해요.","간식은 나누어 주니 분배해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#4','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C40',1,'ox','auto','「인물의 성격을 분배하다」는 낱말을 알맞게 쓴 문장이에요.',ARRAY['K5-2-u1-X36']::text[],false,'{"seq":4,"concept":"K5-2-u1-C40","difficulty":1,"kind":"ox","stem":"「인물의 성격을 분배하다」는 낱말을 알맞게 쓴 문장이에요.","answer":"X","reason_options":[{"t":"성격을 자세히 살피는 일이므로 「분석하다」가 알맞기 때문에","correct":true},{"t":"「분배하다」는 무엇이든 나눌 때 쓰기 때문에","mis":"K5-2-u1-X36"}],"mis":"K5-2-u1-X36","explanation":["몫으로 나누어 주는 일이 아니에요.","자세히 살피는 일이에요.","분석하다가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#5','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C20',1,'mc','auto','전기문을 읽으면 얻을 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X18','K5-2-u1-X24']::text[],false,'{"seq":5,"concept":"K5-2-u1-C20","difficulty":1,"kind":"mc","stem":"전기문을 읽으면 얻을 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"실제 인물의 삶에서 감동과 교훈","correct":true},{"t":"지어낸 마법 이야기의 재미","mis":"K5-2-u1-X18"},{"t":"날씨를 맞히는 방법","mis":"K5-2-u1-X24"},{"t":"책값을 아끼는 방법","mis":"K5-2-u1-X24"}],"explanation":["지어낸 이야기가 아니에요.","날씨와 관계없어요.","인물의 삶에서 배워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#6','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C27',1,'mc','auto','서평 「낡은 책이 다시 숨 쉬는 곳」에서 평가가 드러난 문장은 어느 것인가요?',ARRAY['K5-2-u1-X25','K5-2-u1-X29']::text[],false,'{"seq":6,"concept":"K5-2-u1-C27","difficulty":1,"kind":"mc","stem":"서평 「낡은 책이 다시 숨 쉬는 곳」에서 평가가 드러난 문장은 어느 것인가요?","options":[{"t":"「할머니가 왜 혼자 도서관을 지켰는지가 나오지 않아 조금 아쉬워요.」","correct":true},{"t":"「바닷가 마을 아이가 등대 아래 낡은 도서관을 지키는 이야기예요.」","mis":"K5-2-u1-X25"},{"t":"「친구들과 도서관을 다시 열어요.」","mis":"K5-2-u1-X25"},{"t":"제목 「낡은 책이 다시 숨 쉬는 곳」","mis":"K5-2-u1-X29"}],"explanation":["책 소개예요.","줄거리예요.","아쉬운 점과 까닭이 있어요."],"asset":{"type":"passage","lines":["〔제목〕 낡은 책이 다시 숨 쉬는 곳","「등대 아래 도서관」은 바닷가 마을 아이가 등대 아래 낡은 도서관을 지키는 이야기예요.","해솔이는 사서 할머니에게 찢어진 책을 고치는 법을 배우고, 친구들과 도서관을 다시 열어요.","가장 인상적인 부분은 해솔이가 젖은 책을 한 장씩 말리는 장면이에요.","작은 일을 끝까지 해내는 마음이 잘 보이기 때문이에요.","책을 아끼는 마음을 기르고 싶은 친구들에게 권해요.","다만 할머니가 왜 혼자 도서관을 지켰는지가 나오지 않아 조금 아쉬워요."],"title":"서평 고쳐 쓴 글 「등대 아래 도서관」 (지어낸 책)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#7','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C6',1,'mc','auto','「종이비행기」에서 비행기가 날 수 있다고 한 조건은 무엇인가요?',ARRAY['K5-2-u1-X06']::text[],false,'{"seq":7,"concept":"K5-2-u1-C6","difficulty":1,"kind":"mc","stem":"「종이비행기」에서 비행기가 날 수 있다고 한 조건은 무엇인가요?","options":[{"t":"처음 접은 한 줄을 기억하는 것","correct":true},{"t":"선을 반듯하게 접는 것","mis":"K5-2-u1-X06"},{"t":"멀리 던지는 것","mis":"K5-2-u1-X06"},{"t":"비싼 종이를 쓰는 것","mis":"K5-2-u1-X06"}],"explanation":["삐뚤어도 괜찮다고 했어요.","멀리 가는 건 조건이 아니에요.","둘째 줄에 나와요."],"asset":{"type":"passage","lines":["접는 선이 삐뚤어도 괜찮아","처음 접은 한 줄만 기억하면","너의 비행기는 날 수 있어","멀리 가도 좋고 / 빙글 돌아와도 좋아","네가 접었다는 게 중요해"],"title":"시 「종이비행기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#8','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C35',1,'mc','auto','친구의 추천 까닭을 듣고 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X16','K5-2-u1-X34']::text[],false,'{"seq":8,"concept":"K5-2-u1-C35","difficulty":1,"kind":"mc","stem":"친구의 추천 까닭을 듣고 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"나와 같은 점과 다른 점을 견주어 본다","correct":true},{"t":"바로 내 책이 더 좋다고 말한다","mis":"K5-2-u1-X16"},{"t":"듣지 않고 내 차례를 기다린다","mis":"K5-2-u1-X16"},{"t":"친구 책 제목만 적는다","mis":"K5-2-u1-X34"}],"explanation":["견주기 전에 정하지 않아요.","들어야 견줘요.","제목만으로는 부족해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#9','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C3',2,'mc','auto','인상적인 부분을 말하는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X03','K5-2-u1-X04','K5-2-u1-X02']::text[],false,'{"seq":9,"concept":"K5-2-u1-C3","difficulty":2,"kind":"mc","stem":"인상적인 부분을 말하는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"고른 부분을 말하고 그 부분이 인상적인 까닭을 작품과 이어 말한다","correct":true},{"t":"고른 부분만 짧게 말한다","mis":"K5-2-u1-X03"},{"t":"작품과 상관없는 내 하루 일을 말한다","mis":"K5-2-u1-X04"},{"t":"친구가 고른 부분을 따라 말한다","mis":"K5-2-u1-X02"}],"explanation":["까닭이 빠졌어요.","작품과 이어지지 않아요.","내 생각을 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#10','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C8',2,'error','auto','「종이비행기」를 읽고 친구들이 말한 까닭이에요. 알맞지 않은 생각은 어느 것인가요?',ARRAY['K5-2-u1-X08','K5-2-u1-X07']::text[],false,'{"seq":10,"concept":"K5-2-u1-C8","difficulty":2,"kind":"error","stem":"「종이비행기」를 읽고 친구들이 말한 까닭이에요. 알맞지 않은 생각은 어느 것인가요?","options":[{"t":"「내 경험으로 고른 건 시와 상관없어서 말하면 안 돼.」","correct":true,"mis_target":"K5-2-u1-X08"},{"t":"「나도 실수할 때 괜찮다는 말을 듣고 싶었어서 첫째 줄을 골랐어.」","mis":"K5-2-u1-X08"},{"t":"「〈빙글 돌아와도 좋아〉에서 실패해도 괜찮다는 느낌이 들었어.」","mis":"K5-2-u1-X07"}],"explanation":["경험과 이어진 까닭이에요.","표현과 이어진 까닭이에요.","내 경험도 까닭이 돼요."],"asset":{"type":"passage","lines":["접는 선이 삐뚤어도 괜찮아","처음 접은 한 줄만 기억하면","너의 비행기는 날 수 있어","멀리 가도 좋고 / 빙글 돌아와도 좋아","네가 접었다는 게 중요해"],"title":"시 「종이비행기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#11','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C7',2,'mc','auto','「운동장 그림자」에서 독특하고 재미있는 표현은 어느 것인가요?',ARRAY['K5-2-u1-X01']::text[],false,'{"seq":11,"concept":"K5-2-u1-C7","difficulty":2,"kind":"mc","stem":"「운동장 그림자」에서 독특하고 재미있는 표현은 어느 것인가요?","options":[{"t":"「그림자가 먼저 집으로 달려간다」","correct":true},{"t":"「아침 운동장에선」","mis":"K5-2-u1-X01"},{"t":"「저녁 운동장에선」","mis":"K5-2-u1-X01"},{"t":"「나는 하루 종일」","mis":"K5-2-u1-X01"}],"explanation":["때를 나타낸 말이에요.","때를 나타낸 말이에요.","그림자를 사람처럼 나타냈어요."],"asset":{"type":"passage","lines":["아침 운동장에선 / 내 그림자가 나보다 길다","점심 운동장에선 / 그림자가 발밑에 쪼그려 앉고","저녁 운동장에선 / 그림자가 먼저 집으로 달려간다","나는 하루 종일 / 나를 따라다니는 친구가 있다"],"title":"시 「운동장 그림자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#12','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C21',2,'error','auto','「세종 대왕」을 읽고 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u1-X19','K5-2-u1-X18','K5-2-u1-X21']::text[],false,'{"seq":12,"concept":"K5-2-u1-C21","difficulty":2,"kind":"error","stem":"「세종 대왕」을 읽고 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「혼잣말 장면은 누가 옆에서 받아 적은 거니까 사실이야.」","correct":true,"mis_target":"K5-2-u1-X19"},{"t":"「훈민정음을 만든 것은 역사적 사실이야.」","mis":"K5-2-u1-X18"},{"t":"「촛불 장면은 작가가 그때 마음을 상상해 그린 것 같아.」","mis":"K5-2-u1-X21"}],"explanation":["사실을 바르게 말했어요.","꾸민 부분을 알아봤어요.","꾸민 장면을 사실로 단정했어요."],"asset":{"type":"passage","lines":["세종 대왕은 조선의 넷째 임금이에요.","그 무렵 백성들은 어려운 한자를 몰라 하고 싶은 말을 글로 남기지 못했어요.","세종 대왕은 학자들과 함께 오랫동안 연구하여 우리글 훈민정음을 만들었어요.","어떤 책에서는 세종 대왕이 밤늦도록 촛불 아래에서 글자를 다듬으며","「백성이 쉽게 익혀 날마다 편히 쓰면 좋겠구나」라고 혼잣말을 했다고 그려요."],"title":"짧은 전기문 「세종 대왕」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#13','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C23',2,'mc','auto','「밤늦도록 촛불 아래에서 글자를 다듬었다」는 장면에서 짐작할 수 있는 마음은 어느 것인가요?',ARRAY['K5-2-u1-X21']::text[],false,'{"seq":13,"concept":"K5-2-u1-C23","difficulty":2,"kind":"mc","stem":"「밤늦도록 촛불 아래에서 글자를 다듬었다」는 장면에서 짐작할 수 있는 마음은 어느 것인가요?","options":[{"t":"백성을 위해 쉬운 글자를 꼭 만들고 싶은 마음","correct":true},{"t":"잠이 오지 않아 심심한 마음","mis":"K5-2-u1-X21"},{"t":"촛불을 아끼고 싶은 마음","mis":"K5-2-u1-X21"},{"t":"학자들을 혼내고 싶은 마음","mis":"K5-2-u1-X21"}],"explanation":["백성의 어려움과 이어 봐요.","촛불이 중심이 아니에요.","상황과 행동을 이어 짐작해요."],"asset":{"type":"passage","lines":["세종 대왕은 조선의 넷째 임금이에요.","그 무렵 백성들은 어려운 한자를 몰라 하고 싶은 말을 글로 남기지 못했어요.","세종 대왕은 학자들과 함께 오랫동안 연구하여 우리글 훈민정음을 만들었어요.","어떤 책에서는 세종 대왕이 밤늦도록 촛불 아래에서 글자를 다듬으며","「백성이 쉽게 익혀 날마다 편히 쓰면 좋겠구나」라고 혼잣말을 했다고 그려요."],"title":"짧은 전기문 「세종 대왕」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#14','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C28',2,'blank','auto','서평에 들어갈 내용은 제목, 책 소개, 줄거리, 인상적인 부분과 그 까닭, (     )예요.',ARRAY['K5-2-u1-X25']::text[],false,'{"seq":14,"concept":"K5-2-u1-C28","difficulty":2,"kind":"blank","stem":"서평에 들어갈 내용은 제목, 책 소개, 줄거리, 인상적인 부분과 그 까닭, (     )예요.","options":[{"t":"책에 대한 평가","correct":true},{"t":"책의 값","mis":"K5-2-u1-X25"},{"t":"지은이의 사진","mis":"K5-2-u1-X25"},{"t":"다 읽은 날짜","mis":"K5-2-u1-X25"}],"explanation":["값은 들어가지 않아요.","사진은 들어가지 않아요.","좋은 점 · 아쉬운 점 · 추천을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#15','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C37',2,'mc','auto','「이달의 책」으로 뽑히지 않은 책을 대하는 태도로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X33']::text[],false,'{"seq":15,"concept":"K5-2-u1-C37","difficulty":2,"kind":"mc","stem":"「이달의 책」으로 뽑히지 않은 책을 대하는 태도로 알맞은 것은 어느 것인가요?","options":[{"t":"다음 달 후보로 남기고 목록을 함께 나눈다","correct":true},{"t":"나쁜 책이라고 알린다","mis":"K5-2-u1-X33"},{"t":"추천한 친구의 의견은 쓸모없었다고 한다","mis":"K5-2-u1-X33"},{"t":"다시는 말하지 않는다","mis":"K5-2-u1-X33"}],"explanation":["뽑히지 않았다고 나쁜 책이 아니에요.","추천 까닭도 쓸모가 있어요.","다양한 의견을 인정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#16','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C40',2,'error','auto','낱말을 쓴 문장이에요. 알맞지 않은 문장은 어느 것인가요?',ARRAY['K5-2-u1-X36']::text[],false,'{"seq":16,"concept":"K5-2-u1-C40","difficulty":2,"kind":"error","stem":"낱말을 쓴 문장이에요. 알맞지 않은 문장은 어느 것인가요?","options":[{"t":"「간식을 모둠마다 고르게 분석했다.」","correct":true,"mis_target":"K5-2-u1-X36"},{"t":"「모은 자료를 시대별로 분류했다.」","mis":"K5-2-u1-X36"},{"t":"「이야기 속 인물의 성격을 분석했다.」","mis":"K5-2-u1-X36"}],"explanation":["바르게 썼어요.","바르게 썼어요.","나누어 주는 일은 「분배하다」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#17','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C10',3,'ox','auto','「종이비행기」에서는 한 구절이 아니라 시 전체의 다정한 분위기를 인상적인 부분으로 말할 수 있어요.',ARRAY['K5-2-u1-X07']::text[],false,'{"seq":17,"concept":"K5-2-u1-C10","difficulty":3,"kind":"ox","stem":"「종이비행기」에서는 한 구절이 아니라 시 전체의 다정한 분위기를 인상적인 부분으로 말할 수 있어요.","answer":"O","reason_options":[{"t":"말하는 이의 마음이나 시 전체의 분위기도 인상적인 부분이 되기 때문에","correct":true},{"t":"인상적인 부분은 한 구절에서만 골라야 하기 때문에","mis":"K5-2-u1-X07"}],"mis":"K5-2-u1-X07","explanation":["분위기도 돼요.","구절에만 머물지 않아요.","시 전체에서 느낀 것도 돼요."],"asset":{"type":"passage","lines":["접는 선이 삐뚤어도 괜찮아","처음 접은 한 줄만 기억하면","너의 비행기는 날 수 있어","멀리 가도 좋고 / 빙글 돌아와도 좋아","네가 접었다는 게 중요해"],"title":"시 「종이비행기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#18','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C15',3,'ox','auto','「괜찮아, 나」와 「운동장 그림자」처럼 시 속 모습이나 마음은 연마다 바뀔 수 있어요.',ARRAY['K5-2-u1-X14']::text[],false,'{"seq":18,"concept":"K5-2-u1-C15","difficulty":3,"kind":"ox","stem":"「괜찮아, 나」와 「운동장 그림자」처럼 시 속 모습이나 마음은 연마다 바뀔 수 있어요.","answer":"O","reason_options":[{"t":"연을 따라 읽으면 마음이나 모습이 어떻게 바뀌는지 보이기 때문에","correct":true},{"t":"시는 처음 연에서 모든 것이 정해지기 때문에","mis":"K5-2-u1-X14"}],"mis":"K5-2-u1-X14","explanation":["연마다 따라가요.","처음 연이 다가 아니에요.","흐름을 보며 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#19','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C24',3,'ox','auto','이야기에서는 사건의 흐름이나 인물의 변화도 인상적인 부분이 될 수 있어요.',ARRAY['K5-2-u1-X22']::text[],false,'{"seq":19,"concept":"K5-2-u1-C24","difficulty":3,"kind":"ox","stem":"이야기에서는 사건의 흐름이나 인물의 변화도 인상적인 부분이 될 수 있어요.","answer":"O","reason_options":[{"t":"이야기는 인물 · 사건 · 때와 곳이 작품을 이해하는 데 영향을 주기 때문에","correct":true},{"t":"이야기에서는 가장 큰 사건 한 장면만 인상적이기 때문에","mis":"K5-2-u1-X22"}],"mis":"K5-2-u1-X22","explanation":["흐름도 돼요.","변화도 돼요.","여러 가지를 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#20','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C33',3,'mc','auto','서평을 돌려 읽은 친구가 「인상적인 부분은 있는데 왜 인상적인지가 없어」라고 했을 때 고쳐 쓰는 방법은 어느 것인가요?',ARRAY['K5-2-u1-X30','K5-2-u1-X25']::text[],false,'{"seq":20,"concept":"K5-2-u1-C33","difficulty":3,"kind":"mc","stem":"서평을 돌려 읽은 친구가 「인상적인 부분은 있는데 왜 인상적인지가 없어」라고 했을 때 고쳐 쓰는 방법은 어느 것인가요?","options":[{"t":"그 장면이 왜 마음에 남았는지 까닭을 한 문장 보탠다","correct":true},{"t":"인상적인 부분을 지운다","mis":"K5-2-u1-X30"},{"t":"줄거리를 더 길게 쓴다","mis":"K5-2-u1-X25"},{"t":"친구 의견은 듣지 않고 그대로 둔다","mis":"K5-2-u1-X30"}],"explanation":["지우면 중심이 빠져요.","줄거리가 문제가 아니에요.","받은 의견을 살려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#21','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C17',3,'ox','auto','배경지식이 다르면 같은 시에서도 인상적인 까닭이 달라질 수 있어요.',ARRAY['K5-2-u1-X15']::text[],false,'{"seq":21,"concept":"K5-2-u1-C17","difficulty":3,"kind":"ox","stem":"배경지식이 다르면 같은 시에서도 인상적인 까닭이 달라질 수 있어요.","answer":"O","reason_options":[{"t":"아는 것이 다르면 같은 표현에서도 떠오르는 생각이 다르기 때문에","correct":true},{"t":"배경지식은 시 감상과 관계없기 때문에","mis":"K5-2-u1-X15"}],"mis":"K5-2-u1-X15","explanation":["아는 것이 생각을 바꿔요.","경험 · 관심사 · 배경지식","그래서 서로 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#22','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C26',3,'ox','auto','오래전 인물의 전기문도 오늘 나의 생활에 도움을 줄 수 있어요.',ARRAY['K5-2-u1-X24']::text[],false,'{"seq":22,"concept":"K5-2-u1-C26","difficulty":3,"kind":"ox","stem":"오래전 인물의 전기문도 오늘 나의 생활에 도움을 줄 수 있어요.","answer":"O","reason_options":[{"t":"인물의 삶에서 본받을 점을 찾아 지금의 삶과 이어 볼 수 있기 때문에","correct":true},{"t":"옛날 인물은 지금과 사는 모습이 달라 배울 것이 없기 때문에","mis":"K5-2-u1-X24"}],"mis":"K5-2-u1-X24","explanation":["본받을 점을 찾아요.","오늘과 이어요.","시대가 달라도 배울 게 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#23','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C39',4,'essay','teacher','「종이비행기」나 이 단원에서 읽은 시에서 가장 인상적인 문장 하나를 골라, 내 경험과 이어 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u1-C39","difficulty":4,"kind":"essay","stem":"「종이비행기」나 이 단원에서 읽은 시에서 가장 인상적인 문장 하나를 골라, 내 경험과 이어 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 「네가 접었다는 게 중요해」가 가장 인상적이다. 미술 시간에 만든 작품이 친구 것보다 못나 보여 속상했을 때, 선생님이 끝까지 만든 것이 멋지다고 해 주셔서 힘이 났던 일이 떠올랐다. 잘하고 못하고보다 해 보는 것이 중요하다는 깨달음을 주어서 이 문장을 골랐다.","scoring_points":["문장을 골랐는가","내 경험을 썼는가","경험과 문장을 이어 까닭을 썼는가"]},"explanation":["한 문장을 골라요.","떠오른 경험을 써요.","둘을 이어요."],"asset":{"type":"passage","lines":["접는 선이 삐뚤어도 괜찮아","처음 접은 한 줄만 기억하면","너의 비행기는 날 수 있어","멀리 가도 좋고 / 빙글 돌아와도 좋아","네가 접었다는 게 중요해"],"title":"시 「종이비행기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#24','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C36',4,'essay','teacher','모둠에서 「이달의 책」을 고르다 의견이 갈렸어요. 기준을 하나 세워 쓰고, 그 기준으로 조정하는 과정과 뽑히지 않은 책을 대하는 방법을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u1-C36","difficulty":4,"kind":"essay","stem":"모둠에서 「이달의 책」을 고르다 의견이 갈렸어요. 기준을 하나 세워 쓰고, 그 기준으로 조정하는 과정과 뽑히지 않은 책을 대하는 방법을 쓰세요.","answer_guide":{"answer":"예: 기준 — 「반 친구들 모두가 흥미롭게 읽을 수 있는가」. 먼저 친구들의 추천 까닭을 끝까지 듣고, 각 책을 이 기준에 대어 견준다. 누구나 읽기 쉽고 이야기 나눌 거리가 많은 책을 고른다. 뽑히지 않은 책은 목록에 적어 다음 달 후보로 남기고, 추천한 친구 덕분에 새 책을 알게 되었다고 고마움을 전한다.","scoring_points":["기준을 세웠는가","기준에 대어 조정하는 과정을 썼는가","뽑히지 않은 책을 존중하는 방법을 썼는가"]},"explanation":["기준을 정해요.","대어 견줘요.","다른 의견을 존중해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#25','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C5',4,'essay','teacher','이 단원에서 한 활동(시 · 이야기 · 서평 · 「이달의 책」) 가운데 가장 기억에 남는 활동 하나를 고르고, 그 활동에서 배운 점과 앞으로 책을 읽을 때 해 보고 싶은 일을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u1-C5","difficulty":4,"kind":"essay","stem":"이 단원에서 한 활동(시 · 이야기 · 서평 · 「이달의 책」) 가운데 가장 기억에 남는 활동 하나를 고르고, 그 활동에서 배운 점과 앞으로 책을 읽을 때 해 보고 싶은 일을 쓰세요.","answer_guide":{"answer":"예: 「이달의 책」 고르기가 가장 기억에 남는다. 내가 추천한 책은 뽑히지 않았지만, 친구들의 추천 까닭을 들으며 몰랐던 책의 좋은 점을 알게 되었고 기준을 정해 의견을 조정하는 방법을 배웠다. 앞으로 책을 읽으면 인상적인 문장과 그 까닭을 공책에 적어 두었다가 친구에게 추천할 때 써 보고 싶다.","scoring_points":["활동을 하나 골랐는가","배운 점을 썼는가","앞으로 해 보고 싶은 일을 썼는가"]},"explanation":["활동을 떠올려요.","배운 점을 써요.","다음 다짐을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
